insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (353, 41, 47, 54, 'سورة فصلت ٤٧ – ٥٤', 'فصلت: سنريهم آياتنا في الآفاق وفي أنفسهم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 353) = $j$[{"lbl": "الآيتان ٤٧ – ٤٨", "q": "۞إِلَيۡهِ يُرَدُّ عِلۡمُ ٱلسَّاعَةِۚ وَمَا تَخۡرُجُ مِن ثَمَرَٰتٖ مِّنۡ أَكۡمَامِهَا وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَيَوۡمَ يُنَادِيهِمۡ أَيۡنَ شُرَكَآءِي قَالُوٓاْ ءَاذَنَّـٰكَ مَامِنَّا مِن شَهِيدٖ ﴿٤٧﴾ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَدۡعُونَ مِن قَبۡلُۖ وَظَنُّواْ مَا لَهُم مِّن مَّحِيصٖ ﴿٤٨﴾", "w": [["إليه يُرَدّ علم الساعة", "إلى الله يُرد علم متى تقوم، إذ لا يعلمها إلا هو."], ["وما تخرج من ثمرات من أكمامها", "من أوعيتها، واحد الأكمام كِمّ، وكُمّ الثوب مخرج اليد."], ["ولا تضع إلا بعلمه", "لا تضع حملها إلا ملابساً بعلم الله المحيط بكل شيء."], ["قالوا آذنّاك", "أعلمناك الآن."], ["ما منا من شهيد", "ليس منا من يشهد بأن لك شريكاً أبداً."], ["وظنّوا ما لهم من محيص", "أيقنوا أنه ما لهم من مهرب من العذاب."]], "m": "يخبر تعالى أن علم الغيب منحصر فيه، فليس لأحد من خلقه علم الغيب، وخاصة علم متى تقوم الساعة، ويخبر عن واسع علمه وأنه محيط بكل الكائنات: فما تخرج من ثمرة من وعائها إلا يعلمها على كثرة الثمار والأشجار، وما تحمل من أنثى بجنين ولا تضعه يوم ولادته أو إسقاطه إلا بعلمه وإذنه. وهذه مظاهر الربوبية المستلزمة للألوهية، ومع هذا يتخذ الجاهلون له شركاء من أحجار وأوثان يعبدونها معه ظلماً وسفهاً. ويوم القيامة يناديهم: أين شركائي الذين كنتم تزعمون؟ فيتبرّؤون منهم ويقولون: أعلمناك الآن أنه ما منا من يشهد بأن لك شريكاً، وغاب عنهم ما كانوا يدعون من قبل، وأيقنوا ما لهم من مهرب من عذاب الله.", "h": ["استئثار الله تعالى بعلم الغيب، وخاصة علم متى تقوم الساعة.", "إحاطة علم الله تعالى بكل شيء، فما تخرج من ثمرة من أوعيتها ولا تحمل من أنثى ولا تضع حملها إلا بعلم الله تعالى وإذنه.", "براءة المشركين يوم القيامة من شركهم، وغياب شركائهم عنهم."], "k": "«وما تخرج من ثمرات من أكمامها إلا بعلمه»… يعلم كل ثمرة تتفتّح؛ أفلا يعلم همّي الذي أخفيه؟"}, {"lbl": "الآيات ٤٩ – ٥١", "q": "لَّا يَسۡـَٔمُ ٱلۡإِنسَٰنُ مِن دُعَآءِ ٱلۡخَيۡرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٞ قَنُوطٞ ﴿٤٩﴾ وَلَئِنۡ أَذَقۡنَٰهُ رَحۡمَةٗ مِّنَّا مِنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ هَٰذَا لِي وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةٗ وَلَئِن رُّجِعۡتُ إِلَىٰ رَبِّيٓ إِنَّ لِي عِندَهُۥ لَلۡحُسۡنَىٰۚ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُواْ بِمَا عَمِلُواْ وَلَنُذِيقَنَّهُم مِّنۡ عَذَابٍ غَلِيظٖ ﴿٥٠﴾ وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٖ ﴿٥١﴾", "w": [["لا يسأم الإنسان من دعاء الخير", "لا يملّ ولا يكلّ من سؤال المال والصحة والعافية."], ["وإن مسّه الشر فيؤوس قنوط", "المرض والفقر وغيرهما، فيؤوس من رحمة الله قنوط ظاهر عليه اليأس."], ["من بعد ضرّاء مسّته", "من بعد شدة أصابته وبلاء نزل به."], ["ليقولنّ هذا لي", "استحققته بعملي ومكانتي."], ["وما أظن الساعة قائمة", "ينكر البعث."], ["إن لي عنده للحسنى", "على فرض صحة ما قالت الرسل من البعث إن لي عند الله الحسنى."], ["أعرض ونأى بجانبه", "أعرض عن الشكر وتباعد متبختراً مختالاً في مشيته."], ["فذو دعاء عريض", "فهو ذو دعاء لربه طويل عريض: يا رب يا رب."]], "m": "يخبر تعالى عن الإنسان الذي لم تزكُ نفسه بالإيمان وصالح الأعمال أنه لا يملّ من دعاء الخير من المال والولد والصحة فلا يشبع منه بحال، وإن مسّه الشر من ضر وفقر فهو يؤوس من الفرج وتبدّل الحال، ظاهر عليه آثار اليأس في منطقه وحاله. ولئن أذاقه الله رحمة من مال وصحة واجتماع شمل من بعد مرض وفقر ليقولنّ لجهله وسفهه: هذا لي، استحققته بمالي ومكانتي، وإذا ذُكّر بالساعة ليرفق أو يتصدّق قال: ما أظن الساعة قائمة، ولئن رُجعت إلى ربي إن لي عنده الحسنى من غنى وجنة إن كانت كما تقول. فلننبئنّ الذين كفروا بما عملوا عند عرضهم علينا، ولنذيقنّهم من عذاب غليظ يخلدون فيه. وإذا أنعمنا على الإنسان بالمال والولد والصحة أعرض عن ذكرنا وشكرنا ونأى بجانبه متبختراً مختالاً، وإذا سلبناه ذلك ومسّه الشر فهو ذو دعاء عريض: يا رب يا رب. وهذا ليس الرجل الأول الذي ييأس ويقنط؛ ذاك كافر، وهذا مؤمن ضعيف الإيمان جاهل لا أدب عنده ولا خلق، وما أكثر هذا النوع في المسلمين اليوم؛ فالأول عائد إلى ظلمة نفسه بالكفر، وهذا عائد إلى سوء تربيته وسوء خلقه.", "h": ["بيان حال الإنسان قبل الإيمان والاستقامة، فإنه يكون أحطّ المخلوقات قدراً وأضعفها شأناً.", "تقرير عقيدة البعث والجزاء بذكر بعض الأحداث فيها.", "ذمّ اليأس والقنوط والكبر والاختيال، والكفر للنعم ونسيان المنعم وعدم شكره."], "k": "«وإذا مسّه الشر فذو دعاء عريض»… هل لا أعرف الله إلا في الشدة؟"}, {"lbl": "الآيات ٥٢ – ٥٤", "q": "قُلۡ أَرَءَيۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ ثُمَّ كَفَرۡتُم بِهِۦ مَنۡ أَضَلُّ مِمَّنۡ هُوَ فِي شِقَاقِۭ بَعِيدٖ ﴿٥٢﴾ سَنُرِيهِمۡ ءَايَٰتِنَا فِي ٱلۡأٓفَاقِ وَفِيٓ أَنفُسِهِمۡ حَتَّىٰ يَتَبَيَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّۗ أَوَلَمۡ يَكۡفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ﴿٥٣﴾ أَلَآ إِنَّهُمۡ فِي مِرۡيَةٖ مِّن لِّقَآءِ رَبِّهِمۡۗ أَلَآ إِنَّهُۥ بِكُلِّ شَيۡءٖ مُّحِيطُۢ ﴿٥٤﴾", "w": [["قل أرأيتم إن كان من عند الله", "أخبروني إن كان القرآن من عند الله كما قال النبي ﷺ."], ["ثم كفرتم به", "بعد العلم أنه من عند الله."], ["من أضلّ ممن هو في شقاق بعيد", "من يكون أضل منكم وأنتم في شقاق بعيد؟ لا أحد."], ["في الآفاق وفي أنفسهم", "في أقطار السماوات والأرض من المخلوقات وأسرار خلقها، وفي أنفسهم من لطائف الصنعة وبدائع الحكمة."], ["حتى يتبيّن لهم أنه الحق", "أن القرآن كلام الله ووحيه إلى رسوله حقاً، وأن الإسلام حق."], ["ألا إنهم في مرية من لقاء ربهم", "في شك من البعث حيث يُعرضون على الله."], ["ألا إنه بكل شيء محيط", "علماً وقدرة وعزة وسلطاناً."]], "m": "يأمر تعالى رسوله ﷺ أن يقول للمكذبين بالقرآن، الذين قالوا فيه شعر وسحر وأساطير الأولين: أخبروني إن كان القرآن الذي كذّبتم به من عند الله وكفرتم به، من يكون أضل منكم وأنتم في شقاق بعيد؟ لا أحد، فلِمَ لا تثوبون إلى رشدكم؟ ثم قال: سنريهم آياتنا الدالة على صدقنا وصدق رسولنا في أقطار السماوات والأرض مما ستكشف عنه الأيام من عجائب تدبير الله ولطائف صنعه، وفي أنفسهم أيضاً، حتى يتبيّن لهم أنه الحق؛ ومن ذلك فتح القرى والأمصار وانتصار الإسلام كما أخبر القرآن، ووقعة بدر وفتح مكة، وما ظهر إلى الآن من كشوفات في الآفاق والأنفس مما أشار إليه القرآن، ومن أعجبه قوله: ومن كل شيء خلقنا زوجين، فنظام الزوجية الساري في كل جزئيات الكون شاهد قوي على صدق القرآن. أوَلم يكفِ بربك أنه على كل شيء شهيد؟ توبيخ لهم، فشهادة الله كافية في صدق محمد، فكيف يطالبون بالآيات والله هو المرسل للرسول والمنزّل للكتاب؟ ألا إنهم في شك من البعث والجزاء، وهو الذي سبّب لهم كثيراً من أنواع الشر. ألا إنه بكل شيء محيط علماً وقدرة وعزة وسلطاناً، فليتّقِ الله امرؤ مصاب بالشك في البعث وكل الظواهر دالة على حتميّته.", "h": ["التنديد بالكفر بالقرآن والتكذيب بما جاء فيه من الهدى والنور.", "لا أضلّ ممن يكذّب بالقرآن، لأنه يعيش في خلاف وشقاق لا أبعد منه.", "صدق وعد الله تعالى حيث أرى المشركين وغيرهم آياته الدالة على وحدانيته وصحة دينه وصدق أخباره، ما آمن عليه البشر الذين لا يُعدّون كثرة.", "ما من اكتشاف ظهر ويظهر إلا والقرآن أدخله في هذه الآية: «سنريهم آياتنا في الآفاق وفي أنفسهم».", "الإشارة إلى أن الإسلام سيُعلم صحته وسيدين به البشر أجمعون في يوم ما من الأيام.", "تقرير البعث والجزاء، ومظاهر قدرة الله تعالى المقرّرة له."], "k": "«سنريهم آياتنا… وفي أنفسهم»… في جسدي آيات كثيرة؛ متى آخر مرة تأمّلت واحدة منها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 353;
insert into public.tdb_cards(topic, i, body) select 353, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٤٧ – ٤٨", "q": "۞إِلَيۡهِ يُرَدُّ عِلۡمُ ٱلسَّاعَةِۚ وَمَا تَخۡرُجُ مِن ثَمَرَٰتٖ مِّنۡ أَكۡمَامِهَا وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَيَوۡمَ يُنَادِيهِمۡ أَيۡنَ شُرَكَآءِي قَالُوٓاْ ءَاذَنَّـٰكَ مَامِنَّا مِن شَهِيدٖ ﴿٤٧﴾ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَدۡعُونَ مِن قَبۡلُۖ وَظَنُّواْ مَا لَهُم مِّن مَّحِيصٖ ﴿٤٨﴾", "w": [["إليه يُرَدّ علم الساعة", "إلى الله يُرد علم متى تقوم، إذ لا يعلمها إلا هو."], ["وما تخرج من ثمرات من أكمامها", "من أوعيتها، واحد الأكمام كِمّ، وكُمّ الثوب مخرج اليد."], ["ولا تضع إلا بعلمه", "لا تضع حملها إلا ملابساً بعلم الله المحيط بكل شيء."], ["قالوا آذنّاك", "أعلمناك الآن."], ["ما منا من شهيد", "ليس منا من يشهد بأن لك شريكاً أبداً."], ["وظنّوا ما لهم من محيص", "أيقنوا أنه ما لهم من مهرب من العذاب."]], "m": "يخبر تعالى أن علم الغيب منحصر فيه، فليس لأحد من خلقه علم الغيب، وخاصة علم متى تقوم الساعة، ويخبر عن واسع علمه وأنه محيط بكل الكائنات: فما تخرج من ثمرة من وعائها إلا يعلمها على كثرة الثمار والأشجار، وما تحمل من أنثى بجنين ولا تضعه يوم ولادته أو إسقاطه إلا بعلمه وإذنه. وهذه مظاهر الربوبية المستلزمة للألوهية، ومع هذا يتخذ الجاهلون له شركاء من أحجار وأوثان يعبدونها معه ظلماً وسفهاً. ويوم القيامة يناديهم: أين شركائي الذين كنتم تزعمون؟ فيتبرّؤون منهم ويقولون: أعلمناك الآن أنه ما منا من يشهد بأن لك شريكاً، وغاب عنهم ما كانوا يدعون من قبل، وأيقنوا ما لهم من مهرب من عذاب الله.", "h": ["استئثار الله تعالى بعلم الغيب، وخاصة علم متى تقوم الساعة.", "إحاطة علم الله تعالى بكل شيء، فما تخرج من ثمرة من أوعيتها ولا تحمل من أنثى ولا تضع حملها إلا بعلم الله تعالى وإذنه.", "براءة المشركين يوم القيامة من شركهم، وغياب شركائهم عنهم."], "k": "«وما تخرج من ثمرات من أكمامها إلا بعلمه»… يعلم كل ثمرة تتفتّح؛ أفلا يعلم همّي الذي أخفيه؟"}, {"lbl": "الآيات ٤٩ – ٥١", "q": "لَّا يَسۡـَٔمُ ٱلۡإِنسَٰنُ مِن دُعَآءِ ٱلۡخَيۡرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٞ قَنُوطٞ ﴿٤٩﴾ وَلَئِنۡ أَذَقۡنَٰهُ رَحۡمَةٗ مِّنَّا مِنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ هَٰذَا لِي وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةٗ وَلَئِن رُّجِعۡتُ إِلَىٰ رَبِّيٓ إِنَّ لِي عِندَهُۥ لَلۡحُسۡنَىٰۚ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُواْ بِمَا عَمِلُواْ وَلَنُذِيقَنَّهُم مِّنۡ عَذَابٍ غَلِيظٖ ﴿٥٠﴾ وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٖ ﴿٥١﴾", "w": [["لا يسأم الإنسان من دعاء الخير", "لا يملّ ولا يكلّ من سؤال المال والصحة والعافية."], ["وإن مسّه الشر فيؤوس قنوط", "المرض والفقر وغيرهما، فيؤوس من رحمة الله قنوط ظاهر عليه اليأس."], ["من بعد ضرّاء مسّته", "من بعد شدة أصابته وبلاء نزل به."], ["ليقولنّ هذا لي", "استحققته بعملي ومكانتي."], ["وما أظن الساعة قائمة", "ينكر البعث."], ["إن لي عنده للحسنى", "على فرض صحة ما قالت الرسل من البعث إن لي عند الله الحسنى."], ["أعرض ونأى بجانبه", "أعرض عن الشكر وتباعد متبختراً مختالاً في مشيته."], ["فذو دعاء عريض", "فهو ذو دعاء لربه طويل عريض: يا رب يا رب."]], "m": "يخبر تعالى عن الإنسان الذي لم تزكُ نفسه بالإيمان وصالح الأعمال أنه لا يملّ من دعاء الخير من المال والولد والصحة فلا يشبع منه بحال، وإن مسّه الشر من ضر وفقر فهو يؤوس من الفرج وتبدّل الحال، ظاهر عليه آثار اليأس في منطقه وحاله. ولئن أذاقه الله رحمة من مال وصحة واجتماع شمل من بعد مرض وفقر ليقولنّ لجهله وسفهه: هذا لي، استحققته بمالي ومكانتي، وإذا ذُكّر بالساعة ليرفق أو يتصدّق قال: ما أظن الساعة قائمة، ولئن رُجعت إلى ربي إن لي عنده الحسنى من غنى وجنة إن كانت كما تقول. فلننبئنّ الذين كفروا بما عملوا عند عرضهم علينا، ولنذيقنّهم من عذاب غليظ يخلدون فيه. وإذا أنعمنا على الإنسان بالمال والولد والصحة أعرض عن ذكرنا وشكرنا ونأى بجانبه متبختراً مختالاً، وإذا سلبناه ذلك ومسّه الشر فهو ذو دعاء عريض: يا رب يا رب. وهذا ليس الرجل الأول الذي ييأس ويقنط؛ ذاك كافر، وهذا مؤمن ضعيف الإيمان جاهل لا أدب عنده ولا خلق، وما أكثر هذا النوع في المسلمين اليوم؛ فالأول عائد إلى ظلمة نفسه بالكفر، وهذا عائد إلى سوء تربيته وسوء خلقه.", "h": ["بيان حال الإنسان قبل الإيمان والاستقامة، فإنه يكون أحطّ المخلوقات قدراً وأضعفها شأناً.", "تقرير عقيدة البعث والجزاء بذكر بعض الأحداث فيها.", "ذمّ اليأس والقنوط والكبر والاختيال، والكفر للنعم ونسيان المنعم وعدم شكره."], "k": "«وإذا مسّه الشر فذو دعاء عريض»… هل لا أعرف الله إلا في الشدة؟"}, {"lbl": "الآيات ٥٢ – ٥٤", "q": "قُلۡ أَرَءَيۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ ثُمَّ كَفَرۡتُم بِهِۦ مَنۡ أَضَلُّ مِمَّنۡ هُوَ فِي شِقَاقِۭ بَعِيدٖ ﴿٥٢﴾ سَنُرِيهِمۡ ءَايَٰتِنَا فِي ٱلۡأٓفَاقِ وَفِيٓ أَنفُسِهِمۡ حَتَّىٰ يَتَبَيَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّۗ أَوَلَمۡ يَكۡفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ﴿٥٣﴾ أَلَآ إِنَّهُمۡ فِي مِرۡيَةٖ مِّن لِّقَآءِ رَبِّهِمۡۗ أَلَآ إِنَّهُۥ بِكُلِّ شَيۡءٖ مُّحِيطُۢ ﴿٥٤﴾", "w": [["قل أرأيتم إن كان من عند الله", "أخبروني إن كان القرآن من عند الله كما قال النبي ﷺ."], ["ثم كفرتم به", "بعد العلم أنه من عند الله."], ["من أضلّ ممن هو في شقاق بعيد", "من يكون أضل منكم وأنتم في شقاق بعيد؟ لا أحد."], ["في الآفاق وفي أنفسهم", "في أقطار السماوات والأرض من المخلوقات وأسرار خلقها، وفي أنفسهم من لطائف الصنعة وبدائع الحكمة."], ["حتى يتبيّن لهم أنه الحق", "أن القرآن كلام الله ووحيه إلى رسوله حقاً، وأن الإسلام حق."], ["ألا إنهم في مرية من لقاء ربهم", "في شك من البعث حيث يُعرضون على الله."], ["ألا إنه بكل شيء محيط", "علماً وقدرة وعزة وسلطاناً."]], "m": "يأمر تعالى رسوله ﷺ أن يقول للمكذبين بالقرآن، الذين قالوا فيه شعر وسحر وأساطير الأولين: أخبروني إن كان القرآن الذي كذّبتم به من عند الله وكفرتم به، من يكون أضل منكم وأنتم في شقاق بعيد؟ لا أحد، فلِمَ لا تثوبون إلى رشدكم؟ ثم قال: سنريهم آياتنا الدالة على صدقنا وصدق رسولنا في أقطار السماوات والأرض مما ستكشف عنه الأيام من عجائب تدبير الله ولطائف صنعه، وفي أنفسهم أيضاً، حتى يتبيّن لهم أنه الحق؛ ومن ذلك فتح القرى والأمصار وانتصار الإسلام كما أخبر القرآن، ووقعة بدر وفتح مكة، وما ظهر إلى الآن من كشوفات في الآفاق والأنفس مما أشار إليه القرآن، ومن أعجبه قوله: ومن كل شيء خلقنا زوجين، فنظام الزوجية الساري في كل جزئيات الكون شاهد قوي على صدق القرآن. أوَلم يكفِ بربك أنه على كل شيء شهيد؟ توبيخ لهم، فشهادة الله كافية في صدق محمد، فكيف يطالبون بالآيات والله هو المرسل للرسول والمنزّل للكتاب؟ ألا إنهم في شك من البعث والجزاء، وهو الذي سبّب لهم كثيراً من أنواع الشر. ألا إنه بكل شيء محيط علماً وقدرة وعزة وسلطاناً، فليتّقِ الله امرؤ مصاب بالشك في البعث وكل الظواهر دالة على حتميّته.", "h": ["التنديد بالكفر بالقرآن والتكذيب بما جاء فيه من الهدى والنور.", "لا أضلّ ممن يكذّب بالقرآن، لأنه يعيش في خلاف وشقاق لا أبعد منه.", "صدق وعد الله تعالى حيث أرى المشركين وغيرهم آياته الدالة على وحدانيته وصحة دينه وصدق أخباره، ما آمن عليه البشر الذين لا يُعدّون كثرة.", "ما من اكتشاف ظهر ويظهر إلا والقرآن أدخله في هذه الآية: «سنريهم آياتنا في الآفاق وفي أنفسهم».", "الإشارة إلى أن الإسلام سيُعلم صحته وسيدين به البشر أجمعون في يوم ما من الأيام.", "تقرير البعث والجزاء، ومظاهر قدرة الله تعالى المقرّرة له."], "k": "«سنريهم آياتنا… وفي أنفسهم»… في جسدي آيات كثيرة؛ متى آخر مرة تأمّلت واحدة منها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (354, 42, 1, 12, 'سورة الشورى ١ – ١٢', 'الشورى: ليس كمثله شيء', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 354) = $j$[{"lbl": "الآيات ١ – ٦", "q": "حمٓ ﴿١﴾ عٓسٓقٓ ﴿٢﴾ كَذَٰلِكَ يُوحِيٓ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٣﴾ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ ﴿٤﴾ تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِن فَوۡقِهِنَّۚ وَٱلۡمَلَـٰٓئِكَةُ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيَسۡتَغۡفِرُونَ لِمَن فِي ٱلۡأَرۡضِۗ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿٥﴾ وَٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيۡهِمۡ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٖ ﴿٦﴾", "w": [["حم عسق", "من الحروف المقطعة، الله أعلم بمراده بها."], ["كذلك يوحي إليك وإلى الذين من قبلك", "مثل ذلك الإيحاء يُوحى إليك وإلى الذين من قبلك."], ["له ما في السماوات وما في الأرض", "خلقاً وملكاً وتصرّفاً."], ["وهو العزيز الحكيم", "العزيز في انتقامه من أعدائه، الحكيم في تدبيره لأوليائه."], ["يتفطّرن من فوقهن", "يتشقّقن من عظمة الرحمن وجلاله."], ["والذين اتخذوا من دونه أولياء", "آلهة يعبدونها."], ["الله حفيظ عليهم", "يحصي عليهم أعمالهم ويجزيهم بها."], ["وما أنت عليهم بوكيل", "لست موكَّلاً بحفظ أعمالهم، وإنما عليك البلاغ."]], "m": "حم عسق: الله أعلم بمراده به، وهو من المتشابه الذي يجب الإيمان به وتفويض فهم معناه إلى منزّله. مثل ذلك الإيحاء بأصول الدين الثلاثة، التوحيد والنبوة والبعث، يوحي إليك وإلى الذين من قبلك الله العزيز في انتقامه من أعدائه، الحكيم في تدبيره لأوليائه، له ما في السماوات وما في الأرض، وهو العلي ذو العلو المطلق على خلقه، العظيم في ذاته وشأنه وحكمه، لا إله إلا هو. تكاد السماوات يتشقّقن من فوقهن من عظمة الرب تبارك وتعالى، والملائكة يسبّحون بحمد ربهم، ويستغفرون لمن في الأرض، أي يطلبون المغفرة للمؤمنين، فهذا عام خاص بما في سورة غافر: ويستغفرون للذين آمنوا. ألا إن الله هو الغفور لمن تاب من عباده، الرحيم بالرحمة العامة سائر مخلوقاته في هذه الحياة، وبالرحمة الخاصة عباده المؤمنين في دار السلام. والذين اتخذوا من دونه شركاء يعبدونهم، الله حفيظ عليهم يحصي أعمالهم ويجزيهم بها يوم القيامة، وما أنت عليهم بوكيل تحفظ أعمالهم وتجزيهم، إن عليك إلا البلاغ وقد بلّغت. وفي الآية تسلية للرسول، لأنه كان يشقّ عليه إعراض المشركين وإصرارهم على الشرك.", "h": ["وحدة الوحي بين سائر الأنبياء، إذ هي تدور على التوحيد والنبوة والبعث والجزاء والترغيب في العمل الصالح والترهيب من العمل الفاسد.", "بيان عظمة الله تعالى وجلاله وكماله، حتى إن السماوات تكاد يتفطّرن من فوقهن، والملائكة يسبّحون بحمده تعالى ويستغفرون للمؤمنين.", "تسلية الرسول ﷺ والتخفيف عنه بأنه غير موكَّل بحفظ أعمال المشركين ومجازاتهم عليها، إنما هو الله تعالى، وما على الرسول إلا البلاغ المبين."], "k": "«ويستغفرون لمن في الأرض»… الملائكة تستغفر لي؛ فهل أستغفر أنا لنفسي؟"}, {"lbl": "الآيات ٧ – ٩", "q": "وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ قُرۡءَانًا عَرَبِيّٗا لِّتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَا وَتُنذِرَ يَوۡمَ ٱلۡجَمۡعِ لَا رَيۡبَ فِيهِۚ فَرِيقٞ فِي ٱلۡجَنَّةِ وَفَرِيقٞ فِي ٱلسَّعِيرِ ﴿٧﴾ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَهُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن يُدۡخِلُ مَن يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّـٰلِمُونَ مَا لَهُم مِّن وَلِيّٖ وَلَا نَصِيرٍ ﴿٨﴾ أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۖ فَٱللَّهُ هُوَ ٱلۡوَلِيُّ وَهُوَ يُحۡيِ ٱلۡمَوۡتَىٰ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٩﴾", "w": [["وكذلك أوحينا إليك", "ومثل ذلك الإيحاء إليك وإلى من قبلك أوحينا إليك."], ["قرآناً عربياً", "بلسان عربي."], ["لتنذر أم القرى ومن حولها", "علة الإيحاء إنذارك أهل مكة ومن حولها من القرى عذاب الله إن بقوا على الشرك."], ["وتنذر يوم الجمع", "تنذر الناس من يوم القيامة إذ هو يوم يجمع الله فيه الخلائق."], ["لا ريب فيه", "لا شك في مجيئه وجمع الناس فيه."], ["فريق في الجنة", "المؤمنون المتقون."], ["وفريق في السعير", "الكافرون."], ["ولو شاء الله لجعلهم أمة واحدة", "على دين الإسلام، وبذلك يكون الجميع في الجنة."], ["ولكن يُدخل من يشاء في رحمته", "في الإسلام أولاً ثم في الجنة ثانياً."], ["والظالمون ما لهم من ولي ولا نصير", "المشركون ليس لهم من وليّ يتولاهم ولا نصير ينصرهم."], ["أم اتخذوا من دونه أولياء", "بل اتخذوا من دونه شركاء ألّهوهم."], ["فالله هو الولي", "الولي الحق، ومن عداه فلا تنفع ولايته ولا تضر."]], "m": "ومثل ذلك الإيحاء الذي أوحينا إليك وإلى الذين من قبلك أوحينا إليك قرآناً عربياً يفهمه قومك، لتخوّف به أهل مكة ومن حولها عاقبة الشرك والكفر والظلم، وتنذر الناس يوم الجمع، يوم القيامة، يوم الهول العظيم، ليتّقوه بالإيمان والتقوى؛ يوم يكون فيه الناس والجن فريقين لا ثالث لهما: فريق في الجنة بإيمانه وتقواه، وفريق في السعير بشركه وكفره. ولو شاء الله لجعلهم في الدنيا أمة واحدة على دين الإسلام الذي هو دين آدم فنوح فإبراهيم فسائر الأنبياء، وهو الإيمان بالله وبما أمر الله بالإيمان به، والانقياد له ظاهراً وباطناً، ولو كانوا كذلك لكانوا في الآخرة فريقاً واحداً، ولكن لم يشأ ذلك لحكم عالية، فهو يدخل من يشاء في رحمته في الدنيا وهي الإسلام، وفي الآخرة وهي الجنة، والمشركون الذين رفضوا التوحيد ما لهم من ولي ولا نصير. أم اتخذ الظالمون من دون الله أولياء ليشفعوا لهم، جهلاً منهم بأنه لا يشفع أحد إلا بإذن الله؟ فالله هو الولي الحق، فلِمَ لا يتخذونه ولياً وهو يحيي الموتى وهو على كل شيء قدير؟ فمن أحق بأن يُتولّى: من يحيي ويميت، أم من لا يسمع ولا يبصر ولا يضر ولا ينفع؟", "h": ["تقرير النبوة المحمدية بإثبات الوحي الإلهي.", "شرف مكة بتسميتها أم القرى، أي أم المدن والحواضر.", "مشروعية التعليل للأفعال والأحكام.", "انقسام الناس يوم القيامة إلى سعيد وشقي لا غير.", "لم يشأ الله أن يجعل الناس أمة واحدة لحِكم عالية علمها إليه سبحانه.", "من طلب ولاية غير الله هلك، ومن والى الله دون من سواه كفاه الله ما أهمّه في دنياه وأخراه."], "k": "«فريق في الجنة وفريق في السعير»… لا ثالث لهما؛ فإلى أيّ الفريقين يقودني يومي هذا؟"}, {"lbl": "الآيات ١٠ – ١٢", "q": "وَمَا ٱخۡتَلَفۡتُمۡ فِيهِ مِن شَيۡءٖ فَحُكۡمُهُۥٓ إِلَى ٱللَّهِۚ ذَٰلِكُمُ ٱللَّهُ رَبِّي عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ ﴿١٠﴾ فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا وَمِنَ ٱلۡأَنۡعَٰمِ أَزۡوَٰجٗا يَذۡرَؤُكُمۡ فِيهِۚ لَيۡسَ كَمِثۡلِهِۦ شَيۡءٞۖ وَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ ﴿١١﴾ لَهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿١٢﴾", "w": [["وما اختلفتم فيه من شيء", "من أمور الدين والدنيا مع الكفار أو مع المؤمنين."], ["فحكمه إلى الله", "هو الذي يقضي فيه في الدنيا بما يُنزل من وحي على رسوله، وفي الآخرة إذ الحكم له."], ["ذلكم الله ربي عليه توكلت وإليه أنيب", "ذلكم الحاكم العدل الله ربي، فوّضت أمري إليه، وإليه لا إلى غيره أرجع في أموري."], ["فاطر السماوات والأرض", "خالقهما ومبدعهما على غير مثال سابق."], ["جعل لكم من أنفسكم أزواجاً", "بأن جعلكم ذكراً وأنثى، ومن الأنعام كذلك."], ["يذرؤكم فيه", "يخلقكم في هذا التدبير، تدبير الذكر والأنثى."], ["ليس كمثله شيء", "ليس مثل الله شيء، إذ هو الخالق لكل شيء، فلا يكون مخلوق مثله بحال."], ["وهو السميع البصير", "السميع لأقوال عباده، البصير بأعمالهم وأحوالهم."], ["له مقاليد السماوات والأرض", "له مفاتيح خزائنهما ومغاليقها."]], "m": "يقول تعالى: وما اختلفتم فيه من شيء من أمور الدين والدنيا أيها الناس فحكمه إلى الله، هو الذي يحكم فيه بالعدل، فردّوه إليه يقضِ بينكم بالحق. وأمر رسوله أن يقول للمشركين: ذلكم الحكم العدل الذي يقضي ولا يُقضى عليه الله ربي، لا رب لي سواه، عليه توكلت ففوّضت أمري إليه واثقاً في كفايته، وإليه وحده أرجع في أموري كلها. ثم واصل ذكر صفاته: فاطر السماوات السبع والأرض على غير مثال سابق، جعل لكم من أنفسكم أزواجاً، إذ خلق حواء من ضلع آدم ثم جعلكم تتناسلون من ذكر وأنثى، ومن الأنعام أزواجاً كذلك، يخلقكم في هذا النظام، نظام الذكر والأنثى، كأن الذكورة والأنوثة معمل يتم فيه خلق الإنسان والحيوان، فسبحان الخلّاق العليم. ليس كمثله شيء وهو السميع البصير: هذا تعريف عرّف تعالى به نفسه، فلا شيء مثله، فعُرف بالتفرّد بالوحدانية، وهو السميع لكل الأصوات، العليم بكل الكائنات. له مفاتيح خزائن السماوات والأرض ومغاليقها، يبسط الرزق لمن يشاء امتحاناً ويضيّق ابتلاءً، إنه بكل شيء عليم، فلا يُطلب الرزق إلا منه، ولا يُلجأ فيه إلا إليه.", "h": ["وجوب ردّ ما اختُلف فيه إلى الله تعالى ليحكم فيه، وهو الرد إلى الكتاب والسنة.", "وجوب التوكل عليه والإنابة إليه في كل الأمور.", "تنزيه الله تعالى عن مشابهته لخلقه، مع وجوب الإيمان بأسمائه الحسنى وصفاته العليا.", "وجوب الإيمان بأن الله هو الرزاق، بيده مفاتح خزائن الأرزاق، فمن شاء وسّع عليه ومن شاء ضيّق، وأنه يوسّع لحكمة ويضيّق لأخرى."], "k": "«وما اختلفتم فيه من شيء فحكمه إلى الله»… في خلافاتي، هل أبحث عن حكم الله أم عن انتصار رأيي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 354;
insert into public.tdb_cards(topic, i, body) select 354, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٦", "q": "حمٓ ﴿١﴾ عٓسٓقٓ ﴿٢﴾ كَذَٰلِكَ يُوحِيٓ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٣﴾ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ ﴿٤﴾ تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِن فَوۡقِهِنَّۚ وَٱلۡمَلَـٰٓئِكَةُ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيَسۡتَغۡفِرُونَ لِمَن فِي ٱلۡأَرۡضِۗ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿٥﴾ وَٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيۡهِمۡ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٖ ﴿٦﴾", "w": [["حم عسق", "من الحروف المقطعة، الله أعلم بمراده بها."], ["كذلك يوحي إليك وإلى الذين من قبلك", "مثل ذلك الإيحاء يُوحى إليك وإلى الذين من قبلك."], ["له ما في السماوات وما في الأرض", "خلقاً وملكاً وتصرّفاً."], ["وهو العزيز الحكيم", "العزيز في انتقامه من أعدائه، الحكيم في تدبيره لأوليائه."], ["يتفطّرن من فوقهن", "يتشقّقن من عظمة الرحمن وجلاله."], ["والذين اتخذوا من دونه أولياء", "آلهة يعبدونها."], ["الله حفيظ عليهم", "يحصي عليهم أعمالهم ويجزيهم بها."], ["وما أنت عليهم بوكيل", "لست موكَّلاً بحفظ أعمالهم، وإنما عليك البلاغ."]], "m": "حم عسق: الله أعلم بمراده به، وهو من المتشابه الذي يجب الإيمان به وتفويض فهم معناه إلى منزّله. مثل ذلك الإيحاء بأصول الدين الثلاثة، التوحيد والنبوة والبعث، يوحي إليك وإلى الذين من قبلك الله العزيز في انتقامه من أعدائه، الحكيم في تدبيره لأوليائه، له ما في السماوات وما في الأرض، وهو العلي ذو العلو المطلق على خلقه، العظيم في ذاته وشأنه وحكمه، لا إله إلا هو. تكاد السماوات يتشقّقن من فوقهن من عظمة الرب تبارك وتعالى، والملائكة يسبّحون بحمد ربهم، ويستغفرون لمن في الأرض، أي يطلبون المغفرة للمؤمنين، فهذا عام خاص بما في سورة غافر: ويستغفرون للذين آمنوا. ألا إن الله هو الغفور لمن تاب من عباده، الرحيم بالرحمة العامة سائر مخلوقاته في هذه الحياة، وبالرحمة الخاصة عباده المؤمنين في دار السلام. والذين اتخذوا من دونه شركاء يعبدونهم، الله حفيظ عليهم يحصي أعمالهم ويجزيهم بها يوم القيامة، وما أنت عليهم بوكيل تحفظ أعمالهم وتجزيهم، إن عليك إلا البلاغ وقد بلّغت. وفي الآية تسلية للرسول، لأنه كان يشقّ عليه إعراض المشركين وإصرارهم على الشرك.", "h": ["وحدة الوحي بين سائر الأنبياء، إذ هي تدور على التوحيد والنبوة والبعث والجزاء والترغيب في العمل الصالح والترهيب من العمل الفاسد.", "بيان عظمة الله تعالى وجلاله وكماله، حتى إن السماوات تكاد يتفطّرن من فوقهن، والملائكة يسبّحون بحمده تعالى ويستغفرون للمؤمنين.", "تسلية الرسول ﷺ والتخفيف عنه بأنه غير موكَّل بحفظ أعمال المشركين ومجازاتهم عليها، إنما هو الله تعالى، وما على الرسول إلا البلاغ المبين."], "k": "«ويستغفرون لمن في الأرض»… الملائكة تستغفر لي؛ فهل أستغفر أنا لنفسي؟"}, {"lbl": "الآيات ٧ – ٩", "q": "وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ قُرۡءَانًا عَرَبِيّٗا لِّتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَا وَتُنذِرَ يَوۡمَ ٱلۡجَمۡعِ لَا رَيۡبَ فِيهِۚ فَرِيقٞ فِي ٱلۡجَنَّةِ وَفَرِيقٞ فِي ٱلسَّعِيرِ ﴿٧﴾ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَهُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن يُدۡخِلُ مَن يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّـٰلِمُونَ مَا لَهُم مِّن وَلِيّٖ وَلَا نَصِيرٍ ﴿٨﴾ أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۖ فَٱللَّهُ هُوَ ٱلۡوَلِيُّ وَهُوَ يُحۡيِ ٱلۡمَوۡتَىٰ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٩﴾", "w": [["وكذلك أوحينا إليك", "ومثل ذلك الإيحاء إليك وإلى من قبلك أوحينا إليك."], ["قرآناً عربياً", "بلسان عربي."], ["لتنذر أم القرى ومن حولها", "علة الإيحاء إنذارك أهل مكة ومن حولها من القرى عذاب الله إن بقوا على الشرك."], ["وتنذر يوم الجمع", "تنذر الناس من يوم القيامة إذ هو يوم يجمع الله فيه الخلائق."], ["لا ريب فيه", "لا شك في مجيئه وجمع الناس فيه."], ["فريق في الجنة", "المؤمنون المتقون."], ["وفريق في السعير", "الكافرون."], ["ولو شاء الله لجعلهم أمة واحدة", "على دين الإسلام، وبذلك يكون الجميع في الجنة."], ["ولكن يُدخل من يشاء في رحمته", "في الإسلام أولاً ثم في الجنة ثانياً."], ["والظالمون ما لهم من ولي ولا نصير", "المشركون ليس لهم من وليّ يتولاهم ولا نصير ينصرهم."], ["أم اتخذوا من دونه أولياء", "بل اتخذوا من دونه شركاء ألّهوهم."], ["فالله هو الولي", "الولي الحق، ومن عداه فلا تنفع ولايته ولا تضر."]], "m": "ومثل ذلك الإيحاء الذي أوحينا إليك وإلى الذين من قبلك أوحينا إليك قرآناً عربياً يفهمه قومك، لتخوّف به أهل مكة ومن حولها عاقبة الشرك والكفر والظلم، وتنذر الناس يوم الجمع، يوم القيامة، يوم الهول العظيم، ليتّقوه بالإيمان والتقوى؛ يوم يكون فيه الناس والجن فريقين لا ثالث لهما: فريق في الجنة بإيمانه وتقواه، وفريق في السعير بشركه وكفره. ولو شاء الله لجعلهم في الدنيا أمة واحدة على دين الإسلام الذي هو دين آدم فنوح فإبراهيم فسائر الأنبياء، وهو الإيمان بالله وبما أمر الله بالإيمان به، والانقياد له ظاهراً وباطناً، ولو كانوا كذلك لكانوا في الآخرة فريقاً واحداً، ولكن لم يشأ ذلك لحكم عالية، فهو يدخل من يشاء في رحمته في الدنيا وهي الإسلام، وفي الآخرة وهي الجنة، والمشركون الذين رفضوا التوحيد ما لهم من ولي ولا نصير. أم اتخذ الظالمون من دون الله أولياء ليشفعوا لهم، جهلاً منهم بأنه لا يشفع أحد إلا بإذن الله؟ فالله هو الولي الحق، فلِمَ لا يتخذونه ولياً وهو يحيي الموتى وهو على كل شيء قدير؟ فمن أحق بأن يُتولّى: من يحيي ويميت، أم من لا يسمع ولا يبصر ولا يضر ولا ينفع؟", "h": ["تقرير النبوة المحمدية بإثبات الوحي الإلهي.", "شرف مكة بتسميتها أم القرى، أي أم المدن والحواضر.", "مشروعية التعليل للأفعال والأحكام.", "انقسام الناس يوم القيامة إلى سعيد وشقي لا غير.", "لم يشأ الله أن يجعل الناس أمة واحدة لحِكم عالية علمها إليه سبحانه.", "من طلب ولاية غير الله هلك، ومن والى الله دون من سواه كفاه الله ما أهمّه في دنياه وأخراه."], "k": "«فريق في الجنة وفريق في السعير»… لا ثالث لهما؛ فإلى أيّ الفريقين يقودني يومي هذا؟"}, {"lbl": "الآيات ١٠ – ١٢", "q": "وَمَا ٱخۡتَلَفۡتُمۡ فِيهِ مِن شَيۡءٖ فَحُكۡمُهُۥٓ إِلَى ٱللَّهِۚ ذَٰلِكُمُ ٱللَّهُ رَبِّي عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ ﴿١٠﴾ فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا وَمِنَ ٱلۡأَنۡعَٰمِ أَزۡوَٰجٗا يَذۡرَؤُكُمۡ فِيهِۚ لَيۡسَ كَمِثۡلِهِۦ شَيۡءٞۖ وَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ ﴿١١﴾ لَهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿١٢﴾", "w": [["وما اختلفتم فيه من شيء", "من أمور الدين والدنيا مع الكفار أو مع المؤمنين."], ["فحكمه إلى الله", "هو الذي يقضي فيه في الدنيا بما يُنزل من وحي على رسوله، وفي الآخرة إذ الحكم له."], ["ذلكم الله ربي عليه توكلت وإليه أنيب", "ذلكم الحاكم العدل الله ربي، فوّضت أمري إليه، وإليه لا إلى غيره أرجع في أموري."], ["فاطر السماوات والأرض", "خالقهما ومبدعهما على غير مثال سابق."], ["جعل لكم من أنفسكم أزواجاً", "بأن جعلكم ذكراً وأنثى، ومن الأنعام كذلك."], ["يذرؤكم فيه", "يخلقكم في هذا التدبير، تدبير الذكر والأنثى."], ["ليس كمثله شيء", "ليس مثل الله شيء، إذ هو الخالق لكل شيء، فلا يكون مخلوق مثله بحال."], ["وهو السميع البصير", "السميع لأقوال عباده، البصير بأعمالهم وأحوالهم."], ["له مقاليد السماوات والأرض", "له مفاتيح خزائنهما ومغاليقها."]], "m": "يقول تعالى: وما اختلفتم فيه من شيء من أمور الدين والدنيا أيها الناس فحكمه إلى الله، هو الذي يحكم فيه بالعدل، فردّوه إليه يقضِ بينكم بالحق. وأمر رسوله أن يقول للمشركين: ذلكم الحكم العدل الذي يقضي ولا يُقضى عليه الله ربي، لا رب لي سواه، عليه توكلت ففوّضت أمري إليه واثقاً في كفايته، وإليه وحده أرجع في أموري كلها. ثم واصل ذكر صفاته: فاطر السماوات السبع والأرض على غير مثال سابق، جعل لكم من أنفسكم أزواجاً، إذ خلق حواء من ضلع آدم ثم جعلكم تتناسلون من ذكر وأنثى، ومن الأنعام أزواجاً كذلك، يخلقكم في هذا النظام، نظام الذكر والأنثى، كأن الذكورة والأنوثة معمل يتم فيه خلق الإنسان والحيوان، فسبحان الخلّاق العليم. ليس كمثله شيء وهو السميع البصير: هذا تعريف عرّف تعالى به نفسه، فلا شيء مثله، فعُرف بالتفرّد بالوحدانية، وهو السميع لكل الأصوات، العليم بكل الكائنات. له مفاتيح خزائن السماوات والأرض ومغاليقها، يبسط الرزق لمن يشاء امتحاناً ويضيّق ابتلاءً، إنه بكل شيء عليم، فلا يُطلب الرزق إلا منه، ولا يُلجأ فيه إلا إليه.", "h": ["وجوب ردّ ما اختُلف فيه إلى الله تعالى ليحكم فيه، وهو الرد إلى الكتاب والسنة.", "وجوب التوكل عليه والإنابة إليه في كل الأمور.", "تنزيه الله تعالى عن مشابهته لخلقه، مع وجوب الإيمان بأسمائه الحسنى وصفاته العليا.", "وجوب الإيمان بأن الله هو الرزاق، بيده مفاتح خزائن الأرزاق، فمن شاء وسّع عليه ومن شاء ضيّق، وأنه يوسّع لحكمة ويضيّق لأخرى."], "k": "«وما اختلفتم فيه من شيء فحكمه إلى الله»… في خلافاتي، هل أبحث عن حكم الله أم عن انتصار رأيي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (355, 42, 13, 21, 'سورة الشورى ١٣ – ٢١', 'الشورى: أن أقيموا الدين ولا تتفرقوا فيه', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 355) = $j$[{"lbl": "الآيتان ١٣ – ١٤", "q": "۞شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ كَبُرَ عَلَى ٱلۡمُشۡرِكِينَ مَا تَدۡعُوهُمۡ إِلَيۡهِۚ ٱللَّهُ يَجۡتَبِيٓ إِلَيۡهِ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَن يُنِيبُ ﴿١٣﴾ وَمَا تَفَرَّقُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ إِلَىٰٓ أَجَلٖ مُّسَمّٗى لَّقُضِيَ بَيۡنَهُمۡۚ وَإِنَّ ٱلَّذِينَ أُورِثُواْ ٱلۡكِتَٰبَ مِنۢ بَعۡدِهِمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ ﴿١٤﴾", "w": [["شرع لكم من الدين ما وصّى به نوحاً", "شرع لكم من الدين الذي وصّى به نوحاً والذي أوحينا به إليك."], ["وما وصّينا به إبراهيم وموسى وعيسى", "والذي وصّينا به باقي أولي العزم، وهو أن يعبدوا الله وحده بما شرع من العبادات."], ["أن أقيموا الدين ولا تتفرقوا فيه", "أقيموا الدين الذي شرع لكم ولا تضيّعوه ولا تختلفوا فيه."], ["كبُر على المشركين ما تدعوهم إليه", "عظُم على كفار قريش ما تدعوهم إليه: لا إله إلا الله محمد رسول الله."], ["الله يجتبي إليه من يشاء", "يختار للإيمان به والعمل بطاعته من يريده لذلك."], ["ويهدي إليه من ينيب", "يوفّق لطاعته من يرجع إليه في جميع أموره."], ["بغياً بينهم", "حملهم البغي على التفرق في دين الله."], ["ولولا كلمة سبقت من ربك", "لولا ما قضى الله به من تأخير العذاب على هذه الأمة إلى يوم القيامة."], ["لقُضي بينهم", "لحكم الله بينهم فأهلك الكافرين وأنجى المؤمنين."], ["وإن الذين أُورثوا الكتاب من بعدهم", "الذين أُورثوا الكتاب من بعد الأولين: اليهود والنصارى ومشركو العرب."], ["لفي شك منه مريب", "في شك مما جئتهم به من الدين الحق، وهو الإسلام."]], "m": "يخاطب تعالى رسوله والمؤمنين: شرع لكم من الدين ما وصّى به نوحاً، إذ هو أول حامل شريعة من الرسل، والذي أوحينا إليك يا محمد، وما وصّينا به إبراهيم وموسى وعيسى من أولي العزم: أن الدين واحد، قائم على الإيمان وطاعة الله في أمره ونهيه، وأن إقامته بعدم التفريط فيه أو في شيء منه، وعدم التفرّق فيه، لأن التفرق يسبّب تضييعه كلاً أو بعضاً. كبُر على المشركين من كفار قريش ما تدعوهم إليه من عبادة الله وحده وترك الأصنام فلم يطيقوا حمله، فادعهم واصبر على أذاهم، والله يختار للإيمان به من يشاء ممن لا يصرّون على الباطل ولا يستكبرون عن الحق إذا عرفوه، ويوفّق لطاعته من شأنه الإنابة إلى ربه. وما تفرّق العرب واليهود والنصارى في دين الله فآمن بعض وكفر بعض إلا من بعد ما جاءهم العلم الصحيح يحمله القرآن ونبيه ﷺ، والحامل لهم على ذلك البغي والحسد. ولولا كلمة سبقت من ربك بعدم معاجلة هذه الأمة بعذاب الإبادة وترك عذابهم إلى يوم القيامة، لعجّل لهم العذاب فأهلك الكافرين وأنجى المؤمنين. وإن الذين أُورثوا الكتاب من بعد اليهود والنصارى، وهم العرب الذين أورثهم الله القرآن، لفي شك من القرآن والنبي والإسلام بالغ الغاية في الريبة، واللفظ يشمل اليهود والنصارى أيضاً إذ ورثوا الكتابين عمن سبقهم وهم فعلاً في شك من القرآن ونبيه.", "h": ["دين الله واحد، وهو الإيمان والاستقامة على طاعة الله وطاعة رسوله ﷺ.", "حرمة الاختلاف في دين الله المسبّب تضييع الدين كلاً أو بعضاً.", "مردّ التفرق في الدين إلى الحسد والبغي بين الناس، فلو لم يحسد بعضهم بعضاً ولم يبغِ بعضهم على بعض لما تفرّقوا في دين الله ولأقاموه مجتمعين فيه."], "k": "«ولا تتفرقوا فيه… بغياً بينهم»… كثير من الفرقة سببه الحسد لا الدليل؛ فهل في خلافي مع إخوتي شيء من ذلك؟"}, {"lbl": "الآيتان ١٥ – ١٦", "q": "فَلِذَٰلِكَ فَٱدۡعُۖ وَٱسۡتَقِمۡ كَمَآ أُمِرۡتَۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡۖ وَقُلۡ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَٰبٖۖ وَأُمِرۡتُ لِأَعۡدِلَ بَيۡنَكُمُۖ ٱللَّهُ رَبُّنَا وَرَبُّكُمۡۖ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡۖ لَا حُجَّةَ بَيۡنَنَا وَبَيۡنَكُمُۖ ٱللَّهُ يَجۡمَعُ بَيۡنَنَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ ﴿١٥﴾ وَٱلَّذِينَ يُحَآجُّونَ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ٱسۡتُجِيبَ لَهُۥ حُجَّتُهُمۡ دَاحِضَةٌ عِندَ رَبِّهِمۡ وَعَلَيۡهِمۡ غَضَبٞ وَلَهُمۡ عَذَابٞ شَدِيدٌ ﴿١٦﴾", "w": [["فلذلك فادع", "فإلى ذلك الدين الذي شرعه الله ووصّى به نوحاً وأوحاه إليك يا محمد فادعُ عباد الله."], ["واستقم كما أُمرت", "استقم على العمل به ولا تزغ عنه واثبت عليه كما أمرك ربك."], ["ولا تتبع أهواءهم", "أهواء المشركين وأهل الكتاب فتترك الحنيفية التي بُعثت بها فإنها الحق."], ["وقل آمنت بما أنزل الله من كتاب", "لست كالذين يؤمنون ببعض ويكفرون ببعض."], ["وأُمرت لأعدل بينكم", "أمرني ربي أن أحكم بينكم بالعدل الذي هو خلاف الجور."], ["الله ربنا وربكم", "خالقنا وخالقكم، ورازقنا ورازقكم، وإلهنا وإلهكم."], ["لنا أعمالنا ولكم أعمالكم", "وسيُجزى كلٌّ منا بعمله خيراً كان أو شراً."], ["لا حجة بيننا وبينكم", "لا حاجة إلى المحاجّة الآن بعد ظهور الحق."], ["والذين يحاجّون في الله", "يجادلون في دين الله نبيّه محمداً ﷺ."], ["من بعد ما استُجيب له", "بالإيمان لظهور معجزته."], ["حجتهم داحضة", "باطلة عند ربهم."], ["وعليهم غضب", "من الله، ولهم عذاب شديد يوم القيامة."]], "m": "فإلى ذلك الدين الحق الذي هو الإسلام فادعُ جميع الناس عربهم وعجمهم، فإنه دين الله الذي لا يقبل ديناً سواه، ولا يكمل الإنسان في أخلاقه ومعارفه ولا يسعد في الدارين إلا عليه، واستقم عليه كما أمرك ربك فلا تزغ عنه، فإنه الصراط المستقيم الذي لا يزيغ عنه إلا هالك، ولا تتبع أهواء المشركين ولا أهل الكتاب. وقل في صراحة: آمنت بما أنزل الله من كتاب، فلا أومن ببعض وأكفر ببعض كما أنتم عليه، وأمرني ربي أن أعدل بينكم في الحكم إذا تحاكمتم إليّ، كما أني لا أفرّق بينكم إذ أعتبركم على الكفر سواء، فكل من لم يكن على الإسلام الذي كان عليه نوح وإبراهيم وموسى وعيسى والذي عليه أنا وأصحابي اليوم فهو كافر من أهل النار. الله ربنا وربكم، لنا أعمالنا ولكم أعمالكم، ويُجزى كلٌّ بعمله، السيئة بمثلها والحسنة بعشر أمثالها، إلا أن الكافر لا تكون له حسنة ما دام قد كفر بأصل الدين. لا حجة بيننا وبينكم اليوم، إذ ظهر الحق ولاح الصبح لذي عينين، فلا داعي إلى الجدال، الله يجمع بيننا يوم القيامة فيحكم فيما اختلفنا فيه. والذين يجادلون في دين الله النبيَّ والمؤمنين يريدون ردّهم إلى باطلهم من بعد ما استُجيب للرسول ودخل الناس في دين الله، حجتهم باطلة عند ربهم، وعليهم غضب ولهم عذاب شديد. نزلت في يهود نصبوا أنفسهم خصوماً لأصحاب رسول الله يجادلونهم يريدون تشكيكهم في الإسلام والعودة بهم إلى وثنية الجاهلية.", "h": ["وجوب الدعوة إلى الإسلام بين أمم العالم، إذ لا نجاة للبشرية إلا بالإسلام.", "حرمة اتباع أهواء أهل الأهواء والسير معهم وموافقتهم في باطلهم.", "وجوب الاستقامة على الإسلام عقائد وعبادات وأحكاماً قضائية وآداباً وأخلاقاً.", "تعيّن ترك الحجاج والمخاصمة مع أهل الكتاب، وكذا أهل الأهواء والبدع، لأنا على الحق وهم على الباطل، فكيف نحاجّهم؟ إذ الواجب أن يُسلموا وكفى."], "k": "«واستقم كما أُمرت ولا تتبع أهواءهم»… أين تميل بي أهواء من حولي عن الطريق؟"}, {"lbl": "الآيات ١٧ – ٢١", "q": "ٱللَّهُ ٱلَّذِيٓ أَنزَلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ وَٱلۡمِيزَانَۗ وَمَا يُدۡرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٞ ﴿١٧﴾ يَسۡتَعۡجِلُ بِهَا ٱلَّذِينَ لَا يُؤۡمِنُونَ بِهَاۖ وَٱلَّذِينَ ءَامَنُواْ مُشۡفِقُونَ مِنۡهَا وَيَعۡلَمُونَ أَنَّهَا ٱلۡحَقُّۗ أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِي ٱلسَّاعَةِ لَفِي ضَلَٰلِۭ بَعِيدٍ ﴿١٨﴾ ٱللَّهُ لَطِيفُۢ بِعِبَادِهِۦ يَرۡزُقُ مَن يَشَآءُۖ وَهُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ ﴿١٩﴾ مَن كَانَ يُرِيدُ حَرۡثَ ٱلۡأٓخِرَةِ نَزِدۡ لَهُۥ فِي حَرۡثِهِۦۖ وَمَن كَانَ يُرِيدُ حَرۡثَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِن نَّصِيبٍ ﴿٢٠﴾ أَمۡ لَهُمۡ شُرَكَـٰٓؤُاْ شَرَعُواْ لَهُم مِّنَ ٱلدِّينِ مَا لَمۡ يَأۡذَنۢ بِهِ ٱللَّهُۚ وَلَوۡلَا كَلِمَةُ ٱلۡفَصۡلِ لَقُضِيَ بَيۡنَهُمۡۗ وَإِنَّ ٱلظَّـٰلِمِينَ لَهُمۡ عَذَابٌ أَلِيمٞ ﴿٢١﴾", "w": [["الله الذي أنزل الكتاب بالحق", "أنزل القرآن متلبّساً بالحق والصدق لا يفارقه أبداً."], ["والميزان", "وأنزل الميزان وهو العدل ليُحقّ الحق."], ["وما يدريك لعل الساعة قريب", "أي شيء يجعلك تدري قرب الساعة إلا أن يكون الوحي؟"], ["يستعجل بها الذين لا يؤمنون بها", "يطالب المكذبون بها لأنهم لا يخافون ما فيها لعدم إيمانهم."], ["والذين آمنوا مشفقون منها", "خائفون، لأنهم لا يدرون ما يكون لهم فيها من سعادة أو شقاء."], ["ويعلمون أنها الحق", "أن الساعة حق واجبة الإتيان لا محالة."], ["إن الذين يُمارون في الساعة", "يجادلون فيها شاكّين في وقوعها."], ["الله لطيف بعباده", "برّهم وفاجرهم، بدليل أنهم يعصونه وهو يرزقهم ولا يعاقبهم."], ["من كان يريد حرث الآخرة", "من كان يريد بعمله ثواب الآخرة."], ["نزد له في حرثه", "نضاعف له ثوابه، الحسنة بعشر أمثالها وأكثر."], ["ومن كان يريد حرث الدنيا", "من كان يريد بعمله متاع الحياة الدنيا."], ["نؤته منها وما له في الآخرة من نصيب", "نعطه منها ما قُدّر له، وليس له في الآخرة من حظ."], ["شرعوا لهم من الدين ما لم يأذن به الله", "شركاء من الشياطين شرعوا لهم ما لم يشرعه الله، وهو الشرك."], ["ولولا كلمة الفصل لقُضي بينهم", "لولا حكم الله بتأخير العذاب إلى يوم القيامة لأهلكهم اليوم على شركهم."]], "m": "يخبر تعالى أنه الذي أنزل القرآن بالحق والصدق، وأنزل الميزان، من أجل إحقاق الحق في الأرض وإبطال الباطل، فلا يُعبد إلا الله ولا يُحكم إلا بشرعه، وفي ذلك كمال الإنسانية وسعادتها. وما يدريك لعل الساعة قريب؟ أي شيء جعلك تدري قربها؟ إنه الوحي الإلهي لا غير. يستعجل بها الذين لا يؤمنون بها، يستعجلون الرسول بقولهم: متى الساعة؟ أما المؤمنون فمشفقون من وقوعها لأنهم لا يدرون مصيرهم فيها، ويعلمون أنها الحق ليحكم الله بين عباده ويقتصّ فيها للمظلوم من الظالم. ألا إن الذين يشكّكون في الساعة ويجادلون في وقوعها لفي ضلال بعيد لا يُرجى لهم معه العودة إلى الصواب. الله لطيف بعباده مؤمنهم وكافرهم، برّهم وفاجرهم، يكفر به الكافرون ويعصيه العاصون وهو يطعمهم ويسقيهم ولا يهلكهم بذنوبهم، يرزق من يشاء فيوسّع على من يشاء ويضيّق على من يشاء حسب ما تقتضيه تربيتهم، فلا يدل الغنى على الرضا ولا الفقر على السخط، وهو القوي العزيز. ومن مظاهر لطفه أن من أراد بعمله ثواب الآخرة ضاعف له أجره من عشر إلى سبعمائة، ومن أراد بعمله متاع الدنيا أعطاه منها ما قدّره له، وما له في الآخرة من نصيب إلا النار. أم للمشركين من قريش شركاء من الشياطين شرعوا لهم ديناً هو الشرك لم يأذن به الله؟ ولولا أنه قضى بتأخير عذابهم إلى يوم القيامة لأهلكهم في الدنيا، وإن الظالمين لهم عذاب أليم.", "h": ["بيان بعض الحكمة في إنزال الكتاب أي القرآن والميزان، وهو أن يحكم الناس بالقسط.", "بيان قرب الساعة، وأن معرفة قربها كانت بالوحي الإلهي، مثل: «اقترب للناس حسابهم».", "المستعجلون بالساعة هم الكافرون الجاحدون لها.", "بيان لطف الله بعباده، فله الحمد وله المنة والشكر.", "بيان وجوب إصلاح النيات، فإن مدار العمل قبولاً ورفضاً بحسبها.", "حظر التشريع بجميع أنواعه عن غير الله ورسوله."], "k": "«من كان يريد حرث الآخرة نزد له في حرثه»… العمل نفسه قد يكون حرث دنيا أو حرث آخرة؛ فما نيتي اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 355;
insert into public.tdb_cards(topic, i, body) select 355, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١٣ – ١٤", "q": "۞شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ كَبُرَ عَلَى ٱلۡمُشۡرِكِينَ مَا تَدۡعُوهُمۡ إِلَيۡهِۚ ٱللَّهُ يَجۡتَبِيٓ إِلَيۡهِ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَن يُنِيبُ ﴿١٣﴾ وَمَا تَفَرَّقُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ إِلَىٰٓ أَجَلٖ مُّسَمّٗى لَّقُضِيَ بَيۡنَهُمۡۚ وَإِنَّ ٱلَّذِينَ أُورِثُواْ ٱلۡكِتَٰبَ مِنۢ بَعۡدِهِمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ ﴿١٤﴾", "w": [["شرع لكم من الدين ما وصّى به نوحاً", "شرع لكم من الدين الذي وصّى به نوحاً والذي أوحينا به إليك."], ["وما وصّينا به إبراهيم وموسى وعيسى", "والذي وصّينا به باقي أولي العزم، وهو أن يعبدوا الله وحده بما شرع من العبادات."], ["أن أقيموا الدين ولا تتفرقوا فيه", "أقيموا الدين الذي شرع لكم ولا تضيّعوه ولا تختلفوا فيه."], ["كبُر على المشركين ما تدعوهم إليه", "عظُم على كفار قريش ما تدعوهم إليه: لا إله إلا الله محمد رسول الله."], ["الله يجتبي إليه من يشاء", "يختار للإيمان به والعمل بطاعته من يريده لذلك."], ["ويهدي إليه من ينيب", "يوفّق لطاعته من يرجع إليه في جميع أموره."], ["بغياً بينهم", "حملهم البغي على التفرق في دين الله."], ["ولولا كلمة سبقت من ربك", "لولا ما قضى الله به من تأخير العذاب على هذه الأمة إلى يوم القيامة."], ["لقُضي بينهم", "لحكم الله بينهم فأهلك الكافرين وأنجى المؤمنين."], ["وإن الذين أُورثوا الكتاب من بعدهم", "الذين أُورثوا الكتاب من بعد الأولين: اليهود والنصارى ومشركو العرب."], ["لفي شك منه مريب", "في شك مما جئتهم به من الدين الحق، وهو الإسلام."]], "m": "يخاطب تعالى رسوله والمؤمنين: شرع لكم من الدين ما وصّى به نوحاً، إذ هو أول حامل شريعة من الرسل، والذي أوحينا إليك يا محمد، وما وصّينا به إبراهيم وموسى وعيسى من أولي العزم: أن الدين واحد، قائم على الإيمان وطاعة الله في أمره ونهيه، وأن إقامته بعدم التفريط فيه أو في شيء منه، وعدم التفرّق فيه، لأن التفرق يسبّب تضييعه كلاً أو بعضاً. كبُر على المشركين من كفار قريش ما تدعوهم إليه من عبادة الله وحده وترك الأصنام فلم يطيقوا حمله، فادعهم واصبر على أذاهم، والله يختار للإيمان به من يشاء ممن لا يصرّون على الباطل ولا يستكبرون عن الحق إذا عرفوه، ويوفّق لطاعته من شأنه الإنابة إلى ربه. وما تفرّق العرب واليهود والنصارى في دين الله فآمن بعض وكفر بعض إلا من بعد ما جاءهم العلم الصحيح يحمله القرآن ونبيه ﷺ، والحامل لهم على ذلك البغي والحسد. ولولا كلمة سبقت من ربك بعدم معاجلة هذه الأمة بعذاب الإبادة وترك عذابهم إلى يوم القيامة، لعجّل لهم العذاب فأهلك الكافرين وأنجى المؤمنين. وإن الذين أُورثوا الكتاب من بعد اليهود والنصارى، وهم العرب الذين أورثهم الله القرآن، لفي شك من القرآن والنبي والإسلام بالغ الغاية في الريبة، واللفظ يشمل اليهود والنصارى أيضاً إذ ورثوا الكتابين عمن سبقهم وهم فعلاً في شك من القرآن ونبيه.", "h": ["دين الله واحد، وهو الإيمان والاستقامة على طاعة الله وطاعة رسوله ﷺ.", "حرمة الاختلاف في دين الله المسبّب تضييع الدين كلاً أو بعضاً.", "مردّ التفرق في الدين إلى الحسد والبغي بين الناس، فلو لم يحسد بعضهم بعضاً ولم يبغِ بعضهم على بعض لما تفرّقوا في دين الله ولأقاموه مجتمعين فيه."], "k": "«ولا تتفرقوا فيه… بغياً بينهم»… كثير من الفرقة سببه الحسد لا الدليل؛ فهل في خلافي مع إخوتي شيء من ذلك؟"}, {"lbl": "الآيتان ١٥ – ١٦", "q": "فَلِذَٰلِكَ فَٱدۡعُۖ وَٱسۡتَقِمۡ كَمَآ أُمِرۡتَۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡۖ وَقُلۡ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَٰبٖۖ وَأُمِرۡتُ لِأَعۡدِلَ بَيۡنَكُمُۖ ٱللَّهُ رَبُّنَا وَرَبُّكُمۡۖ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡۖ لَا حُجَّةَ بَيۡنَنَا وَبَيۡنَكُمُۖ ٱللَّهُ يَجۡمَعُ بَيۡنَنَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ ﴿١٥﴾ وَٱلَّذِينَ يُحَآجُّونَ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ٱسۡتُجِيبَ لَهُۥ حُجَّتُهُمۡ دَاحِضَةٌ عِندَ رَبِّهِمۡ وَعَلَيۡهِمۡ غَضَبٞ وَلَهُمۡ عَذَابٞ شَدِيدٌ ﴿١٦﴾", "w": [["فلذلك فادع", "فإلى ذلك الدين الذي شرعه الله ووصّى به نوحاً وأوحاه إليك يا محمد فادعُ عباد الله."], ["واستقم كما أُمرت", "استقم على العمل به ولا تزغ عنه واثبت عليه كما أمرك ربك."], ["ولا تتبع أهواءهم", "أهواء المشركين وأهل الكتاب فتترك الحنيفية التي بُعثت بها فإنها الحق."], ["وقل آمنت بما أنزل الله من كتاب", "لست كالذين يؤمنون ببعض ويكفرون ببعض."], ["وأُمرت لأعدل بينكم", "أمرني ربي أن أحكم بينكم بالعدل الذي هو خلاف الجور."], ["الله ربنا وربكم", "خالقنا وخالقكم، ورازقنا ورازقكم، وإلهنا وإلهكم."], ["لنا أعمالنا ولكم أعمالكم", "وسيُجزى كلٌّ منا بعمله خيراً كان أو شراً."], ["لا حجة بيننا وبينكم", "لا حاجة إلى المحاجّة الآن بعد ظهور الحق."], ["والذين يحاجّون في الله", "يجادلون في دين الله نبيّه محمداً ﷺ."], ["من بعد ما استُجيب له", "بالإيمان لظهور معجزته."], ["حجتهم داحضة", "باطلة عند ربهم."], ["وعليهم غضب", "من الله، ولهم عذاب شديد يوم القيامة."]], "m": "فإلى ذلك الدين الحق الذي هو الإسلام فادعُ جميع الناس عربهم وعجمهم، فإنه دين الله الذي لا يقبل ديناً سواه، ولا يكمل الإنسان في أخلاقه ومعارفه ولا يسعد في الدارين إلا عليه، واستقم عليه كما أمرك ربك فلا تزغ عنه، فإنه الصراط المستقيم الذي لا يزيغ عنه إلا هالك، ولا تتبع أهواء المشركين ولا أهل الكتاب. وقل في صراحة: آمنت بما أنزل الله من كتاب، فلا أومن ببعض وأكفر ببعض كما أنتم عليه، وأمرني ربي أن أعدل بينكم في الحكم إذا تحاكمتم إليّ، كما أني لا أفرّق بينكم إذ أعتبركم على الكفر سواء، فكل من لم يكن على الإسلام الذي كان عليه نوح وإبراهيم وموسى وعيسى والذي عليه أنا وأصحابي اليوم فهو كافر من أهل النار. الله ربنا وربكم، لنا أعمالنا ولكم أعمالكم، ويُجزى كلٌّ بعمله، السيئة بمثلها والحسنة بعشر أمثالها، إلا أن الكافر لا تكون له حسنة ما دام قد كفر بأصل الدين. لا حجة بيننا وبينكم اليوم، إذ ظهر الحق ولاح الصبح لذي عينين، فلا داعي إلى الجدال، الله يجمع بيننا يوم القيامة فيحكم فيما اختلفنا فيه. والذين يجادلون في دين الله النبيَّ والمؤمنين يريدون ردّهم إلى باطلهم من بعد ما استُجيب للرسول ودخل الناس في دين الله، حجتهم باطلة عند ربهم، وعليهم غضب ولهم عذاب شديد. نزلت في يهود نصبوا أنفسهم خصوماً لأصحاب رسول الله يجادلونهم يريدون تشكيكهم في الإسلام والعودة بهم إلى وثنية الجاهلية.", "h": ["وجوب الدعوة إلى الإسلام بين أمم العالم، إذ لا نجاة للبشرية إلا بالإسلام.", "حرمة اتباع أهواء أهل الأهواء والسير معهم وموافقتهم في باطلهم.", "وجوب الاستقامة على الإسلام عقائد وعبادات وأحكاماً قضائية وآداباً وأخلاقاً.", "تعيّن ترك الحجاج والمخاصمة مع أهل الكتاب، وكذا أهل الأهواء والبدع، لأنا على الحق وهم على الباطل، فكيف نحاجّهم؟ إذ الواجب أن يُسلموا وكفى."], "k": "«واستقم كما أُمرت ولا تتبع أهواءهم»… أين تميل بي أهواء من حولي عن الطريق؟"}, {"lbl": "الآيات ١٧ – ٢١", "q": "ٱللَّهُ ٱلَّذِيٓ أَنزَلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ وَٱلۡمِيزَانَۗ وَمَا يُدۡرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٞ ﴿١٧﴾ يَسۡتَعۡجِلُ بِهَا ٱلَّذِينَ لَا يُؤۡمِنُونَ بِهَاۖ وَٱلَّذِينَ ءَامَنُواْ مُشۡفِقُونَ مِنۡهَا وَيَعۡلَمُونَ أَنَّهَا ٱلۡحَقُّۗ أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِي ٱلسَّاعَةِ لَفِي ضَلَٰلِۭ بَعِيدٍ ﴿١٨﴾ ٱللَّهُ لَطِيفُۢ بِعِبَادِهِۦ يَرۡزُقُ مَن يَشَآءُۖ وَهُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ ﴿١٩﴾ مَن كَانَ يُرِيدُ حَرۡثَ ٱلۡأٓخِرَةِ نَزِدۡ لَهُۥ فِي حَرۡثِهِۦۖ وَمَن كَانَ يُرِيدُ حَرۡثَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِن نَّصِيبٍ ﴿٢٠﴾ أَمۡ لَهُمۡ شُرَكَـٰٓؤُاْ شَرَعُواْ لَهُم مِّنَ ٱلدِّينِ مَا لَمۡ يَأۡذَنۢ بِهِ ٱللَّهُۚ وَلَوۡلَا كَلِمَةُ ٱلۡفَصۡلِ لَقُضِيَ بَيۡنَهُمۡۗ وَإِنَّ ٱلظَّـٰلِمِينَ لَهُمۡ عَذَابٌ أَلِيمٞ ﴿٢١﴾", "w": [["الله الذي أنزل الكتاب بالحق", "أنزل القرآن متلبّساً بالحق والصدق لا يفارقه أبداً."], ["والميزان", "وأنزل الميزان وهو العدل ليُحقّ الحق."], ["وما يدريك لعل الساعة قريب", "أي شيء يجعلك تدري قرب الساعة إلا أن يكون الوحي؟"], ["يستعجل بها الذين لا يؤمنون بها", "يطالب المكذبون بها لأنهم لا يخافون ما فيها لعدم إيمانهم."], ["والذين آمنوا مشفقون منها", "خائفون، لأنهم لا يدرون ما يكون لهم فيها من سعادة أو شقاء."], ["ويعلمون أنها الحق", "أن الساعة حق واجبة الإتيان لا محالة."], ["إن الذين يُمارون في الساعة", "يجادلون فيها شاكّين في وقوعها."], ["الله لطيف بعباده", "برّهم وفاجرهم، بدليل أنهم يعصونه وهو يرزقهم ولا يعاقبهم."], ["من كان يريد حرث الآخرة", "من كان يريد بعمله ثواب الآخرة."], ["نزد له في حرثه", "نضاعف له ثوابه، الحسنة بعشر أمثالها وأكثر."], ["ومن كان يريد حرث الدنيا", "من كان يريد بعمله متاع الحياة الدنيا."], ["نؤته منها وما له في الآخرة من نصيب", "نعطه منها ما قُدّر له، وليس له في الآخرة من حظ."], ["شرعوا لهم من الدين ما لم يأذن به الله", "شركاء من الشياطين شرعوا لهم ما لم يشرعه الله، وهو الشرك."], ["ولولا كلمة الفصل لقُضي بينهم", "لولا حكم الله بتأخير العذاب إلى يوم القيامة لأهلكهم اليوم على شركهم."]], "m": "يخبر تعالى أنه الذي أنزل القرآن بالحق والصدق، وأنزل الميزان، من أجل إحقاق الحق في الأرض وإبطال الباطل، فلا يُعبد إلا الله ولا يُحكم إلا بشرعه، وفي ذلك كمال الإنسانية وسعادتها. وما يدريك لعل الساعة قريب؟ أي شيء جعلك تدري قربها؟ إنه الوحي الإلهي لا غير. يستعجل بها الذين لا يؤمنون بها، يستعجلون الرسول بقولهم: متى الساعة؟ أما المؤمنون فمشفقون من وقوعها لأنهم لا يدرون مصيرهم فيها، ويعلمون أنها الحق ليحكم الله بين عباده ويقتصّ فيها للمظلوم من الظالم. ألا إن الذين يشكّكون في الساعة ويجادلون في وقوعها لفي ضلال بعيد لا يُرجى لهم معه العودة إلى الصواب. الله لطيف بعباده مؤمنهم وكافرهم، برّهم وفاجرهم، يكفر به الكافرون ويعصيه العاصون وهو يطعمهم ويسقيهم ولا يهلكهم بذنوبهم، يرزق من يشاء فيوسّع على من يشاء ويضيّق على من يشاء حسب ما تقتضيه تربيتهم، فلا يدل الغنى على الرضا ولا الفقر على السخط، وهو القوي العزيز. ومن مظاهر لطفه أن من أراد بعمله ثواب الآخرة ضاعف له أجره من عشر إلى سبعمائة، ومن أراد بعمله متاع الدنيا أعطاه منها ما قدّره له، وما له في الآخرة من نصيب إلا النار. أم للمشركين من قريش شركاء من الشياطين شرعوا لهم ديناً هو الشرك لم يأذن به الله؟ ولولا أنه قضى بتأخير عذابهم إلى يوم القيامة لأهلكهم في الدنيا، وإن الظالمين لهم عذاب أليم.", "h": ["بيان بعض الحكمة في إنزال الكتاب أي القرآن والميزان، وهو أن يحكم الناس بالقسط.", "بيان قرب الساعة، وأن معرفة قربها كانت بالوحي الإلهي، مثل: «اقترب للناس حسابهم».", "المستعجلون بالساعة هم الكافرون الجاحدون لها.", "بيان لطف الله بعباده، فله الحمد وله المنة والشكر.", "بيان وجوب إصلاح النيات، فإن مدار العمل قبولاً ورفضاً بحسبها.", "حظر التشريع بجميع أنواعه عن غير الله ورسوله."], "k": "«من كان يريد حرث الآخرة نزد له في حرثه»… العمل نفسه قد يكون حرث دنيا أو حرث آخرة؛ فما نيتي اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (356, 42, 22, 35, 'سورة الشورى ٢٢ – ٣٥', 'الشورى: قل لا أسألكم عليه أجراً إلا المودّة في القربى', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 356) = $j$[{"lbl": "الآيات ٢٢ – ٢٦", "q": "تَرَى ٱلظَّـٰلِمِينَ مُشۡفِقِينَ مِمَّا كَسَبُواْ وَهُوَ وَاقِعُۢ بِهِمۡۗ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فِي رَوۡضَاتِ ٱلۡجَنَّاتِۖ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ ﴿٢٢﴾ ذَٰلِكَ ٱلَّذِي يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِۗ قُل لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًا إِلَّا ٱلۡمَوَدَّةَ فِي ٱلۡقُرۡبَىٰۗ وَمَن يَقۡتَرِفۡ حَسَنَةٗ نَّزِدۡ لَهُۥ فِيهَا حُسۡنًاۚ إِنَّ ٱللَّهَ غَفُورٞ شَكُورٌ ﴿٢٣﴾ أَمۡ يَقُولُونَ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗاۖ فَإِن يَشَإِ ٱللَّهُ يَخۡتِمۡ عَلَىٰ قَلۡبِكَۗ وَيَمۡحُ ٱللَّهُ ٱلۡبَٰطِلَ وَيُحِقُّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦٓۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٢٤﴾ وَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَعۡفُواْ عَنِ ٱلسَّيِّـَٔاتِ وَيَعۡلَمُ مَا تَفۡعَلُونَ ﴿٢٥﴾ وَيَسۡتَجِيبُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضۡلِهِۦۚ وَٱلۡكَٰفِرُونَ لَهُمۡ عَذَابٞ شَدِيدٞ ﴿٢٦﴾", "w": [["ترى الظالمين مشفقين مما كسبوا", "ترى الظالمين يوم القيامة خائفين من جزاء ما كسبوا."], ["وهو واقع بهم", "جزاء ما كسبوا من الباطل والشرك نازل بهم لا محالة."], ["في روضات الجنات", "والروضة في الجنة أنزه مكان فيها."], ["لهم ما يشاؤون عند ربهم", "لهم فيها ما تشتهيه أنفسهم وتلذّه أعينهم في جوار ربهم."], ["قل لا أسألكم عليه أجراً", "لا أسألكم على التبليغ ثواباً."], ["إلا المودّة في القربى", "لكن أسألكم أن تودّوا قرابتي فتمنعوني حتى أبلّغ رسالتي."], ["ومن يقترف حسنة", "من يكتسب حسنة بقول أو عمل صالح."], ["نزد له فيها حُسناً", "نضاعفها له أضعافاً."], ["أم يقولون افترى على الله كذباً", "أيقول المشركون إن محمداً افترى على الله كذباً فنسب إليه القرآن؟"], ["فإن يشأ الله يختم على قلبك", "إن يشأ يطبع على قلبك وينسك القرآن، فالله قادر على أن يمنعك من الافتراء عليه."], ["ويمحُ الله الباطل ويُحقّ الحق بكلماته", "من شأنه أنه يمحو الباطل ويحق الحق بالآيات القرآنية، وقد فعل."], ["ويعفو عن السيئات", "لا يؤاخذ بها من تاب منها."], ["ويستجيب الذين آمنوا", "يجيب عباده المؤمنين إلى ما دعوه فيه فيعطيهم سؤلهم."], ["ويزيدهم من فضله", "يعطيهم ما لم يسألوه من الخير."]], "m": "ترى الظالمين يوم القيامة خائفين من جزاء ما كسبوا من الشرك والمعاصي، وهو واقع بهم لا محالة، وفي الوقت ذاته يكون الذين آمنوا بالله رباً وبالإسلام ديناً وبمحمد رسولاً وعملوا الصالحات في روضات الجنات، وهي أنزهها وأحسنها، لهم ما يشاؤون مما تشتهيه الأنفس وتلذّه الأعين في جوار رب كريم، ذلك هو الفضل الكبير، وذلك الذي يبشّر الله به عباده المؤمنين في كتابه وعلى لسان رسوله. قل لقومك: لا أسألكم على إبلاغي إياكم دعوة ربي مالاً، لكن أسألكم أن تودّوا قرابتي منكم فلا تؤذوني وتمنعوني من الناس حتى أبلّغ دعوة ربي. ومن يعمل حسنة نضاعفها له، إن الله غفور للتائبين شكور للعاملين لا يضيع أجر من أحسن عملاً. بل يقولون: افترى محمد على الله كذباً، فأبطل الله دعواهم: فإن يشأ الله يطبع على قلبك فتنسى القرآن ولا تقدر على النطق به، فكيف يقال إنه يفتري والله قادر على منعه؟ ومن شأنه تعالى أن يمحو الباطل ويحق الحق بالقرآن، وقد فعل، فما مات رسول الله ﷺ وفي الجزيرة من يعبد غير الله، ولو كان القرآن مفترى ما محا باطلاً ولا أحق حقاً. وهو الذي يقبل التوبة عن عباده إن تابوا إليه، ويعفو عن سيئاتهم فلا يؤاخذهم بها، ويعلم ما يفعلون في السر والعلن. ويجيب دعاء الذين آمنوا وعملوا الصالحات، ويزيدهم من فضله فيعطيهم ما لم يطلبوه، فما أعظم كرمه! وأما الكافرون فلهم عذاب شديد.", "h": ["تقرير حق القرابة ووجوب المودّة فيها، واحترام قرابة الرسول ﷺ وتقديرها.", "تبرئة رسول الله ﷺ من الافتراء على الله عز وجل.", "مضاعفة الحسنات، وشكر الله للصالحات من أعمال عباده المؤمنين.", "وجوب التوبة وقبول الله تعالى لها، وقد كان رسول الله ﷺ يتوب إلى الله في اليوم مائة مرة. وللتوبة ثلاثة شروط: الإقلاع الفوري عن المعصية، والاستغفار، والندم على ما فعل من المعصية بترك الواجب أو بفعل المحرم، وإن كان الذنب يتعلق بحق آدمي زاد شرط رابع، وهو التحلّل من الآدمي بأداء الحق أو بطلب العفو منه.", "وعد الله تعالى باستجابة دعاء المؤمنين العاملين للصالحات، وهم أولياء الله تعالى الذين إن سألوا أعطاهم، وإن استعاذوه أعاذهم، وإن استنصروه نصرهم."], "k": "«وهو الذي يقبل التوبة عن عباده ويعفو عن السيئات»… الباب مفتوح؛ فأي ذنب أؤجّل التوبة منه؟"}, {"lbl": "الآيات ٢٧ – ٣١", "q": "۞وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ لِعِبَادِهِۦ لَبَغَوۡاْ فِي ٱلۡأَرۡضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٖ مَّا يَشَآءُۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرُۢ بَصِيرٞ ﴿٢٧﴾ وَهُوَ ٱلَّذِي يُنَزِّلُ ٱلۡغَيۡثَ مِنۢ بَعۡدِ مَا قَنَطُواْ وَيَنشُرُ رَحۡمَتَهُۥۚ وَهُوَ ٱلۡوَلِيُّ ٱلۡحَمِيدُ ﴿٢٨﴾ وَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٖۚ وَهُوَ عَلَىٰ جَمۡعِهِمۡ إِذَا يَشَآءُ قَدِيرٞ ﴿٢٩﴾ وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٖ فَبِمَا كَسَبَتۡ أَيۡدِيكُمۡ وَيَعۡفُواْ عَن كَثِيرٖ ﴿٣٠﴾ وَمَآ أَنتُم بِمُعۡجِزِينَ فِي ٱلۡأَرۡضِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ ﴿٣١﴾", "w": [["ولو بسط الله الرزق لعباده", "لو وسّع الرزق لجميع عباده."], ["لبغوا في الأرض", "لطغوا في الأرض جميعاً."], ["ولكن ينزّل بقدر ما يشاء", "ينزل من الأرزاق بقدر ما يشاء فيبسط ويضيّق."], ["إنه بعباده خبير بصير", "بأحوالهم، إذ منهم من يفسده الغنى ومنهم من يصلحه، ومنهم من يصلحه الفقر ومنهم من يفسده."], ["ينزّل الغيث من بعد ما قنطوا", "المطر من بعد يأسهم من نزوله."], ["وينشر رحمته", "بركات المطر ومنافعه في كل سهل وجبل ونبات وحيوان."], ["وهو الوليّ الحميد", "المتولّي لعباده المؤمنين المحسن إليهم المحمود عندهم."], ["وما بثّ فيهما من دابة", "فرّق ونشر من كل ما يدبّ على الأرض من الناس وغيرهم."], ["وهو على جمعهم إذا يشاء قدير", "للحشر والحساب والجزاء يوم القيامة."], ["وما أصابكم من مصيبة", "بليّة وشدة كالمرض والفقر."], ["فبما كسبت أيديكم", "من الذنوب والآثام."], ["ويعفو عن كثير", "فلا يؤاخذ به، وما عفا عنه في الدنيا لا يؤاخذ به في الآخرة."], ["وما أنتم بمعجزين في الأرض", "لستم بفائتي الله ولا سابقيه هرباً منه إذا أراد مؤاخذتكم."]], "m": "هذا شروع في عرض مظاهر القدرة والعلم والحكمة الموجبة لربوبية الله المستلزمة لألوهيته: لو وسّع الله الرزق على عباده لطغى بعضهم على بعض وظلم بعضهم بعضاً، ولزم ذلك فساد كبير قد تتعطّل معه الحياة، ولكن ينزل من الأرزاق بمقادير محددة حسب تدبيره، إنه بما تتطلبه حياة عباده خبير بصير. ومظهر آخر: هو الذي ينزل الغيث من بعد ما قنطوا وينشر رحمته؛ فإنزال المطر بمقادير محددة في أماكن وظروف محددة ما قام إلا على القدرة القاهرة والخبرة التامة، يمنع عن عباده المطر حتى ييأسوا ويظهر عجزهم وعجز آلهتهم، ثم ينزل الغيث فتعمّ الأرزاق والبركات، وهو الولي الذي لا تصلح الولاية لغيره، الحميد المحمود بصنائع برّه. ومظهر آخر: ومن آياته خلق السماوات والأرض بما هما عليه من عجائب الصنعة، وما بثّ فيهما من دابة تدب على الأرض أو ملك يسبّح في السماء، فلِمَ يُعبد غيره؟ وفوق هذا قدرته على جمع سائر خلقه في صعيد واحد بعد إفنائهم وتصييرهم عظاماً ورفاتاً. ومظهر آخر: ما أصابكم من مصيبة في النفس والولد والمال فبما كسبت أيديكم، فكل مصاب ينزل بالإنسان في هذه الحياة ناتج عن مخالفة لله فيما وضع من القوانين والشرائع والسنن، وأعظم دلالة أن يُعطّل الله هذا القانون فيكسب العبد الذنب ولا يُؤاخذ به عفواً من الله، وهو قوله: ويعفو عن كثير. ومظهر آخر: أن الناس مهما أوتوا من قوة وعلم ما هم بمعجزين في الأرض، إن يشأ يخسف بهم الأرض أو يسقط عليهم السماء كسفاً، فلا مهرب إلا إلى الله بالاستسلام له، وما لكم من دون الله من ولي ولا نصير، ففرّوا إلى الله بالإيمان والإسلام تنجوا.", "h": ["بيان الحكمة في تقدير الأرزاق وإعطائها بمقادير محددة.", "من مظاهر ربوبية الله تعالى الموجبة لألوهيته على عباده: إنزال الغيث بعد اليأس والقنوط، وخلق السماوات والأرض وما بثّ فيهما من دابة.", "بيان حقيقة علمية ثابتة، وهي أن المخالفة للقوانين يترتب عليها ضرر يصيب المخالف.", "بيان أنه ما من مصيبة تصيب المرء في نفسه أو ولده أو ماله إلا بذنب ارتكبه."], "k": "«ولو بسط الله الرزق لعباده لبغوا»… ما ضيّقه عليّ قد يكون حماية لي؛ فهل أرضى بتقديره؟"}, {"lbl": "الآيات ٣٢ – ٣٥", "q": "وَمِنۡ ءَايَٰتِهِ ٱلۡجَوَارِ فِي ٱلۡبَحۡرِ كَٱلۡأَعۡلَٰمِ ﴿٣٢﴾ إِن يَشَأۡ يُسۡكِنِ ٱلرِّيحَ فَيَظۡلَلۡنَ رَوَاكِدَ عَلَىٰ ظَهۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٍ ﴿٣٣﴾ أَوۡ يُوبِقۡهُنَّ بِمَا كَسَبُواْ وَيَعۡفُ عَن كَثِيرٖ ﴿٣٤﴾ وَيَعۡلَمَ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصٖ ﴿٣٥﴾", "w": [["ومن آياته الجوار في البحر كالأعلام", "من علامات ربوبيته إيجاد السفن كالجبال في البحار، وتسخير البحار للسير فيها لمنافع العباد."], ["إن يشأ يُسكن الريح", "يوقف هبوب الريح فلا نسيم ولا عواصف."], ["فيظللن رواكد على ظهره", "تقف السفن وتظل راكدة حابسة على ظهر البحر."], ["إن في ذلك لآيات", "في خلق السفن والبحار وتسخيرها وسير السفن وركودها عند سكون الرياح دلالات واضحة على وجود الله وقدرته وعلمه وحكمته."], ["لكل صبّار شكور", "لا يراها ولا ينتفع بها إلا من كان صبّاراً عند الشدائد شكوراً عند النعم."], ["أو يوبقهنّ بما كسبوا", "وإن يشأ يجعل الرياح عواصف فيهلك تلك السفن ويغرقها بمن فيها بسبب ذنوب أصحابها."], ["ويعفُ عن كثير", "يعفو عن كثير من الذنوب، إذ لو آخذ بكل ذنب ما بقي أحد على وجه الأرض."], ["ويعلم الذين يجادلون في آياتنا", "يعلم المكذبون بآيات الله من المشركين عندما تعصف العواصف وتضطرب السفن."], ["ما لهم من محيص", "ليس لهم من مهرب إلا إلى الله، فيجأرون بدعائه وحده ناسين آلهتهم الباطلة."]], "m": "ما زال السياق في ذكر مظاهر الربوبية المستلزمة لألوهية الله: ومن حججه عليكم الدالة على قدرته وعلمه ورحمته هذه السفن الجارية في البحر كأنها جبال عالية، تسير من إقليم إلى إقليم بتسخير الله البحار وإرسال الرياح، تنقل الركاب والبضائع، وإن يشأ يسكن الريح فتقف السفن راكدة على سطح الماء فلا تتحرك، وإن يشأ يرسل عليها عواصف فتضطرب وتغرق بما فيها ومن فيها، وذلك بذنوب أصحابها، إذ القاعدة الثابتة أنه ما من مصيبة إلا بذنب. إن في ذلك لحجج واضحة على وجود الله وقدرته، ولكن لا يراها ولا ينتفع بها أمثال البهائم، بل هي من نصيب كل عبد صبّار على طاعة الله وبلائه شكور لآلائه. ويعفو عن كثير فلا يؤاخذ بكل ذنب، إذ لو عاقب على كل خطيئة لما بقي على الأرض أحد، فما من أحد إلا ويذنب إلا المعصومين من الأنبياء والمرسلين. وعندما تعصف الريح وتشرف السفن على الغرق يعلم المشركون الذين يجادلون في الوحي ما لهم من ملجأ ولا مهرب من الله إلا إليه، فيجأرون بدعائه وحده، كما قال: فإذا ركبوا في الفلك دعوا الله مخلصين له الدين.", "h": ["مظاهر ربوبية الله وألوهيته على خلقه.", "فضل الصبر والشكر، وفضيلة الصابرين الشاكرين.", "تقرير قاعدة: ما من مصيبة إلا بذنب، مع عفو الله عن كثير.", "عند معاينة العذاب يعرف الإنسان ربه ولا يعرف غيره."], "k": "«لكل صبّار شكور»… الصبر في الضيق والشكر في السعة؛ فأيهما أضعف فيّ اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 356;
insert into public.tdb_cards(topic, i, body) select 356, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٢ – ٢٦", "q": "تَرَى ٱلظَّـٰلِمِينَ مُشۡفِقِينَ مِمَّا كَسَبُواْ وَهُوَ وَاقِعُۢ بِهِمۡۗ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فِي رَوۡضَاتِ ٱلۡجَنَّاتِۖ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ ﴿٢٢﴾ ذَٰلِكَ ٱلَّذِي يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِۗ قُل لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًا إِلَّا ٱلۡمَوَدَّةَ فِي ٱلۡقُرۡبَىٰۗ وَمَن يَقۡتَرِفۡ حَسَنَةٗ نَّزِدۡ لَهُۥ فِيهَا حُسۡنًاۚ إِنَّ ٱللَّهَ غَفُورٞ شَكُورٌ ﴿٢٣﴾ أَمۡ يَقُولُونَ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗاۖ فَإِن يَشَإِ ٱللَّهُ يَخۡتِمۡ عَلَىٰ قَلۡبِكَۗ وَيَمۡحُ ٱللَّهُ ٱلۡبَٰطِلَ وَيُحِقُّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦٓۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٢٤﴾ وَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَعۡفُواْ عَنِ ٱلسَّيِّـَٔاتِ وَيَعۡلَمُ مَا تَفۡعَلُونَ ﴿٢٥﴾ وَيَسۡتَجِيبُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضۡلِهِۦۚ وَٱلۡكَٰفِرُونَ لَهُمۡ عَذَابٞ شَدِيدٞ ﴿٢٦﴾", "w": [["ترى الظالمين مشفقين مما كسبوا", "ترى الظالمين يوم القيامة خائفين من جزاء ما كسبوا."], ["وهو واقع بهم", "جزاء ما كسبوا من الباطل والشرك نازل بهم لا محالة."], ["في روضات الجنات", "والروضة في الجنة أنزه مكان فيها."], ["لهم ما يشاؤون عند ربهم", "لهم فيها ما تشتهيه أنفسهم وتلذّه أعينهم في جوار ربهم."], ["قل لا أسألكم عليه أجراً", "لا أسألكم على التبليغ ثواباً."], ["إلا المودّة في القربى", "لكن أسألكم أن تودّوا قرابتي فتمنعوني حتى أبلّغ رسالتي."], ["ومن يقترف حسنة", "من يكتسب حسنة بقول أو عمل صالح."], ["نزد له فيها حُسناً", "نضاعفها له أضعافاً."], ["أم يقولون افترى على الله كذباً", "أيقول المشركون إن محمداً افترى على الله كذباً فنسب إليه القرآن؟"], ["فإن يشأ الله يختم على قلبك", "إن يشأ يطبع على قلبك وينسك القرآن، فالله قادر على أن يمنعك من الافتراء عليه."], ["ويمحُ الله الباطل ويُحقّ الحق بكلماته", "من شأنه أنه يمحو الباطل ويحق الحق بالآيات القرآنية، وقد فعل."], ["ويعفو عن السيئات", "لا يؤاخذ بها من تاب منها."], ["ويستجيب الذين آمنوا", "يجيب عباده المؤمنين إلى ما دعوه فيه فيعطيهم سؤلهم."], ["ويزيدهم من فضله", "يعطيهم ما لم يسألوه من الخير."]], "m": "ترى الظالمين يوم القيامة خائفين من جزاء ما كسبوا من الشرك والمعاصي، وهو واقع بهم لا محالة، وفي الوقت ذاته يكون الذين آمنوا بالله رباً وبالإسلام ديناً وبمحمد رسولاً وعملوا الصالحات في روضات الجنات، وهي أنزهها وأحسنها، لهم ما يشاؤون مما تشتهيه الأنفس وتلذّه الأعين في جوار رب كريم، ذلك هو الفضل الكبير، وذلك الذي يبشّر الله به عباده المؤمنين في كتابه وعلى لسان رسوله. قل لقومك: لا أسألكم على إبلاغي إياكم دعوة ربي مالاً، لكن أسألكم أن تودّوا قرابتي منكم فلا تؤذوني وتمنعوني من الناس حتى أبلّغ دعوة ربي. ومن يعمل حسنة نضاعفها له، إن الله غفور للتائبين شكور للعاملين لا يضيع أجر من أحسن عملاً. بل يقولون: افترى محمد على الله كذباً، فأبطل الله دعواهم: فإن يشأ الله يطبع على قلبك فتنسى القرآن ولا تقدر على النطق به، فكيف يقال إنه يفتري والله قادر على منعه؟ ومن شأنه تعالى أن يمحو الباطل ويحق الحق بالقرآن، وقد فعل، فما مات رسول الله ﷺ وفي الجزيرة من يعبد غير الله، ولو كان القرآن مفترى ما محا باطلاً ولا أحق حقاً. وهو الذي يقبل التوبة عن عباده إن تابوا إليه، ويعفو عن سيئاتهم فلا يؤاخذهم بها، ويعلم ما يفعلون في السر والعلن. ويجيب دعاء الذين آمنوا وعملوا الصالحات، ويزيدهم من فضله فيعطيهم ما لم يطلبوه، فما أعظم كرمه! وأما الكافرون فلهم عذاب شديد.", "h": ["تقرير حق القرابة ووجوب المودّة فيها، واحترام قرابة الرسول ﷺ وتقديرها.", "تبرئة رسول الله ﷺ من الافتراء على الله عز وجل.", "مضاعفة الحسنات، وشكر الله للصالحات من أعمال عباده المؤمنين.", "وجوب التوبة وقبول الله تعالى لها، وقد كان رسول الله ﷺ يتوب إلى الله في اليوم مائة مرة. وللتوبة ثلاثة شروط: الإقلاع الفوري عن المعصية، والاستغفار، والندم على ما فعل من المعصية بترك الواجب أو بفعل المحرم، وإن كان الذنب يتعلق بحق آدمي زاد شرط رابع، وهو التحلّل من الآدمي بأداء الحق أو بطلب العفو منه.", "وعد الله تعالى باستجابة دعاء المؤمنين العاملين للصالحات، وهم أولياء الله تعالى الذين إن سألوا أعطاهم، وإن استعاذوه أعاذهم، وإن استنصروه نصرهم."], "k": "«وهو الذي يقبل التوبة عن عباده ويعفو عن السيئات»… الباب مفتوح؛ فأي ذنب أؤجّل التوبة منه؟"}, {"lbl": "الآيات ٢٧ – ٣١", "q": "۞وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ لِعِبَادِهِۦ لَبَغَوۡاْ فِي ٱلۡأَرۡضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٖ مَّا يَشَآءُۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرُۢ بَصِيرٞ ﴿٢٧﴾ وَهُوَ ٱلَّذِي يُنَزِّلُ ٱلۡغَيۡثَ مِنۢ بَعۡدِ مَا قَنَطُواْ وَيَنشُرُ رَحۡمَتَهُۥۚ وَهُوَ ٱلۡوَلِيُّ ٱلۡحَمِيدُ ﴿٢٨﴾ وَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٖۚ وَهُوَ عَلَىٰ جَمۡعِهِمۡ إِذَا يَشَآءُ قَدِيرٞ ﴿٢٩﴾ وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٖ فَبِمَا كَسَبَتۡ أَيۡدِيكُمۡ وَيَعۡفُواْ عَن كَثِيرٖ ﴿٣٠﴾ وَمَآ أَنتُم بِمُعۡجِزِينَ فِي ٱلۡأَرۡضِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ ﴿٣١﴾", "w": [["ولو بسط الله الرزق لعباده", "لو وسّع الرزق لجميع عباده."], ["لبغوا في الأرض", "لطغوا في الأرض جميعاً."], ["ولكن ينزّل بقدر ما يشاء", "ينزل من الأرزاق بقدر ما يشاء فيبسط ويضيّق."], ["إنه بعباده خبير بصير", "بأحوالهم، إذ منهم من يفسده الغنى ومنهم من يصلحه، ومنهم من يصلحه الفقر ومنهم من يفسده."], ["ينزّل الغيث من بعد ما قنطوا", "المطر من بعد يأسهم من نزوله."], ["وينشر رحمته", "بركات المطر ومنافعه في كل سهل وجبل ونبات وحيوان."], ["وهو الوليّ الحميد", "المتولّي لعباده المؤمنين المحسن إليهم المحمود عندهم."], ["وما بثّ فيهما من دابة", "فرّق ونشر من كل ما يدبّ على الأرض من الناس وغيرهم."], ["وهو على جمعهم إذا يشاء قدير", "للحشر والحساب والجزاء يوم القيامة."], ["وما أصابكم من مصيبة", "بليّة وشدة كالمرض والفقر."], ["فبما كسبت أيديكم", "من الذنوب والآثام."], ["ويعفو عن كثير", "فلا يؤاخذ به، وما عفا عنه في الدنيا لا يؤاخذ به في الآخرة."], ["وما أنتم بمعجزين في الأرض", "لستم بفائتي الله ولا سابقيه هرباً منه إذا أراد مؤاخذتكم."]], "m": "هذا شروع في عرض مظاهر القدرة والعلم والحكمة الموجبة لربوبية الله المستلزمة لألوهيته: لو وسّع الله الرزق على عباده لطغى بعضهم على بعض وظلم بعضهم بعضاً، ولزم ذلك فساد كبير قد تتعطّل معه الحياة، ولكن ينزل من الأرزاق بمقادير محددة حسب تدبيره، إنه بما تتطلبه حياة عباده خبير بصير. ومظهر آخر: هو الذي ينزل الغيث من بعد ما قنطوا وينشر رحمته؛ فإنزال المطر بمقادير محددة في أماكن وظروف محددة ما قام إلا على القدرة القاهرة والخبرة التامة، يمنع عن عباده المطر حتى ييأسوا ويظهر عجزهم وعجز آلهتهم، ثم ينزل الغيث فتعمّ الأرزاق والبركات، وهو الولي الذي لا تصلح الولاية لغيره، الحميد المحمود بصنائع برّه. ومظهر آخر: ومن آياته خلق السماوات والأرض بما هما عليه من عجائب الصنعة، وما بثّ فيهما من دابة تدب على الأرض أو ملك يسبّح في السماء، فلِمَ يُعبد غيره؟ وفوق هذا قدرته على جمع سائر خلقه في صعيد واحد بعد إفنائهم وتصييرهم عظاماً ورفاتاً. ومظهر آخر: ما أصابكم من مصيبة في النفس والولد والمال فبما كسبت أيديكم، فكل مصاب ينزل بالإنسان في هذه الحياة ناتج عن مخالفة لله فيما وضع من القوانين والشرائع والسنن، وأعظم دلالة أن يُعطّل الله هذا القانون فيكسب العبد الذنب ولا يُؤاخذ به عفواً من الله، وهو قوله: ويعفو عن كثير. ومظهر آخر: أن الناس مهما أوتوا من قوة وعلم ما هم بمعجزين في الأرض، إن يشأ يخسف بهم الأرض أو يسقط عليهم السماء كسفاً، فلا مهرب إلا إلى الله بالاستسلام له، وما لكم من دون الله من ولي ولا نصير، ففرّوا إلى الله بالإيمان والإسلام تنجوا.", "h": ["بيان الحكمة في تقدير الأرزاق وإعطائها بمقادير محددة.", "من مظاهر ربوبية الله تعالى الموجبة لألوهيته على عباده: إنزال الغيث بعد اليأس والقنوط، وخلق السماوات والأرض وما بثّ فيهما من دابة.", "بيان حقيقة علمية ثابتة، وهي أن المخالفة للقوانين يترتب عليها ضرر يصيب المخالف.", "بيان أنه ما من مصيبة تصيب المرء في نفسه أو ولده أو ماله إلا بذنب ارتكبه."], "k": "«ولو بسط الله الرزق لعباده لبغوا»… ما ضيّقه عليّ قد يكون حماية لي؛ فهل أرضى بتقديره؟"}, {"lbl": "الآيات ٣٢ – ٣٥", "q": "وَمِنۡ ءَايَٰتِهِ ٱلۡجَوَارِ فِي ٱلۡبَحۡرِ كَٱلۡأَعۡلَٰمِ ﴿٣٢﴾ إِن يَشَأۡ يُسۡكِنِ ٱلرِّيحَ فَيَظۡلَلۡنَ رَوَاكِدَ عَلَىٰ ظَهۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٍ ﴿٣٣﴾ أَوۡ يُوبِقۡهُنَّ بِمَا كَسَبُواْ وَيَعۡفُ عَن كَثِيرٖ ﴿٣٤﴾ وَيَعۡلَمَ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصٖ ﴿٣٥﴾", "w": [["ومن آياته الجوار في البحر كالأعلام", "من علامات ربوبيته إيجاد السفن كالجبال في البحار، وتسخير البحار للسير فيها لمنافع العباد."], ["إن يشأ يُسكن الريح", "يوقف هبوب الريح فلا نسيم ولا عواصف."], ["فيظللن رواكد على ظهره", "تقف السفن وتظل راكدة حابسة على ظهر البحر."], ["إن في ذلك لآيات", "في خلق السفن والبحار وتسخيرها وسير السفن وركودها عند سكون الرياح دلالات واضحة على وجود الله وقدرته وعلمه وحكمته."], ["لكل صبّار شكور", "لا يراها ولا ينتفع بها إلا من كان صبّاراً عند الشدائد شكوراً عند النعم."], ["أو يوبقهنّ بما كسبوا", "وإن يشأ يجعل الرياح عواصف فيهلك تلك السفن ويغرقها بمن فيها بسبب ذنوب أصحابها."], ["ويعفُ عن كثير", "يعفو عن كثير من الذنوب، إذ لو آخذ بكل ذنب ما بقي أحد على وجه الأرض."], ["ويعلم الذين يجادلون في آياتنا", "يعلم المكذبون بآيات الله من المشركين عندما تعصف العواصف وتضطرب السفن."], ["ما لهم من محيص", "ليس لهم من مهرب إلا إلى الله، فيجأرون بدعائه وحده ناسين آلهتهم الباطلة."]], "m": "ما زال السياق في ذكر مظاهر الربوبية المستلزمة لألوهية الله: ومن حججه عليكم الدالة على قدرته وعلمه ورحمته هذه السفن الجارية في البحر كأنها جبال عالية، تسير من إقليم إلى إقليم بتسخير الله البحار وإرسال الرياح، تنقل الركاب والبضائع، وإن يشأ يسكن الريح فتقف السفن راكدة على سطح الماء فلا تتحرك، وإن يشأ يرسل عليها عواصف فتضطرب وتغرق بما فيها ومن فيها، وذلك بذنوب أصحابها، إذ القاعدة الثابتة أنه ما من مصيبة إلا بذنب. إن في ذلك لحجج واضحة على وجود الله وقدرته، ولكن لا يراها ولا ينتفع بها أمثال البهائم، بل هي من نصيب كل عبد صبّار على طاعة الله وبلائه شكور لآلائه. ويعفو عن كثير فلا يؤاخذ بكل ذنب، إذ لو عاقب على كل خطيئة لما بقي على الأرض أحد، فما من أحد إلا ويذنب إلا المعصومين من الأنبياء والمرسلين. وعندما تعصف الريح وتشرف السفن على الغرق يعلم المشركون الذين يجادلون في الوحي ما لهم من ملجأ ولا مهرب من الله إلا إليه، فيجأرون بدعائه وحده، كما قال: فإذا ركبوا في الفلك دعوا الله مخلصين له الدين.", "h": ["مظاهر ربوبية الله وألوهيته على خلقه.", "فضل الصبر والشكر، وفضيلة الصابرين الشاكرين.", "تقرير قاعدة: ما من مصيبة إلا بذنب، مع عفو الله عن كثير.", "عند معاينة العذاب يعرف الإنسان ربه ولا يعرف غيره."], "k": "«لكل صبّار شكور»… الصبر في الضيق والشكر في السعة؛ فأيهما أضعف فيّ اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (357, 42, 36, 46, 'سورة الشورى ٣٦ – ٤٦', 'الشورى: صفات أهل ما عند الله خير وأبقى', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 357) = $j$[{"lbl": "الآيات ٣٦ – ٤١", "q": "فَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰ لِلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ﴿٣٦﴾ وَٱلَّذِينَ يَجۡتَنِبُونَ كَبَـٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ وَإِذَا مَا غَضِبُواْ هُمۡ يَغۡفِرُونَ ﴿٣٧﴾ وَٱلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ﴿٣٨﴾ وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلۡبَغۡيُ هُمۡ يَنتَصِرُونَ ﴿٣٩﴾ وَجَزَـٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّـٰلِمِينَ ﴿٤٠﴾ وَلَمَنِ ٱنتَصَرَ بَعۡدَ ظُلۡمِهِۦ فَأُوْلَـٰٓئِكَ مَا عَلَيۡهِم مِّن سَبِيلٍ ﴿٤١﴾", "w": [["فما أوتيتم من شيء", "ما أُعطيتم من متاع الدنيا كالمال والولد والمطعم والمشرب والملبس والمسكن والمنكح والمركب."], ["فمتاع الحياة الدنيا", "يُتمتّع به زمناً ثم يزول ولا يبقى."], ["وما عند الله خير وأبقى", "ما عند الله من ثواب الآخرة خير في نوعه وأبقى في مدته."], ["للذين آمنوا وعلى ربهم يتوكلون", "لأصحاب الصفات التالية: الإيمان، والتوكل على الله، واجتناب كبائر الإثم والفواحش، والتجاوز عمن أساء إليهم، والاستجابة لربهم، وإقام الصلاة، والمشورة بينهم، والإنفاق مما رزقهم الله، والانتصار عند البغي عليهم."], ["وجزاء سيئة سيئة مثلها", "جزاء سيئة المسيء عقوبته بما أوجبه الله عليه."], ["فمن عفا وأصلح فأجره على الله", "من عفا عمن أساء إليه وأصلح ما بينه وبينه فأجره على الله."], ["إنه لا يحب الظالمين", "لا يحب البادئين بالظلم، ومن لم يحبه الله أذن في عقوبته."], ["ولمن انتصر بعد ظلمه", "ومن ظلمه ظالم فأخذ منه بحقه."], ["فأولئك ما عليهم من سبيل", "لمؤاخذتهم، لأنهم ما بدؤوا بالظلم."]], "m": "هذا شروع في بيان صفات الكمال في المسلم التي يستوجب بها نعيم الآخرة، ضمن التعريض بزينة الدنيا الفانية: فما أوتيتم أيها الناس من شيء في هذه الحياة من لذيذ الطعام والشراب وجميل اللباس وفاخر المساكن وأفره المراكب فمتاع يزول ويفنى، وما أعدّه الله لأوليائه في الآخرة خير وأبقى، لمن؟ للذين آمنوا بالله وآياته ولقائه ورسوله، والذين على ربهم لا على سواه يتوكلون ثقة في كفايته، والذين يتركون كبائر الإثم كالشرك والقتل والظلم وشرب الخمر وأكل الحرام، والفواحش كالزنى واللواط، والذين إذا غضبوا يتجاوزون عمن أغضبهم ويغفرون زلته، والذين استجابوا لربهم في كل ما طلبه منهم، وأقاموا الصلاة فأدّوها على وجهها مراعين شرائطها وأركانها وواجباتها وسننها وآدابها، وأمرهم الذي يهمّهم أفراداً وجماعات يتشاورون فيه ويأخذون بما يلهمهم ربهم من الصواب، ومما رزقهم الله من مال وعلم وجاه وصحة ينفقون شكراً لله، والذين إذا بغى عليهم الظلمة من الكافرين ينتصرون لأنفسهم إكراماً لها لأن الله وليّها فالعزة واجبة لها. هذه عشر صفات متى اتصف بها العبد لا يضره شيء لو عاش الدهر كله فقيراً محروماً من لذيذ الطعام وجميل اللباس، إذ ما عند الله خير له وأبقى، مع أن أهلها لا يُحرمون من طيبات الدنيا بل هم أولى بها. وجزاء سيئة المسيء عقوبته بما أوجب الله في كتابه أو على لسان رسوله، فمن عفا عمن أساء إليه وأصلح ما بينه وبينه فعادت المودة فأجره على الله، وهو خير له من شفاء صدره بعقوبة أخيه، إنه لا يحب الظالمين، فضاعف الأجر للمظلوم إذا عفا وأصلح. والذي ظُلم فانتصر لنفسه وردّ الظلم عنها فلا سبيل إلى عقوبته؛ هذا حكم الله وشرعه.", "h": ["متاع الحياة الدنيا إذا قوبل بما أعدّ الله للمؤمنين المتقين لا يُعدّ شيئاً يُذكر أبداً.", "بيان أكمل الشخصيات الإسلامية، وهي الشخصية التي تتصف بالصفات العشر التي تضمّنتها هذه الآيات.", "مشروعية القصاص وعقوبة الظالم.", "عدم مؤاخذة من ظُلم فأخذ بحقه بلا زيادة عنه ما لم يكن حداً، فإن الحدود يقيمها الإمام.", "فضيلة العفو عن الإخوة المسلمين والإصلاح بينهم."], "k": "«وإذا ما غضبوا هم يغفرون»… آخر مرة غضبت، هل غفرت أم حملت في قلبي؟"}, {"lbl": "الآيات ٤٢ – ٤٦", "q": "إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظۡلِمُونَ ٱلنَّاسَ وَيَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۚ أُوْلَـٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ ﴿٤٢﴾ وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنۡ عَزۡمِ ٱلۡأُمُورِ ﴿٤٣﴾ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِيّٖ مِّنۢ بَعۡدِهِۦۗ وَتَرَى ٱلظَّـٰلِمِينَ لَمَّا رَأَوُاْ ٱلۡعَذَابَ يَقُولُونَ هَلۡ إِلَىٰ مَرَدّٖ مِّن سَبِيلٖ ﴿٤٤﴾ وَتَرَىٰهُمۡ يُعۡرَضُونَ عَلَيۡهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرۡفٍ خَفِيّٖۗ وَقَالَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ ٱلظَّـٰلِمِينَ فِي عَذَابٖ مُّقِيمٖ ﴿٤٥﴾ وَمَا كَانَ لَهُم مِّنۡ أَوۡلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ٱللَّهِۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ ﴿٤٦﴾", "w": [["إنما السبيل", "بالعقوبة والأذية."], ["على الذين يظلمون الناس", "يعتدون عليهم في أعراضهم أو أبدانهم أو أموالهم."], ["ويبغون في الأرض بغير الحق", "يطلبون الفساد فيها بالشرك والظلم والإجرام."], ["ولمن صبر وغفر", "صبر فلم ينتصر لنفسه، وغفر وتجاوز عمن أساء إليه."], ["إن ذلك لمن عزم الأمور", "إن الصبر والتجاوز لمن معزومات الأمور المطلوبة شرعاً."], ["ومن يضلل الله", "حسب سنته في الإضلال."], ["فما له من ولي من بعده", "ليس له من أحد يتولّى هدايته ويقدر عليها."], ["هل إلى مردّ من سبيل", "هل من طريق نسلكه لنعود إلى الدنيا؟"], ["وتراهم يُعرضون عليها خاشعين", "على النار، خائفين متواضعين من الذل."], ["ينظرون من طرف خفيّ", "من عين ضعيفة النظر، كما ينظر المقتول إلى السيف لا يملأ عينه منه."], ["خسروا أنفسهم وأهليهم يوم القيامة", "لخلودهم في النار وعدم وصولهم إلى الحور العين في دار السلام."], ["في عذاب مقيم", "دائم لا يخرجون منه، وهو عذاب الجحيم."], ["فما له من سبيل", "طريق إلى الهداية في الدنيا وإلى الجنة يوم القيامة."]], "m": "لما نفى عن المنتصرين بعد ظلمهم السبيل إلى عقوبتهم، أثبت هنا أن السبيل إلى العقوبة على الذين يظلمون الناس بالاعتداء عليهم في أبدانهم أو أعراضهم أو أموالهم، ويطلبون الفساد في الأرض بالشرك والظلم والمعاصي، وليس فيها من حق يبيحها، أولئك لهم عذاب أليم في الدنيا بعقوبتهم الصارمة، ويوم القيامة إن لم يتوبوا. ولمن صبر فلم ينتصر لنفسه من أخيه المسلم، وغفر له زلّته، إن ذلك من معزومات الأمور المطلوبة شرعاً. ومن يضلّه الله حسب سنته فليس له من أحد يهديه بعد الله. وترى المشركين لما رأوا عذاب النار يقولون متمنّين الرجوع إلى الدنيا ليؤمنوا: هل إلى مردّ من سبيل؟ وتراهم يُعرضون على النار خاضعين من الذل، يسترقون النظر لا يملؤون أعينهم منها لشدة خوفهم. وهنا يقول الذين آمنوا: إن الخاسرين حقاً الذين خسروا أنفسهم وأهليهم يوم القيامة بخلودهم في النار وحرمانهم من الحور العين في الجنة، ويُعلن معلن: ألا إن الظالمين لأنفسهم بالشرك والمعاصي في عذاب مقيم لا يزول. وما كان لهم من أولياء ينصرونهم بتخليصهم من العذاب من دون الله، ومن يضلل الله فما له طريق إلى الهداية في الدنيا ولا إلى الجنة يوم القيامة.", "h": ["لا سبيل إلى معاقبة من انتصر لنفسه بعد ظلمه.", "وجوب معاقبة الظالم والضرب على يديه.", "فضيلة الصبر والتجاوز عن المسلم إذا أساء بقول أو عمل.", "لا أعظم خسراناً ممن يخلد في النار ويُحرم الجنة وما فيها من نعيم مقيم."], "k": "«ولمن صبر وغفر إن ذلك لمن عزم الأمور»… الانتصار مباح والعفو عزيمة؛ فبأيهما أرتقي اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 357;
insert into public.tdb_cards(topic, i, body) select 357, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٦ – ٤١", "q": "فَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰ لِلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ﴿٣٦﴾ وَٱلَّذِينَ يَجۡتَنِبُونَ كَبَـٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ وَإِذَا مَا غَضِبُواْ هُمۡ يَغۡفِرُونَ ﴿٣٧﴾ وَٱلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ﴿٣٨﴾ وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلۡبَغۡيُ هُمۡ يَنتَصِرُونَ ﴿٣٩﴾ وَجَزَـٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّـٰلِمِينَ ﴿٤٠﴾ وَلَمَنِ ٱنتَصَرَ بَعۡدَ ظُلۡمِهِۦ فَأُوْلَـٰٓئِكَ مَا عَلَيۡهِم مِّن سَبِيلٍ ﴿٤١﴾", "w": [["فما أوتيتم من شيء", "ما أُعطيتم من متاع الدنيا كالمال والولد والمطعم والمشرب والملبس والمسكن والمنكح والمركب."], ["فمتاع الحياة الدنيا", "يُتمتّع به زمناً ثم يزول ولا يبقى."], ["وما عند الله خير وأبقى", "ما عند الله من ثواب الآخرة خير في نوعه وأبقى في مدته."], ["للذين آمنوا وعلى ربهم يتوكلون", "لأصحاب الصفات التالية: الإيمان، والتوكل على الله، واجتناب كبائر الإثم والفواحش، والتجاوز عمن أساء إليهم، والاستجابة لربهم، وإقام الصلاة، والمشورة بينهم، والإنفاق مما رزقهم الله، والانتصار عند البغي عليهم."], ["وجزاء سيئة سيئة مثلها", "جزاء سيئة المسيء عقوبته بما أوجبه الله عليه."], ["فمن عفا وأصلح فأجره على الله", "من عفا عمن أساء إليه وأصلح ما بينه وبينه فأجره على الله."], ["إنه لا يحب الظالمين", "لا يحب البادئين بالظلم، ومن لم يحبه الله أذن في عقوبته."], ["ولمن انتصر بعد ظلمه", "ومن ظلمه ظالم فأخذ منه بحقه."], ["فأولئك ما عليهم من سبيل", "لمؤاخذتهم، لأنهم ما بدؤوا بالظلم."]], "m": "هذا شروع في بيان صفات الكمال في المسلم التي يستوجب بها نعيم الآخرة، ضمن التعريض بزينة الدنيا الفانية: فما أوتيتم أيها الناس من شيء في هذه الحياة من لذيذ الطعام والشراب وجميل اللباس وفاخر المساكن وأفره المراكب فمتاع يزول ويفنى، وما أعدّه الله لأوليائه في الآخرة خير وأبقى، لمن؟ للذين آمنوا بالله وآياته ولقائه ورسوله، والذين على ربهم لا على سواه يتوكلون ثقة في كفايته، والذين يتركون كبائر الإثم كالشرك والقتل والظلم وشرب الخمر وأكل الحرام، والفواحش كالزنى واللواط، والذين إذا غضبوا يتجاوزون عمن أغضبهم ويغفرون زلته، والذين استجابوا لربهم في كل ما طلبه منهم، وأقاموا الصلاة فأدّوها على وجهها مراعين شرائطها وأركانها وواجباتها وسننها وآدابها، وأمرهم الذي يهمّهم أفراداً وجماعات يتشاورون فيه ويأخذون بما يلهمهم ربهم من الصواب، ومما رزقهم الله من مال وعلم وجاه وصحة ينفقون شكراً لله، والذين إذا بغى عليهم الظلمة من الكافرين ينتصرون لأنفسهم إكراماً لها لأن الله وليّها فالعزة واجبة لها. هذه عشر صفات متى اتصف بها العبد لا يضره شيء لو عاش الدهر كله فقيراً محروماً من لذيذ الطعام وجميل اللباس، إذ ما عند الله خير له وأبقى، مع أن أهلها لا يُحرمون من طيبات الدنيا بل هم أولى بها. وجزاء سيئة المسيء عقوبته بما أوجب الله في كتابه أو على لسان رسوله، فمن عفا عمن أساء إليه وأصلح ما بينه وبينه فعادت المودة فأجره على الله، وهو خير له من شفاء صدره بعقوبة أخيه، إنه لا يحب الظالمين، فضاعف الأجر للمظلوم إذا عفا وأصلح. والذي ظُلم فانتصر لنفسه وردّ الظلم عنها فلا سبيل إلى عقوبته؛ هذا حكم الله وشرعه.", "h": ["متاع الحياة الدنيا إذا قوبل بما أعدّ الله للمؤمنين المتقين لا يُعدّ شيئاً يُذكر أبداً.", "بيان أكمل الشخصيات الإسلامية، وهي الشخصية التي تتصف بالصفات العشر التي تضمّنتها هذه الآيات.", "مشروعية القصاص وعقوبة الظالم.", "عدم مؤاخذة من ظُلم فأخذ بحقه بلا زيادة عنه ما لم يكن حداً، فإن الحدود يقيمها الإمام.", "فضيلة العفو عن الإخوة المسلمين والإصلاح بينهم."], "k": "«وإذا ما غضبوا هم يغفرون»… آخر مرة غضبت، هل غفرت أم حملت في قلبي؟"}, {"lbl": "الآيات ٤٢ – ٤٦", "q": "إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظۡلِمُونَ ٱلنَّاسَ وَيَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۚ أُوْلَـٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ ﴿٤٢﴾ وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنۡ عَزۡمِ ٱلۡأُمُورِ ﴿٤٣﴾ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِيّٖ مِّنۢ بَعۡدِهِۦۗ وَتَرَى ٱلظَّـٰلِمِينَ لَمَّا رَأَوُاْ ٱلۡعَذَابَ يَقُولُونَ هَلۡ إِلَىٰ مَرَدّٖ مِّن سَبِيلٖ ﴿٤٤﴾ وَتَرَىٰهُمۡ يُعۡرَضُونَ عَلَيۡهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرۡفٍ خَفِيّٖۗ وَقَالَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ ٱلظَّـٰلِمِينَ فِي عَذَابٖ مُّقِيمٖ ﴿٤٥﴾ وَمَا كَانَ لَهُم مِّنۡ أَوۡلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ٱللَّهِۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ ﴿٤٦﴾", "w": [["إنما السبيل", "بالعقوبة والأذية."], ["على الذين يظلمون الناس", "يعتدون عليهم في أعراضهم أو أبدانهم أو أموالهم."], ["ويبغون في الأرض بغير الحق", "يطلبون الفساد فيها بالشرك والظلم والإجرام."], ["ولمن صبر وغفر", "صبر فلم ينتصر لنفسه، وغفر وتجاوز عمن أساء إليه."], ["إن ذلك لمن عزم الأمور", "إن الصبر والتجاوز لمن معزومات الأمور المطلوبة شرعاً."], ["ومن يضلل الله", "حسب سنته في الإضلال."], ["فما له من ولي من بعده", "ليس له من أحد يتولّى هدايته ويقدر عليها."], ["هل إلى مردّ من سبيل", "هل من طريق نسلكه لنعود إلى الدنيا؟"], ["وتراهم يُعرضون عليها خاشعين", "على النار، خائفين متواضعين من الذل."], ["ينظرون من طرف خفيّ", "من عين ضعيفة النظر، كما ينظر المقتول إلى السيف لا يملأ عينه منه."], ["خسروا أنفسهم وأهليهم يوم القيامة", "لخلودهم في النار وعدم وصولهم إلى الحور العين في دار السلام."], ["في عذاب مقيم", "دائم لا يخرجون منه، وهو عذاب الجحيم."], ["فما له من سبيل", "طريق إلى الهداية في الدنيا وإلى الجنة يوم القيامة."]], "m": "لما نفى عن المنتصرين بعد ظلمهم السبيل إلى عقوبتهم، أثبت هنا أن السبيل إلى العقوبة على الذين يظلمون الناس بالاعتداء عليهم في أبدانهم أو أعراضهم أو أموالهم، ويطلبون الفساد في الأرض بالشرك والظلم والمعاصي، وليس فيها من حق يبيحها، أولئك لهم عذاب أليم في الدنيا بعقوبتهم الصارمة، ويوم القيامة إن لم يتوبوا. ولمن صبر فلم ينتصر لنفسه من أخيه المسلم، وغفر له زلّته، إن ذلك من معزومات الأمور المطلوبة شرعاً. ومن يضلّه الله حسب سنته فليس له من أحد يهديه بعد الله. وترى المشركين لما رأوا عذاب النار يقولون متمنّين الرجوع إلى الدنيا ليؤمنوا: هل إلى مردّ من سبيل؟ وتراهم يُعرضون على النار خاضعين من الذل، يسترقون النظر لا يملؤون أعينهم منها لشدة خوفهم. وهنا يقول الذين آمنوا: إن الخاسرين حقاً الذين خسروا أنفسهم وأهليهم يوم القيامة بخلودهم في النار وحرمانهم من الحور العين في الجنة، ويُعلن معلن: ألا إن الظالمين لأنفسهم بالشرك والمعاصي في عذاب مقيم لا يزول. وما كان لهم من أولياء ينصرونهم بتخليصهم من العذاب من دون الله، ومن يضلل الله فما له طريق إلى الهداية في الدنيا ولا إلى الجنة يوم القيامة.", "h": ["لا سبيل إلى معاقبة من انتصر لنفسه بعد ظلمه.", "وجوب معاقبة الظالم والضرب على يديه.", "فضيلة الصبر والتجاوز عن المسلم إذا أساء بقول أو عمل.", "لا أعظم خسراناً ممن يخلد في النار ويُحرم الجنة وما فيها من نعيم مقيم."], "k": "«ولمن صبر وغفر إن ذلك لمن عزم الأمور»… الانتصار مباح والعفو عزيمة؛ فبأيهما أرتقي اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (358, 42, 47, 53, 'سورة الشورى ٤٧ – ٥٣', 'الشورى: وكذلك أوحينا إليك روحاً من أمرنا', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 358) = $j$[{"lbl": "الآيات ٤٧ – ٥٠", "q": "ٱسۡتَجِيبُواْ لِرَبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۚ مَا لَكُم مِّن مَّلۡجَإٖ يَوۡمَئِذٖ وَمَا لَكُم مِّن نَّكِيرٖ ﴿٤٧﴾ فَإِنۡ أَعۡرَضُواْ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظًاۖ إِنۡ عَلَيۡكَ إِلَّا ٱلۡبَلَٰغُۗ وَإِنَّآ إِذَآ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةٗ فَرِحَ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَإِنَّ ٱلۡإِنسَٰنَ كَفُورٞ ﴿٤٨﴾ لِّلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَخۡلُقُ مَا يَشَآءُۚ يَهَبُ لِمَن يَشَآءُ إِنَٰثٗا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ ﴿٤٩﴾ أَوۡ يُزَوِّجُهُمۡ ذُكۡرَانٗا وَإِنَٰثٗاۖ وَيَجۡعَلُ مَن يَشَآءُ عَقِيمًاۚ إِنَّهُۥ عَلِيمٞ قَدِيرٞ ﴿٥٠﴾", "w": [["استجيبوا لربكم", "أجيبوه لما دعاكم إليه من التوحيد والعبادة."], ["من قبل أن يأتي يوم", "يوم القيامة."], ["لا مردّ له من الله", "إذا أتى لا يُردّ بحال."], ["ما لكم من ملجأ يومئذ", "تلجؤون إليه وتتحصّنون فيه."], ["وما لكم من نكير", "ليس لكم ما تنكرون به ذنوبكم لأنها في كتاب لا يغادر صغيرة ولا كبيرة إلا أحصاها."], ["فإن أعرضوا", "لم يجيبوا ربهم لما دعاهم إليه."], ["إن عليك إلا البلاغ", "وقد بلّغت، فلا مسؤولية تخشاها بعد البلاغ."], ["إذا أذقنا الإنسان منا رحمة", "نعمة كالغنى والصحة والعافية."], ["وإن تصبهم سيئة", "بلاء كالمرض والفقر."], ["بما قدّمت أيديهم", "من الذنوب والخطايا."], ["فإن الإنسان كفور", "للنعمة والمنعم، والإنسان هنا غير المؤمن التقي."], ["يهب لمن يشاء إناثاً", "يرزق من يشاء من الناس بنات."], ["ويهب لمن يشاء الذكور", "ويعطي من يشاء الأولاد الذكور."], ["أو يزوّجهم ذكراناً وإناثاً", "يجعلهم ذكوراً وإناثاً."], ["ويجعل من يشاء عقيماً", "لا يلد ولا يولد له."]], "m": "بعد ذلك العرض الهائل لأحوال الظالمين في عرصات القيامة طلب الرب تعالى من عباده أن يجيبوه إنقاذاً لأنفسهم من النار: استجيبوا لربكم لما دعاكم إليه من التوحيد والطاعات قبل فوات الفرصة، قبل الموت وقبل يوم القيامة الذي إذا جاء لا يقدر على ردّه إلا الله، والله أخبر أنه لا يردّه، فبادروا بالتوبة قبل مجيئه حيث لا ملجأ تلجؤون إليه، ولا نكير تنكرون به ذنوبكم، إذ جُمعت في كتاب لم يترك صغيرة ولا كبيرة إلا أحصاها. فإن أعرضوا فما أرسلناك عليهم حفيظاً تحصي أعمالهم وتجازيهم، إن عليك إلا البلاغ وقد بلّغت وبرئت ذمتك فلا تحزن على إعراضهم. وإنا إذا أذقنا الإنسان منا نعمة كسعة رزق وصحة بدن وكثرة مال وولد فرح بها فرح البطر والأشر، وهذا الإنسان هو الكافر أو الجاهل الضعيف الإيمان، وإن تصبهم سيئة من ضيق عيش ومرض بما قدّمت أيديهم من الذنوب فإن الإنسان كفور، سرعان ما ينسى النعمة والمنعم ويقع في اليأس؛ هذا قبل أن يؤمن ويُسلم ويُحسن، فإذا آمن وأسلم وأحسن تغيّر طبعه، وأصبح يشكر عند النعمة ويصبر عند النقمة. لله ملك السماوات والأرض يخلق ما يشاء، يتصرّف كيف يشاء: يهب لمن يشاء إناثاً، ويهب لمن يشاء الذكور، أو يجمع له ذكوراً وإناثاً، ويجعل من يشاء عقيماً، إنه عليم قدير، فالواجب أن يُسلّم العبد لربه فيما وهبه، إذ الله يعطي لحكمة ويمنع لحكمة، ومن السفه الاعتراض على حكمه.", "h": ["وجوب الاستجابة لله تعالى في كل ما دعا العبد إليه.", "على الدعاة إلى الله تعالى إبلاغ مطلوب الله تعالى من عباده، ولا يضرّهم بعد ذلك شيء.", "بيان طبع الإنسان وحاله قبل أن يُهذَّب بالإيمان واليقين والطاعات.", "لله مطلق التصرف في الملكوت كله، فلا يصح الاعتراض عليه في شيء، فهو يهب ويمنع لحِكم عالية لا تدركها عقول العباد.", "وجود عقم في الرجال وعقم في النساء، ولا بأس بالعلاج الجائز المشروع عند الشعور بالعقم أو العقر."], "k": "«يهب لمن يشاء… ويجعل من يشاء عقيماً»… ما الذي مُنعته وأحتاج أن أرضى فيه بحكمة ربي؟"}, {"lbl": "الآيات ٥١ – ٥٣", "q": "۞وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحۡيًا أَوۡ مِن وَرَآيِٕ حِجَابٍ أَوۡ يُرۡسِلَ رَسُولٗا فَيُوحِيَ بِإِذۡنِهِۦ مَا يَشَآءُۚ إِنَّهُۥ عَلِيٌّ حَكِيمٞ ﴿٥١﴾ وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ رُوحٗا مِّنۡ أَمۡرِنَاۚ مَا كُنتَ تَدۡرِي مَا ٱلۡكِتَٰبُ وَلَا ٱلۡإِيمَٰنُ وَلَٰكِن جَعَلۡنَٰهُ نُورٗا نَّهۡدِي بِهِۦ مَن نَّشَآءُ مِنۡ عِبَادِنَاۚ وَإِنَّكَ لَتَهۡدِيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٥٢﴾ صِرَٰطِ ٱللَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلۡأُمُورُ ﴿٥٣﴾", "w": [["إلا وحياً أو من وراء حجاب", "إعلاماً خفياً سريعاً في يقظة أو منام، أو يكلّمه من وراء حجاب فيسمع الكلام ولا يرى الذات."], ["أو يرسل رسولاً", "أو يرسل ملكاً في صورة إنسان فيكلّمه مبلّغاً عن الله."], ["إنه عليّ حكيم", "ذو علو على سائر خلقه، حكيم في تدبير خلقه."], ["وكذلك أوحينا إليك", "كما كنا نوحي إلى سائر رسلنا أوحينا إليك يا محمد هذا القرآن."], ["روحاً من أمرنا", "وحياً ورحمة من أمرنا الذي نوحيه إليك."], ["ما كنت تدري ما الكتاب ولا الإيمان", "لم تكن قبلُ تدري أي شيء هو الكتاب، ولا الإيمان الذي هو قول وعمل واعتقاد."], ["ولكن جعلناه نوراً نهدي به من نشاء", "جعلنا القرآن نوراً نهدي به من نشاء من عبادنا إلى صراطنا."], ["وإنك لتهدي إلى صراط مستقيم", "الإسلام."], ["ألا إلى الله تصير الأمور", "ترجع أمور جميع العباد يوم القيامة إلى الله."]], "m": "يخبر تعالى أنه ليس من شأن البشر كائناً من كان أن يكلّمه الله إلا بإحدى ثلاث طرق: وحياً بأن يُعلمه بطريق سريع إلهاماً أو مناماً فيفهم ما ألقاه في روعه جازماً أنه كلام الله، أو أن يكلّمه فيسمعه كلامه بدون أن يرى ذاته كما كلّم موسى ﵇ غير مرة، أو أن يرسل إليه رسولاً كجبريل ﵇ فيبلّغه كلام ربه، إنه علي على خلقه حكيم في تدبيره. وكما كنا نوحي إلى سائر رسلنا أوحينا إليك يا محمد روحاً من أمرنا، وهو القرآن، سُمّي روحاً لأن القلوب تحيا به كما تحيا الأجسام بالأرواح، الشامل للأمر والنهي والوعد والوعيد. ما كنت تدري قبله ما الكتاب ولا الإيمان الذي هو عقيدة وقول وعمل، ولكن جعلنا القرآن نوراً نهدي به من نشاء من عبادنا إلى الإيمان بنا وتوحيدنا وطلب مرضاتنا، وإنك لتهدي إلى صراط مستقيم هو الدين الإسلامي، صراط الله الذي له ما في السماوات وما في الأرض خلقاً وملكاً وعبيداً، ألا إلى الله تصير الأمور، إذ هو المالك الحق والمدبّر لأمر المخلوقات كلها، ولذا وجب تفويض الأمر إليه والرضا بحكمه ثقة فيه وفي كفايته.", "h": ["بيان طرق الوحي، وهي ثلاثة: الأولى الإلقاء في الروع يقظة أو مناماً، والثانية أن يكلّم الله النبي بدون أن يرى ذاته عز وجل كما كلّم موسى في الطور وكلّم محمداً ﷺ في الملكوت الأعلى، والثالثة أن يرسل إليه الملك إما في صورته الملائكية أو في صورة رجل من بني آدم فيوحي إليه ما شاء الله أن يوحيه من أمره.", "القرآن الكريم روح تحيا به القلوب الميتة كما تحيا الأجسام بالأرواح.", "القرآن نور يُستضاء به في الحياة، فتُعرف به طرق السعادة وسبل النجاة."], "k": "«روحاً من أمرنا… نوراً»… هل أعطي قلبي نصيبه من هذه الروح كل يوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 358;
insert into public.tdb_cards(topic, i, body) select 358, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٧ – ٥٠", "q": "ٱسۡتَجِيبُواْ لِرَبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۚ مَا لَكُم مِّن مَّلۡجَإٖ يَوۡمَئِذٖ وَمَا لَكُم مِّن نَّكِيرٖ ﴿٤٧﴾ فَإِنۡ أَعۡرَضُواْ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظًاۖ إِنۡ عَلَيۡكَ إِلَّا ٱلۡبَلَٰغُۗ وَإِنَّآ إِذَآ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةٗ فَرِحَ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَإِنَّ ٱلۡإِنسَٰنَ كَفُورٞ ﴿٤٨﴾ لِّلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَخۡلُقُ مَا يَشَآءُۚ يَهَبُ لِمَن يَشَآءُ إِنَٰثٗا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ ﴿٤٩﴾ أَوۡ يُزَوِّجُهُمۡ ذُكۡرَانٗا وَإِنَٰثٗاۖ وَيَجۡعَلُ مَن يَشَآءُ عَقِيمًاۚ إِنَّهُۥ عَلِيمٞ قَدِيرٞ ﴿٥٠﴾", "w": [["استجيبوا لربكم", "أجيبوه لما دعاكم إليه من التوحيد والعبادة."], ["من قبل أن يأتي يوم", "يوم القيامة."], ["لا مردّ له من الله", "إذا أتى لا يُردّ بحال."], ["ما لكم من ملجأ يومئذ", "تلجؤون إليه وتتحصّنون فيه."], ["وما لكم من نكير", "ليس لكم ما تنكرون به ذنوبكم لأنها في كتاب لا يغادر صغيرة ولا كبيرة إلا أحصاها."], ["فإن أعرضوا", "لم يجيبوا ربهم لما دعاهم إليه."], ["إن عليك إلا البلاغ", "وقد بلّغت، فلا مسؤولية تخشاها بعد البلاغ."], ["إذا أذقنا الإنسان منا رحمة", "نعمة كالغنى والصحة والعافية."], ["وإن تصبهم سيئة", "بلاء كالمرض والفقر."], ["بما قدّمت أيديهم", "من الذنوب والخطايا."], ["فإن الإنسان كفور", "للنعمة والمنعم، والإنسان هنا غير المؤمن التقي."], ["يهب لمن يشاء إناثاً", "يرزق من يشاء من الناس بنات."], ["ويهب لمن يشاء الذكور", "ويعطي من يشاء الأولاد الذكور."], ["أو يزوّجهم ذكراناً وإناثاً", "يجعلهم ذكوراً وإناثاً."], ["ويجعل من يشاء عقيماً", "لا يلد ولا يولد له."]], "m": "بعد ذلك العرض الهائل لأحوال الظالمين في عرصات القيامة طلب الرب تعالى من عباده أن يجيبوه إنقاذاً لأنفسهم من النار: استجيبوا لربكم لما دعاكم إليه من التوحيد والطاعات قبل فوات الفرصة، قبل الموت وقبل يوم القيامة الذي إذا جاء لا يقدر على ردّه إلا الله، والله أخبر أنه لا يردّه، فبادروا بالتوبة قبل مجيئه حيث لا ملجأ تلجؤون إليه، ولا نكير تنكرون به ذنوبكم، إذ جُمعت في كتاب لم يترك صغيرة ولا كبيرة إلا أحصاها. فإن أعرضوا فما أرسلناك عليهم حفيظاً تحصي أعمالهم وتجازيهم، إن عليك إلا البلاغ وقد بلّغت وبرئت ذمتك فلا تحزن على إعراضهم. وإنا إذا أذقنا الإنسان منا نعمة كسعة رزق وصحة بدن وكثرة مال وولد فرح بها فرح البطر والأشر، وهذا الإنسان هو الكافر أو الجاهل الضعيف الإيمان، وإن تصبهم سيئة من ضيق عيش ومرض بما قدّمت أيديهم من الذنوب فإن الإنسان كفور، سرعان ما ينسى النعمة والمنعم ويقع في اليأس؛ هذا قبل أن يؤمن ويُسلم ويُحسن، فإذا آمن وأسلم وأحسن تغيّر طبعه، وأصبح يشكر عند النعمة ويصبر عند النقمة. لله ملك السماوات والأرض يخلق ما يشاء، يتصرّف كيف يشاء: يهب لمن يشاء إناثاً، ويهب لمن يشاء الذكور، أو يجمع له ذكوراً وإناثاً، ويجعل من يشاء عقيماً، إنه عليم قدير، فالواجب أن يُسلّم العبد لربه فيما وهبه، إذ الله يعطي لحكمة ويمنع لحكمة، ومن السفه الاعتراض على حكمه.", "h": ["وجوب الاستجابة لله تعالى في كل ما دعا العبد إليه.", "على الدعاة إلى الله تعالى إبلاغ مطلوب الله تعالى من عباده، ولا يضرّهم بعد ذلك شيء.", "بيان طبع الإنسان وحاله قبل أن يُهذَّب بالإيمان واليقين والطاعات.", "لله مطلق التصرف في الملكوت كله، فلا يصح الاعتراض عليه في شيء، فهو يهب ويمنع لحِكم عالية لا تدركها عقول العباد.", "وجود عقم في الرجال وعقم في النساء، ولا بأس بالعلاج الجائز المشروع عند الشعور بالعقم أو العقر."], "k": "«يهب لمن يشاء… ويجعل من يشاء عقيماً»… ما الذي مُنعته وأحتاج أن أرضى فيه بحكمة ربي؟"}, {"lbl": "الآيات ٥١ – ٥٣", "q": "۞وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحۡيًا أَوۡ مِن وَرَآيِٕ حِجَابٍ أَوۡ يُرۡسِلَ رَسُولٗا فَيُوحِيَ بِإِذۡنِهِۦ مَا يَشَآءُۚ إِنَّهُۥ عَلِيٌّ حَكِيمٞ ﴿٥١﴾ وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ رُوحٗا مِّنۡ أَمۡرِنَاۚ مَا كُنتَ تَدۡرِي مَا ٱلۡكِتَٰبُ وَلَا ٱلۡإِيمَٰنُ وَلَٰكِن جَعَلۡنَٰهُ نُورٗا نَّهۡدِي بِهِۦ مَن نَّشَآءُ مِنۡ عِبَادِنَاۚ وَإِنَّكَ لَتَهۡدِيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٥٢﴾ صِرَٰطِ ٱللَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلۡأُمُورُ ﴿٥٣﴾", "w": [["إلا وحياً أو من وراء حجاب", "إعلاماً خفياً سريعاً في يقظة أو منام، أو يكلّمه من وراء حجاب فيسمع الكلام ولا يرى الذات."], ["أو يرسل رسولاً", "أو يرسل ملكاً في صورة إنسان فيكلّمه مبلّغاً عن الله."], ["إنه عليّ حكيم", "ذو علو على سائر خلقه، حكيم في تدبير خلقه."], ["وكذلك أوحينا إليك", "كما كنا نوحي إلى سائر رسلنا أوحينا إليك يا محمد هذا القرآن."], ["روحاً من أمرنا", "وحياً ورحمة من أمرنا الذي نوحيه إليك."], ["ما كنت تدري ما الكتاب ولا الإيمان", "لم تكن قبلُ تدري أي شيء هو الكتاب، ولا الإيمان الذي هو قول وعمل واعتقاد."], ["ولكن جعلناه نوراً نهدي به من نشاء", "جعلنا القرآن نوراً نهدي به من نشاء من عبادنا إلى صراطنا."], ["وإنك لتهدي إلى صراط مستقيم", "الإسلام."], ["ألا إلى الله تصير الأمور", "ترجع أمور جميع العباد يوم القيامة إلى الله."]], "m": "يخبر تعالى أنه ليس من شأن البشر كائناً من كان أن يكلّمه الله إلا بإحدى ثلاث طرق: وحياً بأن يُعلمه بطريق سريع إلهاماً أو مناماً فيفهم ما ألقاه في روعه جازماً أنه كلام الله، أو أن يكلّمه فيسمعه كلامه بدون أن يرى ذاته كما كلّم موسى ﵇ غير مرة، أو أن يرسل إليه رسولاً كجبريل ﵇ فيبلّغه كلام ربه، إنه علي على خلقه حكيم في تدبيره. وكما كنا نوحي إلى سائر رسلنا أوحينا إليك يا محمد روحاً من أمرنا، وهو القرآن، سُمّي روحاً لأن القلوب تحيا به كما تحيا الأجسام بالأرواح، الشامل للأمر والنهي والوعد والوعيد. ما كنت تدري قبله ما الكتاب ولا الإيمان الذي هو عقيدة وقول وعمل، ولكن جعلنا القرآن نوراً نهدي به من نشاء من عبادنا إلى الإيمان بنا وتوحيدنا وطلب مرضاتنا، وإنك لتهدي إلى صراط مستقيم هو الدين الإسلامي، صراط الله الذي له ما في السماوات وما في الأرض خلقاً وملكاً وعبيداً، ألا إلى الله تصير الأمور، إذ هو المالك الحق والمدبّر لأمر المخلوقات كلها، ولذا وجب تفويض الأمر إليه والرضا بحكمه ثقة فيه وفي كفايته.", "h": ["بيان طرق الوحي، وهي ثلاثة: الأولى الإلقاء في الروع يقظة أو مناماً، والثانية أن يكلّم الله النبي بدون أن يرى ذاته عز وجل كما كلّم موسى في الطور وكلّم محمداً ﷺ في الملكوت الأعلى، والثالثة أن يرسل إليه الملك إما في صورته الملائكية أو في صورة رجل من بني آدم فيوحي إليه ما شاء الله أن يوحيه من أمره.", "القرآن الكريم روح تحيا به القلوب الميتة كما تحيا الأجسام بالأرواح.", "القرآن نور يُستضاء به في الحياة، فتُعرف به طرق السعادة وسبل النجاة."], "k": "«روحاً من أمرنا… نوراً»… هل أعطي قلبي نصيبه من هذه الروح كل يوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (359, 43, 1, 14, 'سورة الزخرف ١ – ١٤', 'الزخرف: سبحان الذي سخّر لنا هذا', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 359) = $j$[{"lbl": "الآيات ١ – ٨", "q": "حمٓ ﴿١﴾ وَٱلۡكِتَٰبِ ٱلۡمُبِينِ ﴿٢﴾ إِنَّا جَعَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا لَّعَلَّكُمۡ تَعۡقِلُونَ ﴿٣﴾ وَإِنَّهُۥ فِيٓ أُمِّ ٱلۡكِتَٰبِ لَدَيۡنَا لَعَلِيٌّ حَكِيمٌ ﴿٤﴾ أَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ صَفۡحًا أَن كُنتُمۡ قَوۡمٗا مُّسۡرِفِينَ ﴿٥﴾ وَكَمۡ أَرۡسَلۡنَا مِن نَّبِيّٖ فِي ٱلۡأَوَّلِينَ ﴿٦﴾ وَمَا يَأۡتِيهِم مِّن نَّبِيٍّ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٧﴾ فَأَهۡلَكۡنَآ أَشَدَّ مِنۡهُم بَطۡشٗا وَمَضَىٰ مَثَلُ ٱلۡأَوَّلِينَ ﴿٨﴾", "w": [["حم", "أحد الحروف المقطعة، يُكتب «حم» ويُقرأ «حا ميم»."], ["والكتاب المبين", "والقرآن الموضّح لطريق الهدى وسبيل السلام."], ["إنا جعلناه قرآناً عربياً", "جعلناه قرآناً بلسان العرب يُقرأ بلسانهم ويُفهم به."], ["لعلكم تعقلون", "رجاء أن تعقلوا أيها العرب ما تؤمرون به وما تُنهون عنه."], ["وإنه في أم الكتاب لدينا", "في اللوح المحفوظ كتاب المقادير عندنا."], ["لعليّ حكيم", "ذو علو وشأن على الكتب قبله لا يوصل إلى مستواه، ذو حكمة بالغة."], ["أفنضرب عنكم الذكر صفحاً", "أنمهلكم فلا ننزل القرآن بأمركم ونهيكم ووعدكم ووعيدكم؟"], ["أن كنتم قوماً مسرفين", "لأن كنتم متجاوزين الحد في الشرك والكفر؟ كلا لا نفعل."], ["وكم أرسلنا من نبي في الأولين", "كثيراً من الأنبياء أرسلناهم في الأمم الماضية."], ["فأهلكنا أشد منهم بطشاً", "أنزلنا عذابنا بمن هم أشد قوة وبطشاً من قومك فأهلكناهم."], ["ومضى مثل الأولين", "مضى في الآيات القرآنية صفة هلاك الأولين."]], "m": "حم: الله أعلم بمراده به. والكتاب المبين، القرآن الموضّح لكل ما ينجي من عذاب الله ويكسب حبه ورضاه، قسم أقسم الله به، والمقسم عليه: إنا جعلناه قرآناً عربياً بلسان العرب ولغتهم، لكي تعقلوا معانيه وتفهموا مراد الله فيما يدعوكم إليه فيسهل عليكم العمل به فتكملوا وتسعدوا. وإنه في اللوح المحفوظ لدينا لذو علو وشأن على سائر الكتب قبله، ذو حكمة بالغة. أنمهلكم فلا ننزل القرآن حتى لا تؤمروا ولا تُنهوا من أجل أنكم قوم مسرفون في الشرك والتكذيب؟ كلا لا نفعل. وكثيراً من الأنبياء أرسلنا في الأمم السابقة، وما يأتيهم من نبي إلا كانوا به يستهزئون وبما جاءهم به من التوحيد، فاصبر على قومك فإنهم سالكون سبيل من سبقهم. فأهلكنا من هم أشد بطشاً منهم لما كذّبوا رسلنا، فكيف بهؤلاء الأضعف؟ فأحرى بهم ألا يمتنعوا من عذابنا متى أردنا إنزاله بهم. ومضى في القرآن صفة هلاك الأولين كقوم عاد وثمود وأصحاب مدين والمؤتفكات، ألم يكن لقومك في ذلك عبرة؟", "h": ["مشروعية الإقسام بالله تعالى.", "بيان شرف القرآن الكريم وعلوّ مكانته على سائر الكتب السابقة.", "كون الناس مسرفين في الشرك والفساد لا يمنع وعظهم ونصحهم وإرشادهم.", "بيان سنة بشرية، وهي أنهم ما يأتيهم من رسول إلا استهزؤوا به.", "في إهلاك الأقوى دليل على أن إهلاك من هو دونه أحرى وأولى، لا سيما مع شدة كفره."], "k": "«أفنضرب عنكم الذكر صفحاً أن كنتم قوماً مسرفين»… لم يقطع الله تذكيره عني رغم إسرافي؛ فهل أنتفع به؟"}, {"lbl": "الآيات ٩ – ١٤", "q": "وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ خَلَقَهُنَّ ٱلۡعَزِيزُ ٱلۡعَلِيمُ ﴿٩﴾ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَجَعَلَ لَكُمۡ فِيهَا سُبُلٗا لَّعَلَّكُمۡ تَهۡتَدُونَ ﴿١٠﴾ وَٱلَّذِي نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَنشَرۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ تُخۡرَجُونَ ﴿١١﴾ وَٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلۡفُلۡكِ وَٱلۡأَنۡعَٰمِ مَا تَرۡكَبُونَ ﴿١٢﴾ لِتَسۡتَوُۥاْ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذۡكُرُواْ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَيۡتُمۡ عَلَيۡهِ وَتَقُولُواْ سُبۡحَٰنَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ ﴿١٣﴾ وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ ﴿١٤﴾", "w": [["ولئن سألتهم", "ولئن سألت هؤلاء المشركين من قومك يا رسولنا."], ["من خلق السماوات والأرض", "من بدأ خلقهنّ وأوجدهن؟ ليقولُنّ: خلقهن الله ذو العزة والعلم."], ["الذي جعل لكم الأرض مهداً", "فراشاً كالمهد للصبي."], ["وجعل لكم فيها سبلاً", "طرقاً."], ["لعلكم تهتدون", "إلى مقاصدكم في أسفاركم."], ["ماءً بقدر", "على قدر الحاجة، ولم يجعله طوفاناً مغرقاً."], ["فأنشرنا به بلدة ميتاً", "أحيينا به بلدة لا نبات فيها ولا زرع."], ["كذلك تُخرجون", "مثل هذا الإحياء للأرض الميتة تُحيَون أنتم وتخرجون من قبوركم."], ["والذي خلق الأزواج كلها", "خلق كل شيء، إذ الأشياء كلها زوج ولم يُعرف فرد إلا الله."], ["من الفلك والأنعام", "السفن والإبل."], ["لتستووا على ظهوره", "تستقرّوا على ظهور ما تركبون."], ["وما كنا له مقرنين", "مطيقين ولا ضابطين."], ["وإنا إلى ربنا لمنقلبون", "لصائرون إليه راجعون."]], "m": "ما زال السياق في دعوة المشركين إلى التوحيد: ولئن سألتهم من أنشأ السماوات والأرض بعد عدم لبادروك بالجواب: الله، ثم هم مع اعترافهم بربوبيته يشركون في عبادته أصناماً، وقالوا هنا: العزيز العليم، أي ذو العزة التي لا تُرام والعلم الذي لا يُحاط به. ولما وصفوه بهاتين الصفتين ناسب ذكر صفات أخرى تعريفاً لهم به، وهذا من كلام الله لا من كلامهم: الذي جعل لكم الأرض فراشاً كمهد الطفل، وجعل لكم فيها طرقاً لعلكم تهتدون إلى مقاصدكم، والذي نزّل من السماء المطر بكميات موزونة على قدر الحاجة، فلم يكن قليلاً لا ينفع ولا طوفاناً مهلكاً، فأحيينا به أرضاً يابسة، كذلك يحييكم ويخرجكم من قبوركم أحياء. والذي خلق الأزواج كلها: الذكر والأنثى، والخير والشر، والصحة والمرض، إذ لا فرد إلا هو، وفي الحديث الصحيح: «إن الله وتر يحب الوتر». وجعل لكم من السفن ومن الأنعام كالإبل ومن البهائم كالخيل والبغال والحمير ما تركبون، لتستقرّوا على ظهوره، ثم تذكروا نعمة ربكم بقلوبكم إذا استويتم عليه، وتقولوا بألسنتكم: سبحان الذي سخّر لنا هذا وأقدرنا على التحكم فيه، وما كنا له مطيقين ولا ضابطين لعجزنا وقوته، وإنا إلى ربنا لصائرون بعد موتنا.", "h": ["تقرير التوحيد بذكر صفات الربوبية المقتضية للألوهية.", "تقرير عقيدة البعث والجزاء.", "معجزة القرآن في الإخبار بالزوجية، وقد قرّر العلم الحديث نظام الزوجية حتى في الذرة، فهي زوج: موجب وسالب.", "مشروعية التسمية والذكر عند ركوب ما يُركب: فإن كان سفينة أو سيارة قال العبد: «بسم الله مجراها ومرساها إن ربي لغفور رحيم»، وإن كان حيواناً قال عند الشروع: باسم الله، وإذا استوى قاعداً: «سبحان الذي سخّر لنا هذا وما كنا له مقرنين وإنا إلى ربنا لمنقلبون»."], "k": "«سبحان الذي سخّر لنا هذا»… أركب كل يوم؛ فهل أتذكّر النعمة أم أعتاد عليها؟"}]$j$::jsonb then 0 else 1 end;
