insert into public.tdb_cards(topic, i, body) select 359, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٨", "q": "حمٓ ﴿١﴾ وَٱلۡكِتَٰبِ ٱلۡمُبِينِ ﴿٢﴾ إِنَّا جَعَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا لَّعَلَّكُمۡ تَعۡقِلُونَ ﴿٣﴾ وَإِنَّهُۥ فِيٓ أُمِّ ٱلۡكِتَٰبِ لَدَيۡنَا لَعَلِيٌّ حَكِيمٌ ﴿٤﴾ أَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ صَفۡحًا أَن كُنتُمۡ قَوۡمٗا مُّسۡرِفِينَ ﴿٥﴾ وَكَمۡ أَرۡسَلۡنَا مِن نَّبِيّٖ فِي ٱلۡأَوَّلِينَ ﴿٦﴾ وَمَا يَأۡتِيهِم مِّن نَّبِيٍّ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٧﴾ فَأَهۡلَكۡنَآ أَشَدَّ مِنۡهُم بَطۡشٗا وَمَضَىٰ مَثَلُ ٱلۡأَوَّلِينَ ﴿٨﴾", "w": [["حم", "أحد الحروف المقطعة، يُكتب «حم» ويُقرأ «حا ميم»."], ["والكتاب المبين", "والقرآن الموضّح لطريق الهدى وسبيل السلام."], ["إنا جعلناه قرآناً عربياً", "جعلناه قرآناً بلسان العرب يُقرأ بلسانهم ويُفهم به."], ["لعلكم تعقلون", "رجاء أن تعقلوا أيها العرب ما تؤمرون به وما تُنهون عنه."], ["وإنه في أم الكتاب لدينا", "في اللوح المحفوظ كتاب المقادير عندنا."], ["لعليّ حكيم", "ذو علو وشأن على الكتب قبله لا يوصل إلى مستواه، ذو حكمة بالغة."], ["أفنضرب عنكم الذكر صفحاً", "أنمهلكم فلا ننزل القرآن بأمركم ونهيكم ووعدكم ووعيدكم؟"], ["أن كنتم قوماً مسرفين", "لأن كنتم متجاوزين الحد في الشرك والكفر؟ كلا لا نفعل."], ["وكم أرسلنا من نبي في الأولين", "كثيراً من الأنبياء أرسلناهم في الأمم الماضية."], ["فأهلكنا أشد منهم بطشاً", "أنزلنا عذابنا بمن هم أشد قوة وبطشاً من قومك فأهلكناهم."], ["ومضى مثل الأولين", "مضى في الآيات القرآنية صفة هلاك الأولين."]], "m": "حم: الله أعلم بمراده به. والكتاب المبين، القرآن الموضّح لكل ما ينجي من عذاب الله ويكسب حبه ورضاه، قسم أقسم الله به، والمقسم عليه: إنا جعلناه قرآناً عربياً بلسان العرب ولغتهم، لكي تعقلوا معانيه وتفهموا مراد الله فيما يدعوكم إليه فيسهل عليكم العمل به فتكملوا وتسعدوا. وإنه في اللوح المحفوظ لدينا لذو علو وشأن على سائر الكتب قبله، ذو حكمة بالغة. أنمهلكم فلا ننزل القرآن حتى لا تؤمروا ولا تُنهوا من أجل أنكم قوم مسرفون في الشرك والتكذيب؟ كلا لا نفعل. وكثيراً من الأنبياء أرسلنا في الأمم السابقة، وما يأتيهم من نبي إلا كانوا به يستهزئون وبما جاءهم به من التوحيد، فاصبر على قومك فإنهم سالكون سبيل من سبقهم. فأهلكنا من هم أشد بطشاً منهم لما كذّبوا رسلنا، فكيف بهؤلاء الأضعف؟ فأحرى بهم ألا يمتنعوا من عذابنا متى أردنا إنزاله بهم. ومضى في القرآن صفة هلاك الأولين كقوم عاد وثمود وأصحاب مدين والمؤتفكات، ألم يكن لقومك في ذلك عبرة؟", "h": ["مشروعية الإقسام بالله تعالى.", "بيان شرف القرآن الكريم وعلوّ مكانته على سائر الكتب السابقة.", "كون الناس مسرفين في الشرك والفساد لا يمنع وعظهم ونصحهم وإرشادهم.", "بيان سنة بشرية، وهي أنهم ما يأتيهم من رسول إلا استهزؤوا به.", "في إهلاك الأقوى دليل على أن إهلاك من هو دونه أحرى وأولى، لا سيما مع شدة كفره."], "k": "«أفنضرب عنكم الذكر صفحاً أن كنتم قوماً مسرفين»… لم يقطع الله تذكيره عني رغم إسرافي؛ فهل أنتفع به؟"}, {"lbl": "الآيات ٩ – ١٤", "q": "وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ خَلَقَهُنَّ ٱلۡعَزِيزُ ٱلۡعَلِيمُ ﴿٩﴾ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَجَعَلَ لَكُمۡ فِيهَا سُبُلٗا لَّعَلَّكُمۡ تَهۡتَدُونَ ﴿١٠﴾ وَٱلَّذِي نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَنشَرۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ تُخۡرَجُونَ ﴿١١﴾ وَٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلۡفُلۡكِ وَٱلۡأَنۡعَٰمِ مَا تَرۡكَبُونَ ﴿١٢﴾ لِتَسۡتَوُۥاْ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذۡكُرُواْ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَيۡتُمۡ عَلَيۡهِ وَتَقُولُواْ سُبۡحَٰنَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ ﴿١٣﴾ وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ ﴿١٤﴾", "w": [["ولئن سألتهم", "ولئن سألت هؤلاء المشركين من قومك يا رسولنا."], ["من خلق السماوات والأرض", "من بدأ خلقهنّ وأوجدهن؟ ليقولُنّ: خلقهن الله ذو العزة والعلم."], ["الذي جعل لكم الأرض مهداً", "فراشاً كالمهد للصبي."], ["وجعل لكم فيها سبلاً", "طرقاً."], ["لعلكم تهتدون", "إلى مقاصدكم في أسفاركم."], ["ماءً بقدر", "على قدر الحاجة، ولم يجعله طوفاناً مغرقاً."], ["فأنشرنا به بلدة ميتاً", "أحيينا به بلدة لا نبات فيها ولا زرع."], ["كذلك تُخرجون", "مثل هذا الإحياء للأرض الميتة تُحيَون أنتم وتخرجون من قبوركم."], ["والذي خلق الأزواج كلها", "خلق كل شيء، إذ الأشياء كلها زوج ولم يُعرف فرد إلا الله."], ["من الفلك والأنعام", "السفن والإبل."], ["لتستووا على ظهوره", "تستقرّوا على ظهور ما تركبون."], ["وما كنا له مقرنين", "مطيقين ولا ضابطين."], ["وإنا إلى ربنا لمنقلبون", "لصائرون إليه راجعون."]], "m": "ما زال السياق في دعوة المشركين إلى التوحيد: ولئن سألتهم من أنشأ السماوات والأرض بعد عدم لبادروك بالجواب: الله، ثم هم مع اعترافهم بربوبيته يشركون في عبادته أصناماً، وقالوا هنا: العزيز العليم، أي ذو العزة التي لا تُرام والعلم الذي لا يُحاط به. ولما وصفوه بهاتين الصفتين ناسب ذكر صفات أخرى تعريفاً لهم به، وهذا من كلام الله لا من كلامهم: الذي جعل لكم الأرض فراشاً كمهد الطفل، وجعل لكم فيها طرقاً لعلكم تهتدون إلى مقاصدكم، والذي نزّل من السماء المطر بكميات موزونة على قدر الحاجة، فلم يكن قليلاً لا ينفع ولا طوفاناً مهلكاً، فأحيينا به أرضاً يابسة، كذلك يحييكم ويخرجكم من قبوركم أحياء. والذي خلق الأزواج كلها: الذكر والأنثى، والخير والشر، والصحة والمرض، إذ لا فرد إلا هو، وفي الحديث الصحيح: «إن الله وتر يحب الوتر». وجعل لكم من السفن ومن الأنعام كالإبل ومن البهائم كالخيل والبغال والحمير ما تركبون، لتستقرّوا على ظهوره، ثم تذكروا نعمة ربكم بقلوبكم إذا استويتم عليه، وتقولوا بألسنتكم: سبحان الذي سخّر لنا هذا وأقدرنا على التحكم فيه، وما كنا له مطيقين ولا ضابطين لعجزنا وقوته، وإنا إلى ربنا لصائرون بعد موتنا.", "h": ["تقرير التوحيد بذكر صفات الربوبية المقتضية للألوهية.", "تقرير عقيدة البعث والجزاء.", "معجزة القرآن في الإخبار بالزوجية، وقد قرّر العلم الحديث نظام الزوجية حتى في الذرة، فهي زوج: موجب وسالب.", "مشروعية التسمية والذكر عند ركوب ما يُركب: فإن كان سفينة أو سيارة قال العبد: «بسم الله مجراها ومرساها إن ربي لغفور رحيم»، وإن كان حيواناً قال عند الشروع: باسم الله، وإذا استوى قاعداً: «سبحان الذي سخّر لنا هذا وما كنا له مقرنين وإنا إلى ربنا لمنقلبون»."], "k": "«سبحان الذي سخّر لنا هذا»… أركب كل يوم؛ فهل أتذكّر النعمة أم أعتاد عليها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (360, 43, 15, 32, 'سورة الزخرف ١٥ – ٣٢', 'الزخرف: أهم يقسمون رحمة ربك', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 360) = $j$[{"lbl": "الآيات ١٥ – ٢٣", "q": "وَجَعَلُواْ لَهُۥ مِنۡ عِبَادِهِۦ جُزۡءًاۚ إِنَّ ٱلۡإِنسَٰنَ لَكَفُورٞ مُّبِينٌ ﴿١٥﴾ أَمِ ٱتَّخَذَ مِمَّا يَخۡلُقُ بَنَاتٖ وَأَصۡفَىٰكُم بِٱلۡبَنِينَ ﴿١٦﴾ وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحۡمَٰنِ مَثَلٗا ظَلَّ وَجۡهُهُۥ مُسۡوَدّٗا وَهُوَ كَظِيمٌ ﴿١٧﴾ أَوَمَن يُنَشَّؤُاْ فِي ٱلۡحِلۡيَةِ وَهُوَ فِي ٱلۡخِصَامِ غَيۡرُ مُبِينٖ ﴿١٨﴾ وَجَعَلُواْ ٱلۡمَلَـٰٓئِكَةَ ٱلَّذِينَ هُمۡ عِبَٰدُ ٱلرَّحۡمَٰنِ إِنَٰثًاۚ أَشَهِدُواْ خَلۡقَهُمۡۚ سَتُكۡتَبُ شَهَٰدَتُهُمۡ وَيُسۡـَٔلُونَ ﴿١٩﴾ وَقَالُواْ لَوۡ شَآءَ ٱلرَّحۡمَٰنُ مَا عَبَدۡنَٰهُمۗ مَّا لَهُم بِذَٰلِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا يَخۡرُصُونَ ﴿٢٠﴾ أَمۡ ءَاتَيۡنَٰهُمۡ كِتَٰبٗا مِّن قَبۡلِهِۦ فَهُم بِهِۦ مُسۡتَمۡسِكُونَ ﴿٢١﴾ بَلۡ قَالُوٓاْ إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهۡتَدُونَ ﴿٢٢﴾ وَكَذَٰلِكَ مَآ أَرۡسَلۡنَا مِن قَبۡلِكَ فِي قَرۡيَةٖ مِّن نَّذِيرٍ إِلَّا قَالَ مُتۡرَفُوهَآ إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقۡتَدُونَ ﴿٢٣﴾", "w": [["وجعلوا له من عباده جزءاً", "جعل المشركون المقرّون بأن الله خالق السماوات والأرض له من عباده جزءاً إذ قالوا: الملائكة بنات الله."], ["إن الإنسان لكفور مبين", "لكثير الكفر بيّنه."], ["وأصفاكم بالبنين", "خصّكم بالبنين وأخلصهم لكم."], ["بما ضرب للرحمن مثلاً", "بما جعل للرحمن شبهاً وهو الولد."], ["ظلّ وجهه مسودّاً وهو كظيم", "أقام طوال نهاره مسودّ الوجه من الحزن وهو ممتلئ غيظاً."], ["أوَمن يُنشّأ في الحلية", "أيجترئون على الله ويجعلون له جزءاً هو البنت التي تُربّى في الزينة؟"], ["وهو في الخصام غير مبين", "غير مُظهر للحجة لضعفه بالأنوثة."], ["عباد الرحمن إناثاً", "لأنهم قالوا: بنات الله."], ["أشهدوا خلقهم", "أحضروا خلقهم عندما كان الرحمن يخلقهم؟"], ["ستُكتب شهادتهم", "سيُكتب قولهم إن الملائكة إناث."], ["ويُسألون", "يوم القيامة عن شهادتهم الباطلة ويُعاقبون عليها."], ["ما لهم بذلك من علم", "دعواهم أن الله راضٍ عنهم بعبادة الملائكة لا دليل لهم عليها."], ["إن هم إلا يخرصون", "ما هم إلا يكذبون، يتوارثون الجهل عن بعضهم."], ["أم آتيناهم كتاباً من قبله", "أم أنزلنا عليهم كتاباً قبل القرآن؟"], ["فهم به مستمسكون", "متمسّكون بما فيه؟ لم يقع ذلك أبداً."], ["إنا وجدنا آباءنا على أمة", "لا حجة لهم إلا التقليد الأعمى لآبائهم، والأمة: الملة والدين."], ["وإنا على آثارهم مهتدون", "على طريقتهم ماشون، وهي عبادة غير الله."], ["إلا قال مترفوها", "متنعّموها."], ["وإنا على آثارهم مقتدون", "على طريقهم متبعون لهم فيها."]], "m": "ما زال السياق في دعوة المشركين إلى التوحيد منكراً عليهم باطلهم: وجعلوا لله من خلقه نصيباً حيث قالوا: الملائكة بنات الله، وهذا من أكذب الكذب وأكفر الكفر، إذ كيف عرفوا أنهم إناث وأنهم بنات الله وأنهم يستحقون العبادة فعبدوهم؟ إن الإنسان لكثير الكفر بيّنه. أتقولون اتخذ الله مما يخلق بنات وخصّكم بالبنين، ورضي لنفسه بالإناث اللاتي تبغضون؟ عجباً لهذا الفهم السقيم! وإذا بُشّر أحدهم ببنت ظل وجهه طوال النهار مسودّاً من الكآبة وهو ممتلئ غماً. أيجترئون ويجعلون لله من يُربّى في الزينة لنقصانه، وهو في الخصام لا يُظهر الحجة لضعفه بالخلقة؟ وجعلوا الملائكة الذين هم عباد الرحمن إناثاً وعبدوهم طلباً لشفاعتهم، أحضروا عندما كان الله يخلقهم؟ لا، ومن أين لهم ذلك؟ ستُكتب شهادتهم هذه ويُسألون عنها ويُعاقبون، لأنها الكذب على الله. وقالوا لمن أنكر عليهم: لو شاء الرحمن ما عبدناهم، ما لهم بذلك من علم برضا الله، إن هم إلا يكذبون، إذ العلم يأتي من طريق الكتاب أو النبي، ولا كتاب عندهم ولا نبي. أم آتيناهم كتاباً قبل القرآن فهم به مستمسكون؟ لا، فلا حجة لهم إلا التقليد الأعمى للآباء الجهال: إنا وجدنا آباءنا على ملة وإنا على آثارهم مهتدون. وكذلك ما أرسلنا من قبلك في قرية من رسول إلا قال متنعّموها: إنا وجدنا آباءنا على ملة وإنا على آثارهم مقتدون؛ فهذه سنة الأمم قبل أمتك، فلا تحزن عليهم.", "h": ["تقرير صفة من صفات الإنسان قبل شفائه بالإيمان والعبادة، وهي الكفر الواضح المبين.", "وجوب إنكار المنكر ومحاولة تغييره في حدود ما يسمح به الشرع وتتّسع له طاقة الإنسان.", "بيان حال المشركين العرب في الجاهلية من كراهيتهم البنات خوف العار.", "بيان ضعف المرأة ونقصانها، ولذا تكمُل بالزينة، وأن النقص فيها فطري في البدن والعقل.", "بيان أن من قال قولاً وشهد شهادة باطلة سوف يُسأل عنها يوم القيامة ويُعاقب عليها.", "حرمة القول على الله بدون علم، فلا يحل أن يُنسب إلى الله تعالى شيء لم ينسبه هو تعالى لنفسه.", "حرمة التقليد للآباء وأهل البلاد والمشايخ، فلا يُقبل قول إلا بدليل من الشرع."], "k": "«إنا وجدنا آباءنا على أمة»… ما الذي أفعله فقط لأني نشأت عليه، دون أن أعرف دليله؟"}, {"lbl": "الآيات ٢٤ – ٣٢", "q": "۞قَٰلَ أَوَلَوۡ جِئۡتُكُم بِأَهۡدَىٰ مِمَّا وَجَدتُّمۡ عَلَيۡهِ ءَابَآءَكُمۡۖ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ ﴿٢٤﴾ فَٱنتَقَمۡنَا مِنۡهُمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ ﴿٢٥﴾ وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ وَقَوۡمِهِۦٓ إِنَّنِي بَرَآءٞ مِّمَّا تَعۡبُدُونَ ﴿٢٦﴾ إِلَّا ٱلَّذِي فَطَرَنِي فَإِنَّهُۥ سَيَهۡدِينِ ﴿٢٧﴾ وَجَعَلَهَا كَلِمَةَۢ بَاقِيَةٗ فِي عَقِبِهِۦ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٢٨﴾ بَلۡ مَتَّعۡتُ هَـٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ جَآءَهُمُ ٱلۡحَقُّ وَرَسُولٞ مُّبِينٞ ﴿٢٩﴾ وَلَمَّا جَآءَهُمُ ٱلۡحَقُّ قَالُواْ هَٰذَا سِحۡرٞ وَإِنَّا بِهِۦ كَٰفِرُونَ ﴿٣٠﴾ وَقَالُواْ لَوۡلَا نُزِّلَ هَٰذَا ٱلۡقُرۡءَانُ عَلَىٰ رَجُلٖ مِّنَ ٱلۡقَرۡيَتَيۡنِ عَظِيمٍ ﴿٣١﴾ أَهُمۡ يَقۡسِمُونَ رَحۡمَتَ رَبِّكَۚ نَحۡنُ قَسَمۡنَا بَيۡنَهُم مَّعِيشَتَهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَتَّخِذَ بَعۡضُهُم بَعۡضٗا سُخۡرِيّٗاۗ وَرَحۡمَتُ رَبِّكَ خَيۡرٞ مِّمَّا يَجۡمَعُونَ ﴿٣٢﴾", "w": [["أوَلو جئتكم بأهدى مما وجدتم عليه آباءكم", "قال لهم رسولهم: أتتبعون آباءكم ولو جئتكم بخير مما وجدتم عليه آباءكم هداية؟"], ["إنا بما أُرسلتم به كافرون", "جاحدون منكرون غير معترفين به."], ["فانظر كيف كان عاقبة المكذبين", "كانت دماراً وهلاكاً، فلا تكترث بتكذيب قومك يا رسولنا."], ["وإذ قال إبراهيم", "واذكر إذ قال إبراهيم أبو الأنبياء خليل الرحمن."], ["إنني براء مما تعبدون", "بريء مما تعبدون من أصنام لا أعبدها."], ["إلا الذي فطرني فإنه سيهدين", "لكن الذي خلقني أعبده، فإنه سيرشدني إلى ما يكمّلني ويسعدني."], ["وجعلها كلمة باقية في عقبه", "جعل إبراهيم كلمة التوحيد «لا إله إلا الله» باقية في ذريته، إذ وصّاهم بها."], ["لعلهم يرجعون", "رجاء أن يتوبوا ويرجعوا إلى توحيده كلما ذكروها."], ["بل متّعت هؤلاء وآباءهم", "المشركين وآباءهم بالحياة فلم أعاجلهم بالعقوبة."], ["حتى جاءهم الحق ورسول مبين", "جاء القرآن يحمل الدين الحق، ورسول لا شك في رسالته، وهو محمد ﷺ."], ["على رجل من القريتين عظيم", "هلّا نزل على أحد رجلين من مكة أو الطائف: الوليد بن المغيرة أو عروة بن مسعود الثقفي."], ["أهم يقسمون رحمة ربك", "ينكر عليهم هذا التحكم، إذ النبوة من أعظم الرحمات وليس لهم حق في تنبئة أحد."], ["نحن قسمنا بينهم معيشتهم", "إذا كنا نحن نقسم معيشتهم فنغني هذا ونفقر هذا، فكيف بالنبوة وهي أجل من الطعام والشراب؟"], ["ليتخذ بعضهم بعضاً سُخرياً", "جعلنا هذا غنياً وذاك فقيراً ليتخذ الغني الفقير خادماً يسخّره في خدمته بأجرة."], ["ورحمة ربك خير مما يجمعون", "الجنة التي أعدّها الله لك ولأتباعك خير من المال الذي يجمعه المشركون."]], "m": "لما ذكر قول المشركين لرسلهم: إنا وجدنا آباءنا على ملة، أخبر عن قول الرسول لأمته المكذبة المقلّدة: أتتبعون آباءكم ولا تتبعونني ولو جئتكم بأهدى إلى الخير مما وجدتم عليه آباءكم؟ إذ العاقل يتبع الهدى جاء به من جاء. فقالت كل أمة لرسولها: إنا بما أُرسلتم به من التوحيد والبعث والشرع كافرون، فانتقمنا منهم فأهلكناهم، فانظر كيف كان عاقبتهم، وليذكر هذا قومك. واذكر لقومك قول إبراهيم الذي ينتسبون إليه باطلاً لأبيه وقومه: إنني بريء من آلهتكم، إلا الذي خلقني فهو أحق بعبادتي مما لم يخلقني ولم يخلق شيئاً، فإنه سيرشدني دائماً. وجعل براءته من الشرك وعبادته الخاصة بالله كلمة باقية في ذريته، إذ وصّاهم بها كما في البقرة: ووصّى بها إبراهيم بنيه، وهي لا إله إلا الله، لعلهم يرجعون إليها كلما غفلوا، فجزى الله إبراهيم عن المؤمنين خيراً. بل لم يتحقق ما ترجّاه إبراهيم كاملاً، إذ أشرك من بنيه من أشرك، ومنهم هؤلاء المعاصرون لك، متّعتهم وآباءهم بالحياة حتى جاءهم الحق، القرآن، يتلوه الرسول المبيّن لكل الشرائع، فقالوا: هذا سحر وإنا به كافرون، وقالوا: هلّا نزل هذا القرآن على رجل شريف ذي مكانة كالوليد بن المغيرة في مكة أو عروة بن مسعود في الطائف؛ وهذه نظرة مادية بحتة، رأوا الشرف بالمال، ولما كان محمد لا مال له رأوه ليس أهلاً للرسالة. فردّ عليهم: أهم يقسمون رحمة ربك فيعطون منها من شاؤوا؟ نحن قسمنا بينهم معيشتهم، فالعاجز حتى عن إطعام نفسه كيف لا يستحي أن يعترض على الله في اختياره من هو أهل لنبوته؟ ورفعنا بعضهم فوق بعض درجات في الرزق ليخدم الفقير الغني، إذ لو كانوا كلهم أغنياء لما خدم أحد أحداً وتعطّلت الحياة. ورحمة ربك، الجنة، خير مما يجمعون من المال الذي فضّلوا أهله وإن كانوا من أحطّ الناس قدراً.", "h": ["من الكمال العقلي أن يتبع المرء الهدى ولو خالفه قومه وأهل بلاده.", "وجوب البراءة من الشرك والمشركين، وهذا معنى لا إله إلا الله.", "فضيلة من يورّث أولاده هدى وصلاحاً.", "لا يعترض على الله أحد في شرعه وتدبيره إلا كفر، والعياذ بالله تعالى.", "بيان الحكمة في الغنى والفقر، والصحة والمرض، والذكاء والغباء."], "k": "«وجعلها كلمة باقية في عقبه»… ما الذي سأورّثه لأولادي ومن بعدي؛ مالاً أم كلمة باقية؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 360;
insert into public.tdb_cards(topic, i, body) select 360, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٥ – ٢٣", "q": "وَجَعَلُواْ لَهُۥ مِنۡ عِبَادِهِۦ جُزۡءًاۚ إِنَّ ٱلۡإِنسَٰنَ لَكَفُورٞ مُّبِينٌ ﴿١٥﴾ أَمِ ٱتَّخَذَ مِمَّا يَخۡلُقُ بَنَاتٖ وَأَصۡفَىٰكُم بِٱلۡبَنِينَ ﴿١٦﴾ وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحۡمَٰنِ مَثَلٗا ظَلَّ وَجۡهُهُۥ مُسۡوَدّٗا وَهُوَ كَظِيمٌ ﴿١٧﴾ أَوَمَن يُنَشَّؤُاْ فِي ٱلۡحِلۡيَةِ وَهُوَ فِي ٱلۡخِصَامِ غَيۡرُ مُبِينٖ ﴿١٨﴾ وَجَعَلُواْ ٱلۡمَلَـٰٓئِكَةَ ٱلَّذِينَ هُمۡ عِبَٰدُ ٱلرَّحۡمَٰنِ إِنَٰثًاۚ أَشَهِدُواْ خَلۡقَهُمۡۚ سَتُكۡتَبُ شَهَٰدَتُهُمۡ وَيُسۡـَٔلُونَ ﴿١٩﴾ وَقَالُواْ لَوۡ شَآءَ ٱلرَّحۡمَٰنُ مَا عَبَدۡنَٰهُمۗ مَّا لَهُم بِذَٰلِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا يَخۡرُصُونَ ﴿٢٠﴾ أَمۡ ءَاتَيۡنَٰهُمۡ كِتَٰبٗا مِّن قَبۡلِهِۦ فَهُم بِهِۦ مُسۡتَمۡسِكُونَ ﴿٢١﴾ بَلۡ قَالُوٓاْ إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهۡتَدُونَ ﴿٢٢﴾ وَكَذَٰلِكَ مَآ أَرۡسَلۡنَا مِن قَبۡلِكَ فِي قَرۡيَةٖ مِّن نَّذِيرٍ إِلَّا قَالَ مُتۡرَفُوهَآ إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقۡتَدُونَ ﴿٢٣﴾", "w": [["وجعلوا له من عباده جزءاً", "جعل المشركون المقرّون بأن الله خالق السماوات والأرض له من عباده جزءاً إذ قالوا: الملائكة بنات الله."], ["إن الإنسان لكفور مبين", "لكثير الكفر بيّنه."], ["وأصفاكم بالبنين", "خصّكم بالبنين وأخلصهم لكم."], ["بما ضرب للرحمن مثلاً", "بما جعل للرحمن شبهاً وهو الولد."], ["ظلّ وجهه مسودّاً وهو كظيم", "أقام طوال نهاره مسودّ الوجه من الحزن وهو ممتلئ غيظاً."], ["أوَمن يُنشّأ في الحلية", "أيجترئون على الله ويجعلون له جزءاً هو البنت التي تُربّى في الزينة؟"], ["وهو في الخصام غير مبين", "غير مُظهر للحجة لضعفه بالأنوثة."], ["عباد الرحمن إناثاً", "لأنهم قالوا: بنات الله."], ["أشهدوا خلقهم", "أحضروا خلقهم عندما كان الرحمن يخلقهم؟"], ["ستُكتب شهادتهم", "سيُكتب قولهم إن الملائكة إناث."], ["ويُسألون", "يوم القيامة عن شهادتهم الباطلة ويُعاقبون عليها."], ["ما لهم بذلك من علم", "دعواهم أن الله راضٍ عنهم بعبادة الملائكة لا دليل لهم عليها."], ["إن هم إلا يخرصون", "ما هم إلا يكذبون، يتوارثون الجهل عن بعضهم."], ["أم آتيناهم كتاباً من قبله", "أم أنزلنا عليهم كتاباً قبل القرآن؟"], ["فهم به مستمسكون", "متمسّكون بما فيه؟ لم يقع ذلك أبداً."], ["إنا وجدنا آباءنا على أمة", "لا حجة لهم إلا التقليد الأعمى لآبائهم، والأمة: الملة والدين."], ["وإنا على آثارهم مهتدون", "على طريقتهم ماشون، وهي عبادة غير الله."], ["إلا قال مترفوها", "متنعّموها."], ["وإنا على آثارهم مقتدون", "على طريقهم متبعون لهم فيها."]], "m": "ما زال السياق في دعوة المشركين إلى التوحيد منكراً عليهم باطلهم: وجعلوا لله من خلقه نصيباً حيث قالوا: الملائكة بنات الله، وهذا من أكذب الكذب وأكفر الكفر، إذ كيف عرفوا أنهم إناث وأنهم بنات الله وأنهم يستحقون العبادة فعبدوهم؟ إن الإنسان لكثير الكفر بيّنه. أتقولون اتخذ الله مما يخلق بنات وخصّكم بالبنين، ورضي لنفسه بالإناث اللاتي تبغضون؟ عجباً لهذا الفهم السقيم! وإذا بُشّر أحدهم ببنت ظل وجهه طوال النهار مسودّاً من الكآبة وهو ممتلئ غماً. أيجترئون ويجعلون لله من يُربّى في الزينة لنقصانه، وهو في الخصام لا يُظهر الحجة لضعفه بالخلقة؟ وجعلوا الملائكة الذين هم عباد الرحمن إناثاً وعبدوهم طلباً لشفاعتهم، أحضروا عندما كان الله يخلقهم؟ لا، ومن أين لهم ذلك؟ ستُكتب شهادتهم هذه ويُسألون عنها ويُعاقبون، لأنها الكذب على الله. وقالوا لمن أنكر عليهم: لو شاء الرحمن ما عبدناهم، ما لهم بذلك من علم برضا الله، إن هم إلا يكذبون، إذ العلم يأتي من طريق الكتاب أو النبي، ولا كتاب عندهم ولا نبي. أم آتيناهم كتاباً قبل القرآن فهم به مستمسكون؟ لا، فلا حجة لهم إلا التقليد الأعمى للآباء الجهال: إنا وجدنا آباءنا على ملة وإنا على آثارهم مهتدون. وكذلك ما أرسلنا من قبلك في قرية من رسول إلا قال متنعّموها: إنا وجدنا آباءنا على ملة وإنا على آثارهم مقتدون؛ فهذه سنة الأمم قبل أمتك، فلا تحزن عليهم.", "h": ["تقرير صفة من صفات الإنسان قبل شفائه بالإيمان والعبادة، وهي الكفر الواضح المبين.", "وجوب إنكار المنكر ومحاولة تغييره في حدود ما يسمح به الشرع وتتّسع له طاقة الإنسان.", "بيان حال المشركين العرب في الجاهلية من كراهيتهم البنات خوف العار.", "بيان ضعف المرأة ونقصانها، ولذا تكمُل بالزينة، وأن النقص فيها فطري في البدن والعقل.", "بيان أن من قال قولاً وشهد شهادة باطلة سوف يُسأل عنها يوم القيامة ويُعاقب عليها.", "حرمة القول على الله بدون علم، فلا يحل أن يُنسب إلى الله تعالى شيء لم ينسبه هو تعالى لنفسه.", "حرمة التقليد للآباء وأهل البلاد والمشايخ، فلا يُقبل قول إلا بدليل من الشرع."], "k": "«إنا وجدنا آباءنا على أمة»… ما الذي أفعله فقط لأني نشأت عليه، دون أن أعرف دليله؟"}, {"lbl": "الآيات ٢٤ – ٣٢", "q": "۞قَٰلَ أَوَلَوۡ جِئۡتُكُم بِأَهۡدَىٰ مِمَّا وَجَدتُّمۡ عَلَيۡهِ ءَابَآءَكُمۡۖ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ ﴿٢٤﴾ فَٱنتَقَمۡنَا مِنۡهُمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ ﴿٢٥﴾ وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ وَقَوۡمِهِۦٓ إِنَّنِي بَرَآءٞ مِّمَّا تَعۡبُدُونَ ﴿٢٦﴾ إِلَّا ٱلَّذِي فَطَرَنِي فَإِنَّهُۥ سَيَهۡدِينِ ﴿٢٧﴾ وَجَعَلَهَا كَلِمَةَۢ بَاقِيَةٗ فِي عَقِبِهِۦ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٢٨﴾ بَلۡ مَتَّعۡتُ هَـٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ جَآءَهُمُ ٱلۡحَقُّ وَرَسُولٞ مُّبِينٞ ﴿٢٩﴾ وَلَمَّا جَآءَهُمُ ٱلۡحَقُّ قَالُواْ هَٰذَا سِحۡرٞ وَإِنَّا بِهِۦ كَٰفِرُونَ ﴿٣٠﴾ وَقَالُواْ لَوۡلَا نُزِّلَ هَٰذَا ٱلۡقُرۡءَانُ عَلَىٰ رَجُلٖ مِّنَ ٱلۡقَرۡيَتَيۡنِ عَظِيمٍ ﴿٣١﴾ أَهُمۡ يَقۡسِمُونَ رَحۡمَتَ رَبِّكَۚ نَحۡنُ قَسَمۡنَا بَيۡنَهُم مَّعِيشَتَهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَتَّخِذَ بَعۡضُهُم بَعۡضٗا سُخۡرِيّٗاۗ وَرَحۡمَتُ رَبِّكَ خَيۡرٞ مِّمَّا يَجۡمَعُونَ ﴿٣٢﴾", "w": [["أوَلو جئتكم بأهدى مما وجدتم عليه آباءكم", "قال لهم رسولهم: أتتبعون آباءكم ولو جئتكم بخير مما وجدتم عليه آباءكم هداية؟"], ["إنا بما أُرسلتم به كافرون", "جاحدون منكرون غير معترفين به."], ["فانظر كيف كان عاقبة المكذبين", "كانت دماراً وهلاكاً، فلا تكترث بتكذيب قومك يا رسولنا."], ["وإذ قال إبراهيم", "واذكر إذ قال إبراهيم أبو الأنبياء خليل الرحمن."], ["إنني براء مما تعبدون", "بريء مما تعبدون من أصنام لا أعبدها."], ["إلا الذي فطرني فإنه سيهدين", "لكن الذي خلقني أعبده، فإنه سيرشدني إلى ما يكمّلني ويسعدني."], ["وجعلها كلمة باقية في عقبه", "جعل إبراهيم كلمة التوحيد «لا إله إلا الله» باقية في ذريته، إذ وصّاهم بها."], ["لعلهم يرجعون", "رجاء أن يتوبوا ويرجعوا إلى توحيده كلما ذكروها."], ["بل متّعت هؤلاء وآباءهم", "المشركين وآباءهم بالحياة فلم أعاجلهم بالعقوبة."], ["حتى جاءهم الحق ورسول مبين", "جاء القرآن يحمل الدين الحق، ورسول لا شك في رسالته، وهو محمد ﷺ."], ["على رجل من القريتين عظيم", "هلّا نزل على أحد رجلين من مكة أو الطائف: الوليد بن المغيرة أو عروة بن مسعود الثقفي."], ["أهم يقسمون رحمة ربك", "ينكر عليهم هذا التحكم، إذ النبوة من أعظم الرحمات وليس لهم حق في تنبئة أحد."], ["نحن قسمنا بينهم معيشتهم", "إذا كنا نحن نقسم معيشتهم فنغني هذا ونفقر هذا، فكيف بالنبوة وهي أجل من الطعام والشراب؟"], ["ليتخذ بعضهم بعضاً سُخرياً", "جعلنا هذا غنياً وذاك فقيراً ليتخذ الغني الفقير خادماً يسخّره في خدمته بأجرة."], ["ورحمة ربك خير مما يجمعون", "الجنة التي أعدّها الله لك ولأتباعك خير من المال الذي يجمعه المشركون."]], "m": "لما ذكر قول المشركين لرسلهم: إنا وجدنا آباءنا على ملة، أخبر عن قول الرسول لأمته المكذبة المقلّدة: أتتبعون آباءكم ولا تتبعونني ولو جئتكم بأهدى إلى الخير مما وجدتم عليه آباءكم؟ إذ العاقل يتبع الهدى جاء به من جاء. فقالت كل أمة لرسولها: إنا بما أُرسلتم به من التوحيد والبعث والشرع كافرون، فانتقمنا منهم فأهلكناهم، فانظر كيف كان عاقبتهم، وليذكر هذا قومك. واذكر لقومك قول إبراهيم الذي ينتسبون إليه باطلاً لأبيه وقومه: إنني بريء من آلهتكم، إلا الذي خلقني فهو أحق بعبادتي مما لم يخلقني ولم يخلق شيئاً، فإنه سيرشدني دائماً. وجعل براءته من الشرك وعبادته الخاصة بالله كلمة باقية في ذريته، إذ وصّاهم بها كما في البقرة: ووصّى بها إبراهيم بنيه، وهي لا إله إلا الله، لعلهم يرجعون إليها كلما غفلوا، فجزى الله إبراهيم عن المؤمنين خيراً. بل لم يتحقق ما ترجّاه إبراهيم كاملاً، إذ أشرك من بنيه من أشرك، ومنهم هؤلاء المعاصرون لك، متّعتهم وآباءهم بالحياة حتى جاءهم الحق، القرآن، يتلوه الرسول المبيّن لكل الشرائع، فقالوا: هذا سحر وإنا به كافرون، وقالوا: هلّا نزل هذا القرآن على رجل شريف ذي مكانة كالوليد بن المغيرة في مكة أو عروة بن مسعود في الطائف؛ وهذه نظرة مادية بحتة، رأوا الشرف بالمال، ولما كان محمد لا مال له رأوه ليس أهلاً للرسالة. فردّ عليهم: أهم يقسمون رحمة ربك فيعطون منها من شاؤوا؟ نحن قسمنا بينهم معيشتهم، فالعاجز حتى عن إطعام نفسه كيف لا يستحي أن يعترض على الله في اختياره من هو أهل لنبوته؟ ورفعنا بعضهم فوق بعض درجات في الرزق ليخدم الفقير الغني، إذ لو كانوا كلهم أغنياء لما خدم أحد أحداً وتعطّلت الحياة. ورحمة ربك، الجنة، خير مما يجمعون من المال الذي فضّلوا أهله وإن كانوا من أحطّ الناس قدراً.", "h": ["من الكمال العقلي أن يتبع المرء الهدى ولو خالفه قومه وأهل بلاده.", "وجوب البراءة من الشرك والمشركين، وهذا معنى لا إله إلا الله.", "فضيلة من يورّث أولاده هدى وصلاحاً.", "لا يعترض على الله أحد في شرعه وتدبيره إلا كفر، والعياذ بالله تعالى.", "بيان الحكمة في الغنى والفقر، والصحة والمرض، والذكاء والغباء."], "k": "«وجعلها كلمة باقية في عقبه»… ما الذي سأورّثه لأولادي ومن بعدي؛ مالاً أم كلمة باقية؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (361, 43, 33, 40, 'سورة الزخرف ٣٣ – ٤٠', 'الزخرف: ومن يعشُ عن ذكر الرحمن', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 361) = $j$[{"lbl": "الآيات ٣٣ – ٣٥", "q": "وَلَوۡلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ لَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ وَمَعَارِجَ عَلَيۡهَا يَظۡهَرُونَ ﴿٣٣﴾ وَلِبُيُوتِهِمۡ أَبۡوَٰبٗا وَسُرُرًا عَلَيۡهَا يَتَّكِـُٔونَ ﴿٣٤﴾ وَزُخۡرُفٗاۚ وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَٱلۡأٓخِرَةُ عِندَ رَبِّكَ لِلۡمُتَّقِينَ ﴿٣٥﴾", "w": [["أمة واحدة", "على الكفر."], ["ومعارج", "كالسلم والمصعد الحديث، جمع معرج."], ["عليها يظهرون", "يعلون عليها إلى السطوح."], ["وزخرفاً", "ذهباً، أي لجعلنا لبيوتهم سقفاً وأبواباً ومصاعد وسرراً بعضها من فضة وبعضها من ذهب."], ["وإن كل ذلك لمّا متاع الحياة الدنيا", "ما كل ذلك إلا متاع الحياة الدنيا يُتمتّع به فيها ثم يزول."], ["والآخرة عند ربك للمتقين", "الجنة ونعيمها خير لأهل الإيمان والتقوى من متاع الدنيا."]], "m": "لما فضّل تعالى الجنة على المال والمتاع الدنيوي في الآيات السابقة قال: ولولا أن يكون الناس أمة واحدة على الكفر لجعلنا لمن يكفر بالرحمن لبيوتهم سقفاً من فضة، ومصاعد عليها يعلون إلى الغرف والسطوح من فضة، ولبيوتهم أبواباً وسرراً عليها يتكئون من فضة، وذهباً أي بعض المذكور من فضة وبعضه من ذهب ليكون أجمل وأبهى. وما كل ذلك إلا متاع الحياة الدنيا يتمتّع به الناس ثم يزول بزوالهم، والآخرة عند ربك، الجنة ونعيمها المقيم، للمتقين الذين اتقوا الشرك والمعاصي، وما عند الله خير مما عند الناس، وما يبقى خير مما يفنى؛ ولذا قال الحكماء: لو كانت الدنيا من ذهب والآخرة من خزف لاختار العاقل الآخرة على الدنيا، وهو اختيار ما يبقى على ما يفنى.", "h": ["الميل إلى الدنيا وطلب متاعها فطري في الإنسان، فلذا لو أُعطيها الكافر بكفره لمال إليها كل الناس وطلبوها بالكفر.", "هوان الدنيا على الله وعدم الاكتراث بها، إذ قال رسول الله ﷺ: «لو كانت الدنيا تعدل عند الله جناح بعوضة ما سقى كافراً منها شربة ماء» رواه الترمذي وصححه، وفي صحيح مسلم: «الدنيا سجن المؤمن وجنة الكافر».", "بيان أن الآخرة خير للمتقين."], "k": "«وإن كل ذلك لمّا متاع الحياة الدنيا»… الذهب على سقوف الكافرين لو شاء الله؛ فلماذا أحزن على ما فاتني من الدنيا؟"}, {"lbl": "الآيات ٣٦ – ٤٠", "q": "وَمَن يَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَٰنِ نُقَيِّضۡ لَهُۥ شَيۡطَٰنٗا فَهُوَ لَهُۥ قَرِينٞ ﴿٣٦﴾ وَإِنَّهُمۡ لَيَصُدُّونَهُمۡ عَنِ ٱلسَّبِيلِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ ﴿٣٧﴾ حَتَّىٰٓ إِذَا جَآءَنَا قَالَ يَٰلَيۡتَ بَيۡنِي وَبَيۡنَكَ بُعۡدَ ٱلۡمَشۡرِقَيۡنِ فَبِئۡسَ ٱلۡقَرِينُ ﴿٣٨﴾ وَلَن يَنفَعَكُمُ ٱلۡيَوۡمَ إِذ ظَّلَمۡتُمۡ أَنَّكُمۡ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ ﴿٣٩﴾ أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ أَوۡ تَهۡدِي ٱلۡعُمۡيَ وَمَن كَانَ فِي ضَلَٰلٖ مُّبِينٖ ﴿٤٠﴾", "w": [["ومن يعشُ عن ذكر الرحمن", "يعرض متعامياً متغافلاً عن ذكر الرحمن الذي هو القرآن."], ["نقيّض له شيطاناً", "نجعل له شيطاناً يلازمه لإضلاله وإغوائه."], ["فهو له قرين", "فهو قرين للشيطان لا يفارقه."], ["وإنهم ليصدّونهم عن السبيل", "وإن الشياطين المقارنين لهم ليصدّونهم عن طريق الهدى."], ["ويحسبون أنهم مهتدون", "ويحسب العاشون عن القرآن أنهم على الحق، بتزيين الشياطين لهم."], ["ولن ينفعكم اليوم إذ ظلمتم", "لن ينفعكم أيها العاشون إذ ظلمتم أنفسكم بالشرك."], ["أنكم في العذاب مشتركون", "اشتراككم في العذاب غير نافع لكم."], ["أفأنت تُسمع الصم أو تهدي العمي", "إنك لا تُسمع الصم ولا تهدي العمي، والقوم قد أصمّهم الله وأعمى أبصارهم لأنهم عشوا عن ذكره."], ["ومن كان في ضلال مبين", "كما أنك لا تقدر على هداية من كان في ضلال مبين."]], "m": "ما زال السياق في عرض الهداية على الضالين بالكشف عن أحوالهم: ومن يعرض متعامياً متغافلاً عن ذكر الرحمن، القرآن وعبادة الله، نجعل له شيطاناً قريناً لا يفارقه في الدنيا ولا في الآخرة. وإن القرناء الذين جعلهم الله حسب سنته في الأسباب والمسبّبات للعاشين عن ذكره ليصدّونهم بتزيين كل المعاصي حتى انغمسوا في كل إثم وضلّوا عن سبيل الرشد، ومع هذا يحسبون أنهم مهتدون وغيرهم الظالمون. حتى إذا جاءنا يوم القيامة قال العاشي عن ذكر الرحمن متمنّياً: يا ليت بيني وبينك يا قريني من الشياطين بُعد ما بين المشرق والمغرب، فبئس القرين. ويقال لهم: لن ينفعكم اليوم إذ ظلمتم أنفسكم بالشرك والمعاصي في الدنيا أن اشتراككم في العذاب. ثم أنكر على رسوله ظنّه أنه يقدر على هدايتهم بدون إرادة الله، إذ كان ﷺ يجتهد في دعائهم وهم لا يزدادون إلا تعامياً: أفأنت تُسمع الصمّ الذين ذهب الله بأسماعهم، أو تهدي العمي الذين ذهب الله بأبصارهم، ومن كان في ضلال مبين؟ إنك لا تقدر على ذلك، فهوّن على نفسك وترفّق في دعوتك، فإنك لا تُكلّف غير البلاغ وقد بلّغت.", "h": ["بيان سنة الله تعالى فيمن يعرض عن ذكر الله، فإنه يسبّب له شيطاناً يضله ويحرمه الهداية أبداً، فيقيم على الذنوب والآثام ضالاً الطريق المنجي المسعد وهو يحسب أنه مهتدٍ، وهذا يتعرّض له المعرضون عن الكتاب والسنة كالمبتدعة وأصحاب الأهواء والشهوات، والعياذ بالله تعالى.", "الاشتراك في العذاب يوم القيامة لا يخفّفه.", "بيان أن من أعماه الله وأصمّه حسب سنته في ذلك لا هادي له ولا مُسمع له ولا مُبصر."], "k": "«ومن يعشُ عن ذكر الرحمن نقيّض له شيطاناً»… كل فراغ أتركه من الذكر يملؤه شيء آخر؛ فبماذا أملأ يومي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 361;
insert into public.tdb_cards(topic, i, body) select 361, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٣ – ٣٥", "q": "وَلَوۡلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ لَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ وَمَعَارِجَ عَلَيۡهَا يَظۡهَرُونَ ﴿٣٣﴾ وَلِبُيُوتِهِمۡ أَبۡوَٰبٗا وَسُرُرًا عَلَيۡهَا يَتَّكِـُٔونَ ﴿٣٤﴾ وَزُخۡرُفٗاۚ وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَٱلۡأٓخِرَةُ عِندَ رَبِّكَ لِلۡمُتَّقِينَ ﴿٣٥﴾", "w": [["أمة واحدة", "على الكفر."], ["ومعارج", "كالسلم والمصعد الحديث، جمع معرج."], ["عليها يظهرون", "يعلون عليها إلى السطوح."], ["وزخرفاً", "ذهباً، أي لجعلنا لبيوتهم سقفاً وأبواباً ومصاعد وسرراً بعضها من فضة وبعضها من ذهب."], ["وإن كل ذلك لمّا متاع الحياة الدنيا", "ما كل ذلك إلا متاع الحياة الدنيا يُتمتّع به فيها ثم يزول."], ["والآخرة عند ربك للمتقين", "الجنة ونعيمها خير لأهل الإيمان والتقوى من متاع الدنيا."]], "m": "لما فضّل تعالى الجنة على المال والمتاع الدنيوي في الآيات السابقة قال: ولولا أن يكون الناس أمة واحدة على الكفر لجعلنا لمن يكفر بالرحمن لبيوتهم سقفاً من فضة، ومصاعد عليها يعلون إلى الغرف والسطوح من فضة، ولبيوتهم أبواباً وسرراً عليها يتكئون من فضة، وذهباً أي بعض المذكور من فضة وبعضه من ذهب ليكون أجمل وأبهى. وما كل ذلك إلا متاع الحياة الدنيا يتمتّع به الناس ثم يزول بزوالهم، والآخرة عند ربك، الجنة ونعيمها المقيم، للمتقين الذين اتقوا الشرك والمعاصي، وما عند الله خير مما عند الناس، وما يبقى خير مما يفنى؛ ولذا قال الحكماء: لو كانت الدنيا من ذهب والآخرة من خزف لاختار العاقل الآخرة على الدنيا، وهو اختيار ما يبقى على ما يفنى.", "h": ["الميل إلى الدنيا وطلب متاعها فطري في الإنسان، فلذا لو أُعطيها الكافر بكفره لمال إليها كل الناس وطلبوها بالكفر.", "هوان الدنيا على الله وعدم الاكتراث بها، إذ قال رسول الله ﷺ: «لو كانت الدنيا تعدل عند الله جناح بعوضة ما سقى كافراً منها شربة ماء» رواه الترمذي وصححه، وفي صحيح مسلم: «الدنيا سجن المؤمن وجنة الكافر».", "بيان أن الآخرة خير للمتقين."], "k": "«وإن كل ذلك لمّا متاع الحياة الدنيا»… الذهب على سقوف الكافرين لو شاء الله؛ فلماذا أحزن على ما فاتني من الدن