 تهدي العمي الذين ذهب الله بأبصارهم، ومن كان في ضلال مبين؟ إنك لا تقدر على ذلك، فهوّن على نفسك وترفّق في دعوتك، فإنك لا تُكلّف غير البلاغ وقد بلّغت.", "h": ["بيان سنة الله تعالى فيمن يعرض عن ذكر الله، فإنه يسبّب له شيطاناً يضله ويحرمه الهداية أبداً، فيقيم على الذنوب والآثام ضالاً الطريق المنجي المسعد وهو يحسب أنه مهتدٍ، وهذا يتعرّض له المعرضون عن الكتاب والسنة كالمبتدعة وأصحاب الأهواء والشهوات، والعياذ بالله تعالى.", "الاشتراك في العذاب يوم القيامة لا يخفّفه.", "بيان أن من أعماه الله وأصمّه حسب سنته في ذلك لا هادي له ولا مُسمع له ولا مُبصر."], "k": "«ومن يعشُ عن ذكر الرحمن نقيّض له شيطاناً»… كل فراغ أتركه من الذكر يملؤه شيء آخر؛ فبماذا أملأ يومي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (362, 43, 41, 56, 'سورة الزخرف ٤١ – ٥٦', 'الزخرف: فاستمسك بالذي أوحي إليك', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 362) = $j$[{"lbl": "الآيات ٤١ – ٤٥", "q": "فَإِمَّا نَذۡهَبَنَّ بِكَ فَإِنَّا مِنۡهُم مُّنتَقِمُونَ ﴿٤١﴾ أَوۡ نُرِيَنَّكَ ٱلَّذِي وَعَدۡنَٰهُمۡ فَإِنَّا عَلَيۡهِم مُّقۡتَدِرُونَ ﴿٤٢﴾ فَٱسۡتَمۡسِكۡ بِٱلَّذِيٓ أُوحِيَ إِلَيۡكَۖ إِنَّكَ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٤٣﴾ وَإِنَّهُۥ لَذِكۡرٞ لَّكَ وَلِقَوۡمِكَۖ وَسَوۡفَ تُسۡـَٔلُونَ ﴿٤٤﴾ وَسۡـَٔلۡ مَنۡ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رُّسُلِنَآ أَجَعَلۡنَا مِن دُونِ ٱلرَّحۡمَٰنِ ءَالِهَةٗ يُعۡبَدُونَ ﴿٤٥﴾", "w": [["فإما نذهبنّ بك", "فإن نذهب بك أي نميتك قبل تعذيبهم، و«ما» زائدة أُدغمت فيها «إن» الشرطية."], ["فإنا منهم منتقمون", "معذّبوهم في الدنيا وفي الآخرة."], ["أو نرينّك الذي وعدناهم", "بعض الذي نعدهم من العذاب."], ["فإنا عليهم مقتدرون", "لا يعوقنا عائق، لأنا عليهم قادرون."], ["فاستمسك بالذي أوحي إليك", "دُم على استمساكك بالقرآن، سواء عجّلنا لك بالموعود به أو أخّرناه."], ["إنك على صراط مستقيم", "على طريق الحق والهدى، فواصل سيرك."], ["وإنه لذكر لك ولقومك", "وإن القرآن لشرف لك ولقومك."], ["وسوف تُسألون", "عن القرآن، أي عن العمل به بتطبيق شرائعه وإبلاغه."], ["واسأل من أرسلنا من قبلك من رسلنا", "اسأل مؤمني أهل الكتابين التوراة والإنجيل."], ["أجعلنا من دون الرحمن آلهة يُعبدون", "والجواب: لم نجعل أبداً، فليفهم هذا مشركو مكة."]], "m": "ما زال السياق في دعوة كفار قريش إلى الإيمان والتوحيد: فإن نذهب بك فنخرجك من مكة أو نميتك فإنا منهم منتقمون كما انتقمنا من الأمم قبلهم عندما أخرجوا رسولهم، أو نرينّك الذي وعدناهم من نصرك عليهم وغلبتك لهم، فإنا عليهم قادرون. فتمسّك يا رسولنا بما يأمرك به هذا القرآن الذي أوحاه إليك ربك، إنك على صراط مستقيم هو الإسلام الذي لا يشقى من تمسّك به فعاش عليه ومات عليه. وإن القرآن لشرف لك ولقومك من قريش إذا آمنوا به وعملوا بما فيه، وسوف تُسألون عن العمل به وتطبيق أحكامه والالتزام بشرائعه. واسأل يا رسولنا مؤمني أهل التوراة والإنجيل، وسؤالهم سؤال رسلهم الذين ماتوا من قبلك: هل جعل الله من دونه آلهة يُعبدون؟ وسوف يجيبونك: حاشا لله أن يأذن بعبادة غيره من خلقه؛ وهذا لتنبيه أذهان قريش إلى خطئها الفاحش في إصرارها على عبادة الأصنام.", "h": ["من سنة الله في الأمم إذا أخرجت الرسول أو قتلته أو همّت بمكره انتقم الله تعالى له منهم فأهلكهم.", "صدق وعد الله تعالى لرسوله، فإنه ما توفّاه حتى أقرّ عينه بنصره على أعدائه.", "وجوب التمسك بالكتاب والسنة اعتقاداً وعملاً.", "شرف هذه الأمة بالقرآن، فإن أضاعته أضاعها الله وأذلّها."], "k": "«وإنه لذكر لك ولقومك وسوف تُسألون»… شرفي في القرآن، وسأُسأل عنه؛ فماذا أعددت من جواب؟"}, {"lbl": "الآيات ٤٦ – ٥٠", "q": "وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَقَالَ إِنِّي رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ ﴿٤٦﴾ فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنۡهَا يَضۡحَكُونَ ﴿٤٧﴾ وَمَا نُرِيهِم مِّنۡ ءَايَةٍ إِلَّا هِيَ أَكۡبَرُ مِنۡ أُخۡتِهَاۖ وَأَخَذۡنَٰهُم بِٱلۡعَذَابِ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٤٨﴾ وَقَالُواْ يَـٰٓأَيُّهَ ٱلسَّاحِرُ ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهۡتَدُونَ ﴿٤٩﴾ فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِذَا هُمۡ يَنكُثُونَ ﴿٥٠﴾", "w": [["ولقد أرسلنا موسى بآياتنا", "بالمعجزات الدالة على صدق رسالته."], ["إلى فرعون وملئه", "وقومه من القبط."], ["إذا هم منها يضحكون", "سخرية واستهزاءً."], ["وما نريهم من آية", "من آيات العذاب كالطوفان."], ["إلا هي أكبر من أختها", "من قرينتها التي قبلها من الآيات."], ["وقالوا يا أيها الساحر", "أيها العالم بالسحر المتبحّر فيه."], ["بما عهد عندك", "من كشف العذاب عنا إن آمنا."], ["إننا لمهتدون", "إن كشفت عنا العذاب إنا مؤمنون."], ["إذا هم ينكثون", "ينقضون عهدهم فلم يؤمنوا."]], "m": "إيراد هذا القصص هنا لمشابهة حال قريش بحال فرعون: إذ قال رجال قريش: لِمَ لا يكون الرسول من ذوي المال والجاه كالوليد بن المغيرة أو عروة بن مسعود؟ وقال فرعون: أم أنا خير من هذا الذي هو مهين؟ يعني موسى ﵇؛ ولتسلية الرسول ﷺ وحمله على الصبر كما صبر موسى، وهو أحد أولي العزم الخمسة. ولقد أرسلنا موسى بحججنا إلى فرعون وقومه بأن يعبدوا الله ويتركوا عبادة غيره، وأن يرسلوا معه بني إسرائيل ليذهب بهم إلى أرض الميعاد فلسطين، فقال: إني رسول رب العالمين، فطالبوه بالآيات، فلما جاءهم بالآيات العظام فاجؤوه بالضحك منها والسخرية. وما نريهم من آية إلا هي أكبر دلالة على صدق موسى من التي سبقتها، وأخذناهم بالعذاب لعلهم يرجعون إلى الحق. وقالوا لموسى: يا أيها العالم بالسحر، ظناً منهم أن المعجزات عمل ساحر، ادع لنا ربك أن يرفع عنا هذا العذاب كالطوفان والجراد والقمل والضفادع إنا مؤمنون، فكانوا كلما نزل بهم العذاب سألوا موسى ووعدوه بالإيمان، فلما كشف الله عنهم العذاب إذا هم ينقضون العهد ولا يؤمنون.", "h": ["الآيات دليل على صدق من جاء بها، ولكن لا تستلزم الإيمان ممن شاهدها.", "قد يؤاخذ الله الأفراد أو الجماعات بالذنب المرة بعد المرة لعلهم يتوبون إليه.", "حرمة خلف الوعد ونكث العهد، وأنهما من آيات النفاق وعلاماته."], "k": "«فلما كشفنا عنهم العذاب إذا هم ينكثون»… كم وعدتُ الله في شدة ثم نسيت بعد الفرج؟"}, {"lbl": "الآيات ٥١ – ٥٦", "q": "وَنَادَىٰ فِرۡعَوۡنُ فِي قَوۡمِهِۦ قَالَ يَٰقَوۡمِ أَلَيۡسَ لِي مُلۡكُ مِصۡرَ وَهَٰذِهِ ٱلۡأَنۡهَٰرُ تَجۡرِي مِن تَحۡتِيٓۚ أَفَلَا تُبۡصِرُونَ ﴿٥١﴾ أَمۡ أَنَا۠ خَيۡرٞ مِّنۡ هَٰذَا ٱلَّذِي هُوَ مَهِينٞ وَلَا يَكَادُ يُبِينُ ﴿٥٢﴾ فَلَوۡلَآ أُلۡقِيَ عَلَيۡهِ أَسۡوِرَةٞ مِّن ذَهَبٍ أَوۡ جَآءَ مَعَهُ ٱلۡمَلَـٰٓئِكَةُ مُقۡتَرِنِينَ ﴿٥٣﴾ فَٱسۡتَخَفَّ قَوۡمَهُۥ فَأَطَاعُوهُۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ ﴿٥٤﴾ فَلَمَّآ ءَاسَفُونَا ٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ ﴿٥٥﴾ فَجَعَلۡنَٰهُمۡ سَلَفٗا وَمَثَلٗا لِّلۡأٓخِرِينَ ﴿٥٦﴾", "w": [["ونادى فرعون في قومه", "نادى فيهم افتخاراً وتبجّحاً بما عنده."], ["وهذه الأنهار تجري من تحتي", "أنهار النيل تجري من تحت قصوري."], ["أفلا تبصرون", "عظمتي وما أنا عليه من الجلال والكمال."], ["أم أنا خير", "من موسى الذي هو مهين ولا يكاد يُفصح للُثغة في لسانه."], ["فلولا أُلقي عليه أسورة من ذهب", "هلّا أُلقي عليه أسورة من ذهب من قِبل الذي أرسله."], ["أو جاء معه الملائكة مقترنين", "يتبع بعضها بعضاً تشهد له بالرسالة."], ["فاستخفّ قومه", "استفزّهم بما حرّكهم به فخفّوا لطاعته."], ["إنهم كانوا قوماً فاسقين", "أطاعوه لكونهم قوماً فاسقين، ففسقهم علة طاعتهم."], ["فلما آسفونا انتقمنا منهم", "فلما أغضبونا انتقمنا منهم."], ["فجعلناهم سلفاً", "سابقين ليكونوا عبرة لمن بعدهم."], ["ومثلاً للآخرين", "يتمثّلون بحالهم فلا يُقدمون على مثل فعلهم."]], "m": "ما زال السياق في قصة موسى مع فرعون: ونادى فرعون في قومه افتخاراً وتطاولاً وإرهاباً للناس: يا قوم أليس لي ملك مصر، وهذه أنهار النيل تجري من تحت قصوري، أفلا تبصرون؟ فإذا أبصرتم فقولوا: أنا خير من هذا الذي هو حقير يتولّى الخدمة بنفسه، ولا يكاد يُفصح بلسانه لعلة به وهي اللثغة. فهلّا ألقى عليه من أرسله أسورة من ذهب، أو بعث معه الملائكة مقترنين يشهدون له بالرسالة. فاستفزّ قومه بقوله هذا فأطاعوه، إنهم كانوا قوماً فاسقين، والفاسق جبان خوّاف يستجيب بسرعة للباطل إن كان ممن يُخاف عادة كالحاكم الظالم. فلما أغضبونا بنكثهم وكفرهم وكبريائهم وظلمهم انتقمنا منهم فأغرقناهم أجمعين فلم نبق منهم أحداً، فجعلنا فرعون ومن أغرقنا معه من ملئه وجيوشه سابقين ليكونوا عبرة لمن بعدهم، ومثلاً يتمثّل به من بعدهم فلا يُقدمون على ما أقدموا عليه من الكفر والظلم والفساد، وأولى من يعتبر بهذا قريش التي نزل القرآن ليحرّك كامن نفسها لتنتبه من غفلتها فتؤمن فتنجو.", "h": ["ذمّ الفخر والمباهاة، إذ هما من صفات المتكبرين والظالمين.", "الاحتقار للفقراء والازدراء بهم من صفات الجبارين الظلمة المتكبرين.", "الفسق يجعل صاحبه مطية لكل ظالم، أداة يسخّره كما يشاء.", "التحذير من غضب الرب تبارك وتعالى، فإنه متى غضب انتقم فبطش."], "k": "«فاستخفّ قومه فأطاعوه»… من يستخفّني اليوم بكلامه فأتبعه بلا تفكير؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 362;
insert into public.tdb_cards(topic, i, body) select 362, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤١ – ٤٥", "q": "فَإِمَّا نَذۡهَبَنَّ بِكَ فَإِنَّا مِنۡهُم مُّنتَقِمُونَ ﴿٤١﴾ أَوۡ نُرِيَنَّكَ ٱلَّذِي وَعَدۡنَٰهُمۡ فَإِنَّا عَلَيۡهِم مُّقۡتَدِرُونَ ﴿٤٢﴾ فَٱسۡتَمۡسِكۡ بِٱلَّذِيٓ أُوحِيَ إِلَيۡكَۖ إِنَّكَ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٤٣﴾ وَإِنَّهُۥ لَذِكۡرٞ لَّكَ وَلِقَوۡمِكَۖ وَسَوۡفَ تُسۡـَٔلُونَ ﴿٤٤﴾ وَسۡـَٔلۡ مَنۡ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رُّسُلِنَآ أَجَعَلۡنَا مِن دُونِ ٱلرَّحۡمَٰنِ ءَالِهَةٗ يُعۡبَدُونَ ﴿٤٥﴾", "w": [["فإما نذهبنّ بك", "فإن نذهب بك أي نميتك قبل تعذيبهم، و«ما» زائدة أُدغمت فيها «إن» الشرطية."], ["فإنا منهم منتقمون", "معذّبوهم في الدنيا وفي الآخرة."], ["أو نرينّك الذي وعدناهم", "بعض الذي نعدهم من العذاب."], ["فإنا عليهم مقتدرون", "لا يعوقنا عائق، لأنا عليهم قادرون."], ["فاستمسك بالذي أوحي إليك", "دُم على استمساكك بالقرآن، سواء عجّلنا لك بالموعود به أو أخّرناه."], ["إنك على صراط مستقيم", "على طريق الحق والهدى، فواصل سيرك."], ["وإنه لذكر لك ولقومك", "وإن القرآن لشرف لك ولقومك."], ["وسوف تُسألون", "عن القرآن، أي عن العمل به بتطبيق شرائعه وإبلاغه."], ["واسأل من أرسلنا من قبلك من رسلنا", "اسأل مؤمني أهل الكتابين التوراة والإنجيل."], ["أجعلنا من دون الرحمن آلهة يُعبدون", "والجواب: لم نجعل أبداً، فليفهم هذا مشركو مكة."]], "m": "ما زال السياق في دعوة كفار قريش إلى الإيمان والتوحيد: فإن نذهب بك فنخرجك من مكة أو نميتك فإنا منهم منتقمون كما انتقمنا من الأمم قبلهم عندما أخرجوا رسولهم، أو نرينّك الذي وعدناهم من نصرك عليهم وغلبتك لهم، فإنا عليهم قادرون. فتمسّك يا رسولنا بما يأمرك به هذا القرآن الذي أوحاه إليك ربك، إنك على صراط مستقيم هو الإسلام الذي لا يشقى من تمسّك به فعاش عليه ومات عليه. وإن القرآن لشرف لك ولقومك من قريش إذا آمنوا به وعملوا بما فيه، وسوف تُسألون عن العمل به وتطبيق أحكامه والالتزام بشرائعه. واسأل يا رسولنا مؤمني أهل التوراة والإنجيل، وسؤالهم سؤال رسلهم الذين ماتوا من قبلك: هل جعل الله من دونه آلهة يُعبدون؟ وسوف يجيبونك: حاشا لله أن يأذن بعبادة غيره من خلقه؛ وهذا لتنبيه أذهان قريش إلى خطئها الفاحش في إصرارها على عبادة الأصنام.", "h": ["من سنة الله في الأمم إذا أخرجت الرسول أو قتلته أو همّت بمكره انتقم الله تعالى له منهم فأهلكهم.", "صدق وعد الله تعالى لرسوله، فإنه ما توفّاه حتى أقرّ عينه بنصره على أعدائه.", "وجوب التمسك بالكتاب والسنة اعتقاداً وعملاً.", "شرف هذه الأمة بالقرآن، فإن أضاعته أضاعها الله وأذلّها."], "k": "«وإنه لذكر لك ولقومك وسوف تُسألون»… شرفي في القرآن، وسأُسأل عنه؛ فماذا أعددت من جواب؟"}, {"lbl": "الآيات ٤٦ – ٥٠", "q": "وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَقَالَ إِنِّي رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ ﴿٤٦﴾ فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنۡهَا يَضۡحَكُونَ ﴿٤٧﴾ وَمَا نُرِيهِم مِّنۡ ءَايَةٍ إِلَّا هِيَ أَكۡبَرُ مِنۡ أُخۡتِهَاۖ وَأَخَذۡنَٰهُم بِٱلۡعَذَابِ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٤٨﴾ وَقَالُواْ يَـٰٓأَيُّهَ ٱلسَّاحِرُ ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهۡتَدُونَ ﴿٤٩﴾ فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِذَا هُمۡ يَنكُثُونَ ﴿٥٠﴾", "w": [["ولقد أرسلنا موسى بآياتنا", "بالمعجزات الدالة على صدق رسالته."], ["إلى فرعون وملئه", "وقومه من القبط."], ["إذا هم منها يضحكون", "سخرية واستهزاءً."], ["وما نريهم من آية", "من آيات العذاب كالطوفان."], ["إلا هي أكبر من أختها", "من قرينتها التي قبلها من الآيات."], ["وقالوا يا أيها الساحر", "أيها العالم بالسحر المتبحّر فيه."], ["بما عهد عندك", "من كشف العذاب عنا إن آمنا."], ["إننا لمهتدون", "إن كشفت عنا العذاب إنا مؤمنون."], ["إذا هم ينكثون", "ينقضون عهدهم فلم يؤمنوا."]], "m": "إيراد هذا القصص هنا لمشابهة حال قريش بحال فرعون: إذ قال رجال قريش: لِمَ لا يكون الرسول من ذوي المال والجاه كالوليد بن المغيرة أو عروة بن مسعود؟ وقال فرعون: أم أنا خير من هذا الذي هو مهين؟ يعني موسى ﵇؛ ولتسلية الرسول ﷺ وحمله على الصبر كما صبر موسى، وهو أحد أولي العزم الخمسة. ولقد أرسلنا موسى بحججنا إلى فرعون وقومه بأن يعبدوا الله ويتركوا عبادة غيره، وأن يرسلوا معه بني إسرائيل ليذهب بهم إلى أرض الميعاد فلسطين، فقال: إني رسول رب العالمين، فطالبوه بالآيات، فلما جاءهم بالآيات العظام فاجؤوه بالضحك منها والسخرية. وما نريهم من آية إلا هي أكبر دلالة على صدق موسى من التي سبقتها، وأخذناهم بالعذاب لعلهم يرجعون إلى الحق. وقالوا لموسى: يا أيها العالم بالسحر، ظناً منهم أن المعجزات عمل ساحر، ادع لنا ربك أن يرفع عنا هذا العذاب كالطوفان والجراد والقمل والضفادع إنا مؤمنون، فكانوا كلما نزل بهم العذاب سألوا موسى ووعدوه بالإيمان، فلما كشف الله عنهم العذاب إذا هم ينقضون العهد ولا يؤمنون.", "h": ["الآيات دليل على صدق من جاء بها، ولكن لا تستلزم الإيمان ممن شاهدها.", "قد يؤاخذ الله الأفراد أو الجماعات بالذنب المرة بعد المرة لعلهم يتوبون إليه.", "حرمة خلف الوعد ونكث العهد، وأنهما من آيات النفاق وعلاماته."], "k": "«فلما كشفنا عنهم العذاب إذا هم ينكثون»… كم وعدتُ الله في شدة ثم نسيت بعد الفرج؟"}, {"lbl": "الآيات ٥١ – ٥٦", "q": "وَنَادَىٰ فِرۡعَوۡنُ فِي قَوۡمِهِۦ قَالَ يَٰقَوۡمِ أَلَيۡسَ لِي مُلۡكُ مِصۡرَ وَهَٰذِهِ ٱلۡأَنۡهَٰرُ تَجۡرِي مِن تَحۡتِيٓۚ أَفَلَا تُبۡصِرُونَ ﴿٥١﴾ أَمۡ أَنَا۠ خَيۡرٞ مِّنۡ هَٰذَا ٱلَّذِي هُوَ مَهِينٞ وَلَا يَكَادُ يُبِينُ ﴿٥٢﴾ فَلَوۡلَآ أُلۡقِيَ عَلَيۡهِ أَسۡوِرَةٞ مِّن ذَهَبٍ أَوۡ جَآءَ مَعَهُ ٱلۡمَلَـٰٓئِكَةُ مُقۡتَرِنِينَ ﴿٥٣﴾ فَٱسۡتَخَفَّ قَوۡمَهُۥ فَأَطَاعُوهُۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ ﴿٥٤﴾ فَلَمَّآ ءَاسَفُونَا ٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ ﴿٥٥﴾ فَجَعَلۡنَٰهُمۡ سَلَفٗا وَمَثَلٗا لِّلۡأٓخِرِينَ ﴿٥٦﴾", "w": [["ونادى فرعون في قومه", "نادى فيهم افتخاراً وتبجّحاً بما عنده."], ["وهذه الأنهار تجري من تحتي", "أنهار النيل تجري من تحت قصوري."], ["أفلا تبصرون", "عظمتي وما أنا عليه من الجلال والكمال."], ["أم أنا خير", "من موسى الذي هو مهين ولا يكاد يُفصح للُثغة في لسانه."], ["فلولا أُلقي عليه أسورة من ذهب", "هلّا أُلقي عليه أسورة من ذهب من قِبل الذي أرسله."], ["أو جاء معه الملائكة مقترنين", "يتبع بعضها بعضاً تشهد له بالرسالة."], ["فاستخفّ قومه", "استفزّهم بما حرّكهم به فخفّوا لطاعته."], ["إنهم كانوا قوماً فاسقين", "أطاعوه لكونهم قوماً فاسقين، ففسقهم علة طاعتهم."], ["فلما آسفونا انتقمنا منهم", "فلما أغضبونا انتقمنا منهم."], ["فجعلناهم سلفاً", "سابقين ليكونوا عبرة لمن بعدهم."], ["ومثلاً للآخرين", "يتمثّلون بحالهم فلا يُقدمون على مثل فعلهم."]], "m": "ما زال السياق في قصة موسى مع فرعون: ونادى فرعون في قومه افتخاراً وتطاولاً وإرهاباً للناس: يا قوم أليس لي ملك مصر، وهذه أنهار النيل تجري من تحت قصوري، أفلا تبصرون؟ فإذا أبصرتم فقولوا: أنا خير من هذا الذي هو حقير يتولّى الخدمة بنفسه، ولا يكاد يُفصح بلسانه لعلة به وهي اللثغة. فهلّا ألقى عليه من أرسله أسورة من ذهب، أو بعث معه الملائكة مقترنين يشهدون له بالرسالة. فاستفزّ قومه بقوله هذا فأطاعوه، إنهم كانوا قوماً فاسقين، والفاسق جبان خوّاف يستجيب بسرعة للباطل إن كان ممن يُخاف عادة كالحاكم الظالم. فلما أغضبونا بنكثهم وكفرهم وكبريائهم وظلمهم انتقمنا منهم فأغرقناهم أجمعين فلم نبق منهم أحداً، فجعلنا فرعون ومن أغرقنا معه من ملئه وجيوشه سابقين ليكونوا عبرة لمن بعدهم، ومثلاً يتمثّل به من بعدهم فلا يُقدمون على ما أقدموا عليه من الكفر والظلم والفساد، وأولى من يعتبر بهذا قريش التي نزل القرآن ليحرّك كامن نفسها لتنتبه من غفلتها فتؤمن فتنجو.", "h": ["ذمّ الفخر والمباهاة، إذ هما من صفات المتكبرين والظالمين.", "الاحتقار للفقراء والازدراء بهم من صفات الجبارين الظلمة المتكبرين.", "الفسق يجعل صاحبه مطية لكل ظالم، أداة يسخّره كما يشاء.", "التحذير من غضب الرب تبارك وتعالى، فإنه متى غضب انتقم فبطش."], "k": "«فاستخفّ قومه فأطاعوه»… من يستخفّني اليوم بكلامه فأتبعه بلا تفكير؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (363, 43, 57, 66, 'سورة الزخرف ٥٧ – ٦٦', 'الزخرف: وإنه لعلمٌ للساعة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 363) = $j$[{"lbl": "الآيات ٥٧ – ٦٢", "q": "۞وَلَمَّا ضُرِبَ ٱبۡنُ مَرۡيَمَ مَثَلًا إِذَا قَوۡمُكَ مِنۡهُ يَصِدُّونَ ﴿٥٧﴾ وَقَالُوٓاْ ءَأَٰلِهَتُنَا خَيۡرٌ أَمۡ هُوَۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلَۢاۚ بَلۡ هُمۡ قَوۡمٌ خَصِمُونَ ﴿٥٨﴾ إِنۡ هُوَ إِلَّا عَبۡدٌ أَنۡعَمۡنَا عَلَيۡهِ وَجَعَلۡنَٰهُ مَثَلٗا لِّبَنِيٓ إِسۡرَـٰٓءِيلَ ﴿٥٩﴾ وَلَوۡ نَشَآءُ لَجَعَلۡنَا مِنكُم مَّلَـٰٓئِكَةٗ فِي ٱلۡأَرۡضِ يَخۡلُفُونَ ﴿٦٠﴾ وَإِنَّهُۥ لَعِلۡمٞ لِّلسَّاعَةِ فَلَا تَمۡتَرُنَّ بِهَا وَٱتَّبِعُونِۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ﴿٦١﴾ وَلَا يَصُدَّنَّكُمُ ٱلشَّيۡطَٰنُۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ ﴿٦٢﴾", "w": [["ولما ضُرب ابن مريم مثلاً", "ولما جُعل عيسى بن مريم مثلاً، والضارب ابن الزِّبَعرى."], ["إذا قومك منه يَصِدّون", "إذا المشركون من قومك يضحكون فرحاً بما سمعوا."], ["أآلهتنا خير أم هو", "آلهتنا التي نعبدها خير أم عيسى بن مريم، فنرضى أن تكون آلهتنا معه."], ["ما ضربوه لك إلا جدلاً", "ما جعلوه مثلاً إلا خصومة بالباطل، لعلمهم أن «ما» لغير العاقل فلا يتناول اللفظ عيسى ﵇."], ["بل هم قوم خصمون", "شديدو الخصومة."], ["إن هو إلا عبد أنعمنا عليه", "ما عيسى إلا عبد أنعمنا عليه بالنبوة."], ["وجعلناه مثلاً لبني إسرائيل", "لوجوده من غير أب، كان مثلاً لغرابته يُستدلّ به على قدرة الله."], ["ولو نشاء لجعلنا منكم ملائكة", "لو نشاء لأهلكناكم وجعلنا بدلكم ملائكة."], ["في الأرض يخلفون", "يعمرون الأرض ويعبدون الله فيها يخلفونكم."], ["وإنه لعلمٌ للساعة", "وإن عيسى ﵇ لعلامة للساعة، تُعلم بنزوله."], ["فلا تمترُنّ بها", "لا تشكّنّ في إتيانها ولا في قربها."], ["واتبعون هذا صراط مستقيم", "وقل لهم: اتبعوني على التوحيد، هذا صراط مستقيم هو الإسلام."], ["ولا يصدّنّكم الشيطان", "لا يصرفنّكم عن الإسلام."], ["إنه لكم عدو مبين", "بيّن العداوة فلا تتبعوه."]], "m": "روي أنه لما نزلت آية الأنبياء: إنكم وما تعبدون من دون الله حصب جهنم، قال ابن الزبعرى لرسول الله ﷺ: أهذا لنا ولآلهتنا أم لجميع الأمم؟ فقال: «هو لكم ولآلهتكم ولجميع الأمم»، فقال: خصمتك ورب الكعبة، أليست النصارى يعبدون المسيح، واليهود يعبدون العزير، وبنو مليح يعبدون الملائكة؟ فإن كان هؤلاء في النار فقد رضينا أن نكون نحن وآلهتنا معهم؛ ففرح بها المشركون وضجّوا بالضحك. فنزلت: ولما جُعل عيسى بن مريم مثلاً مشابهاً للأصنام من حيث إن النصارى اتخذوه إلهاً، إذا قومك منه يضحكون، وقالوا: آلهتنا خير أم المسيح؟ قال تعالى: ما ضرب لك ابن الزبعرى هذا المثل طلباً للحق، وإنما للجدل والخصومة، بل هم قوم مجبولون على الجدل. ما عيسى إلا عبد أنعمنا عليه بالنبوة، وجعلناه مثلاً لبني إسرائيل يستدلّون به على قدرة الله إذ خلقه من غير أب كما خلق آدم من تراب. ولو نشاء لأهلكناكم يا بني آدم وجعلنا بدلكم في الأرض ملائكة يعمرونها ويعبدون الله فيها ويوحّدونه. وإن نزول عيسى في آخر الزمان علامة على قرب الساعة، فلا تشكّنّ في إتيانها فإنها آتية قريبة. وقل لهم يا رسولنا: اتبعوني على التوحيد وما جئتكم به من الهدى، هذا صراط مستقيم هو الإسلام، ولا يصدّنكم الشيطان بوساوسه، إنه لكم عدو بيّن العداوة، وأدلّ دليل على عداوته أنه أخرج آدم بإغوائه من الجنة حسداً له، فمثل هذا العدو لا يصح أبداً الاستماع إليه واتباع خطواته.", "h": ["بيان أن قريشاً أوتيت الجدل والقوة في الخصومة.", "ذمّ الجدل لغير إحقاق حق أو إبطال باطل.", "شرف عيسى ﵇ وعلوّ مكانته، وأن نزوله إلى الأرض علامة كبرى من علامات قرب الساعة.", "تقرير البعث والجزاء.", "حرمة اتباع الشيطان لأنه يُضل ولا يهدي."], "k": "«ما ضربوه لك إلا جدلاً»… حين أجادل، هل أطلب الحق أم الغلبة؟"}, {"lbl": "الآيات ٦٣ – ٦٦", "q": "وَلَمَّا جَآءَ عِيسَىٰ بِٱلۡبَيِّنَٰتِ قَالَ قَدۡ جِئۡتُكُم بِٱلۡحِكۡمَةِ وَلِأُبَيِّنَ لَكُم بَعۡضَ ٱلَّذِي تَخۡتَلِفُونَ فِيهِۖ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿٦٣﴾ إِنَّ ٱللَّهَ هُوَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ﴿٦٤﴾ فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَيۡنِهِمۡۖ فَوَيۡلٞ لِّلَّذِينَ ظَلَمُواْ مِنۡ عَذَابِ يَوۡمٍ أَلِيمٍ ﴿٦٥﴾ هَلۡ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأۡتِيَهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ ﴿٦٦﴾", "w": [["ولما جاء عيسى بالبيّنات", "ولما جاء عيسى بن مريم إلى بني إسرائيل بالمعجزات."], ["قد جئتكم بالحكمة", "قد جئتكم بالنبوة وشرائع الإنجيل."], ["ولأبيّن لكم بعض الذي تختلفون فيه", "ما اختلفتم فيه من أحكام التوراة من أمر الدين وغيره."], ["فاتقوا الله وأطيعون", "خافوا الله وأطيعوني فيما أبلّغكم عن الله من الأمر والنهي."], ["إن الله هو ربي وربكم فاعبدوه", "إلهي وإلهكم، فاعبدوه بحبه وتعظيمه والذلة له."], ["هذا صراط مستقيم", "تقوى الله وطاعة الرسول وعبادة الله بما شرع هو الإسلام."], ["فاختلف الأحزاب من بينهم", "في شأن عيسى: أهو الله، أو ابن الله، أو ثالث ثلاثة."], ["فويل للذين ظلموا من عذاب يوم أليم", "فويل للذين كفروا بما قالوا في عيسى من الكذب والباطل."], ["هل ينظرون إلا الساعة", "ما ينتظر هؤلاء الأحزاب مع إصرارهم إلا الساعة أن تأتيهم فجأة وهم لا يشعرون."]], "m": "بعد ذكر جدل المشركين وفرحهم بالباطل الذي قاله ابن الزبعرى من أن الملائكة والعزير وعيسى في النار مع من عبدوهم، برّأهم تعالى لأنهم ما أمروا الناس بعبادتهم، وإنما أمر بها الشيطان، فالشيطان ومن عبدوه هم الذين في النار. ثم ذكر رسالة عيسى ﵇ إلى بني إسرائيل موعظةً لكفار مكة: ولما جاء عيسى بني إسرائيل بالإنجيل والمعجزات كإحياء الموتى وإبراء الأكمه والأبرص، قال: قد جئتكم بالنبوة من عند الله، ولأبيّن لكم بعض الذي تختلفون فيه من أحكام التوراة، فاتقوا الله وخافوا عقابه، وأطيعوني فيما أبلّغكم، إن الله إلهي وإلهكم فاعبدوه بفعل محابّه وترك مساخطه حباً فيه وتعظيماً له، هذا الطريق المستقيم المفضي إلى سعادة الدارين. فاختلف الأحزاب من بني إسرائيل: فقالت طائفة من اليهود فيه وفي أمه البهتان وقالوا ساحر، وقال النصارى: هو الله، أو ابن الله، أو ثالث ثلاثة. فويل للذين ظلموا من عذاب يوم أليم، والويل وادٍ يسيل في جهنم بما يتجمّع من صديد أهل النار. ما ينتظرون، وقد أصرّوا، اليهود يصفونه بأخسّ الصفات والنصارى يصفونه بالألوهية التي هي حق الله، إلا الساعة أن تأتيهم فجأة وهم لا يشعرون، لأنهم مشغولون بالذرة والهيدروجين والاستعمار والتجارة والانغماس في الشهوات كما هو مشاهد اليوم.", "h": ["بيان رسالة عيسى ﵇ إلى بني إسرائيل.", "وجوب التقوى لله وطاعة الرسول وتوحيد الله في عبادته.", "بيان شؤم الخلاف وما يجرّه من التوغّل في الكفر والفساد.", "وعيد الله لليهود والنصارى الذين لم يدخلوا في الإسلام بالويل، وهو عذاب يوم أليم."], "k": "«إن الله هو ربي وربكم فاعبدوه هذا صراط مستقيم»… دعوة كل الأنبياء واحدة؛ فهل أعيشها بوضوح كما قالوها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 363;
insert into public.tdb_cards(topic, i, body) select 363, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٧ – ٦٢", "q": "۞وَلَمَّا ضُرِبَ ٱبۡنُ مَرۡيَمَ مَثَلًا إِذَا قَوۡمُكَ مِنۡهُ يَصِدُّونَ ﴿٥٧﴾ وَقَالُوٓاْ ءَأَٰلِهَتُنَا خَيۡرٌ أَمۡ هُوَۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلَۢاۚ بَلۡ هُمۡ قَوۡمٌ خَصِمُونَ ﴿٥٨﴾ إِنۡ هُوَ إِلَّا عَبۡدٌ أَنۡعَمۡنَا عَلَيۡهِ وَجَعَلۡنَٰهُ مَثَلٗا لِّبَنِيٓ إِسۡرَـٰٓءِيلَ ﴿٥٩﴾ وَلَوۡ نَشَآءُ لَجَعَلۡنَا مِنكُم مَّلَـٰٓئِكَةٗ فِي ٱلۡأَرۡضِ يَخۡلُفُونَ ﴿٦٠﴾ وَإِنَّهُۥ لَعِلۡمٞ لِّلسَّاعَةِ فَلَا تَمۡتَرُنَّ بِهَا وَٱتَّبِعُونِۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ﴿٦١﴾ وَلَا يَصُدَّنَّكُمُ ٱلشَّيۡطَٰنُۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ ﴿٦٢﴾", "w": [["ولما ضُرب ابن مريم مثلاً", "ولما جُعل عيسى بن مريم مثلاً، والضارب ابن الزِّبَعرى."], ["إذا قومك منه يَصِدّون", "إذا المشركون من قومك يضحكون فرحاً بما سمعوا."], ["أآلهتنا خير أم هو", "آلهتنا التي نعبدها خير أم عيسى بن مريم، فنرضى أن تكون آلهتنا معه."], ["ما ضربوه لك إلا جدلاً", "ما جعلوه مثلاً إلا خصومة بالباطل، لعلمهم أن «ما» لغير العاقل فلا يتناول اللفظ عيسى ﵇."], ["بل هم قوم خصمون", "شديدو الخصومة."], ["إن هو إلا عبد أنعمنا عليه", "ما عيسى إلا عبد أنعمنا عليه بالنبوة."], ["وجعلناه مثلاً لبني إسرائيل", "لوجوده من غير أب، كان مثلاً لغرابته يُستدلّ به على قدرة الله."], ["ولو نشاء لجعلنا منكم ملائكة", "لو نشاء لأهلكناكم وجعلنا بدلكم ملائكة."], ["في الأرض يخلفون", "يعمرون الأرض ويعبدون الله فيها يخلفونكم."], ["وإنه لعلمٌ للساعة", "وإن عيسى ﵇ لعلامة للساعة، تُعلم بنزوله."], ["فلا تمترُنّ بها", "لا تشكّنّ في إتيانها ولا في قربها."], ["واتبعون هذا صراط مستقيم", "وقل لهم: اتبعوني على التوحيد، هذا صراط مستقيم هو الإسلام."], ["ولا يصدّنّكم الشيطان", "لا يصرفنّكم عن الإسلام."], ["إنه لكم عدو مبين", "بيّن العداوة فلا تتبعوه."]], "m": "روي أنه لما نزلت آية الأنبياء: إنكم وما تعبدون من دون الله حصب جهنم، قال ابن الزبعرى لرسول الله ﷺ: أهذا لنا ولآلهتنا أم لجميع الأمم؟ فقال: «هو لكم ولآلهتكم ولجميع الأمم»، فقال: خصمتك ورب الكعبة، أليست النصارى يعبدون المسيح، واليهود يعبدون العزير، وبنو مليح يعبدون الملائكة؟ فإن كان هؤلاء في النار فقد رضينا أن نكون نحن وآلهتنا معهم؛ ففرح بها المشركون وضجّوا بالضحك. فنزلت: ولما جُعل عيسى بن مريم مثلاً مشابهاً للأصنام من حيث إن النصارى اتخذوه إلهاً، إذا قومك منه يضحكون، وقالوا: آلهتنا خير أم المسيح؟ قال تعالى: ما ضرب لك ابن الزبعرى هذا المثل طلباً للحق، وإنما للجدل والخصومة، بل هم قوم مجبولون على الجدل. ما عيسى إلا عبد أنعمنا عليه بالنبوة، وجعلناه مثلاً لبني إسرائيل يستدلّون به على قدرة الله إذ خلقه من غير أب كما خلق آدم من تراب. ولو نشاء لأهلكناكم يا بني آدم وجعلنا بدلكم في الأرض ملائكة يعمرونها ويعبدون الله فيها ويوحّدونه. وإن نزول عيسى في آخر الزمان علامة على قرب الساعة، فلا تشكّنّ في إتيانها فإنها آتية قريبة. وقل لهم يا رسولنا: اتبعوني على التوحيد وما جئتكم به من الهدى، هذا صراط مستقيم هو الإسلام، ولا يصدّنكم الشيطان بوساوسه، إنه لكم عدو بيّن العداوة، وأدلّ دليل على عداوته أنه أخرج آدم بإغوائه من الجنة حسداً له، فمثل هذا العدو لا يصح أبداً الاستماع إليه واتباع خطواته.", "h": ["بيان أن قريشاً أوتيت الجدل والقوة في الخصومة.", "ذمّ الجدل لغير إحقاق حق أو إبطال باطل.", "شرف عيسى ﵇ وعلوّ مكانته، وأن نزوله إلى الأرض علامة كبرى من علامات قرب الساعة.", "تقرير البعث والجزاء.", "حرمة اتباع الشيطان لأنه يُضل ولا يهدي."], "k": "«ما ضربوه لك إلا جدلاً»… حين أجادل، هل أطلب الحق أم الغلبة؟"}, {"lbl": "الآيات ٦٣ – ٦٦", "q": "وَلَمَّا جَآءَ عِيسَىٰ بِٱلۡبَيِّنَٰتِ قَالَ قَدۡ جِئۡتُكُم بِٱلۡحِكۡمَةِ وَلِأُبَيِّنَ لَكُم بَعۡضَ ٱلَّذِي تَخۡتَلِفُونَ فِيهِۖ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿٦٣﴾ إِنَّ ٱللَّهَ هُوَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ﴿٦٤﴾ فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَيۡنِهِمۡۖ فَوَيۡلٞ لِّلَّذِينَ ظَلَمُواْ مِنۡ عَذَابِ يَوۡمٍ أَلِيمٍ ﴿٦٥﴾ هَلۡ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأۡتِيَهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ ﴿٦٦﴾", "w": [["ولما جاء عيسى بالبيّنات", "ولما جاء عيسى بن مريم إلى بني إسرائيل بالمعجزات."], ["قد جئتكم بالحكمة", "قد جئتكم بالنبوة وشرائع الإنجيل."], ["ولأبيّن لكم بعض الذي تختلفون فيه", "ما اختلفتم فيه من أحكام التوراة من أمر الدين وغيره."], ["فاتقوا الله وأطيعون", "خافوا الله وأطيعوني فيما أبلّغكم عن الله من الأمر والنهي."], ["إن الله هو ربي وربكم فاعبدوه", "إلهي وإلهكم، فاعبدوه بحبه وتعظيمه والذلة له."], ["هذا صراط مستقيم", "تقوى الله وطاعة الرسول وعبادة الله بما شرع هو الإسلام."], ["فاختلف الأحزاب من بينهم", "في شأن عيسى: أهو الله، أو ابن الله، أو ثالث ثلاثة."], ["فويل للذين ظلموا من عذاب يوم أليم", "فويل للذين كفروا بما قالوا في عيسى من الكذب والباطل."], ["هل ينظرون إلا الساعة", "ما ينتظر هؤلاء الأحزاب مع إصرارهم إلا الساعة أن تأتيهم فجأة وهم لا يشعرون."]], "m": "بعد ذكر جدل المشركين وفرحهم بالباطل الذي قاله ابن الزبعرى من أن الملائكة والعزير وعيسى في النار مع من عبدوهم، برّأهم تعالى لأنهم ما أمروا الناس بعبادتهم، وإنما أمر بها الشيطان، فالشيطان ومن عبدوه هم الذين في النار. ثم ذكر رسالة عيسى ﵇ إلى بني إسرائيل موعظةً لكفار مكة: ولما جاء عيسى بني إسرائيل بالإنجيل والمعجزات كإحياء الموتى وإبراء الأكمه والأبرص، قال: قد جئتكم بالنبوة من عند الله، ولأبيّن لكم بعض الذي تختلفون فيه من أحكام التوراة، فاتقوا الله وخافوا عقابه، وأطيعوني فيما أبلّغكم، إن الله إلهي وإلهكم فاعبدوه بفعل محابّه وترك مساخطه حباً فيه وتعظيماً له، هذا الطريق المستقيم المفضي إلى سعادة الدارين. فاختلف الأحزاب من بني إسرائيل: فقالت طائفة من اليهود فيه وفي أمه البهتان وقالوا ساحر، وقال النصارى: هو الله، أو ابن الله، أو ثالث ثلاثة. فويل للذين ظلموا من عذاب يوم أليم، والويل وادٍ يسيل في جهنم بما يتجمّع من صديد أهل النار. ما ينتظرون، وقد أصرّوا، اليهود يصفونه بأخسّ الصفات والنصارى يصفونه بالألوهية التي هي حق الله، إلا الساعة أن تأتيهم فجأة وهم لا يشعرون، لأنهم مشغولون بالذرة والهيدروجين والاستعمار والتجارة والانغماس في الشهوات كما هو مشاهد اليوم.", "h": ["بيان رسالة عيسى ﵇ إلى بني إسرائيل.", "وجوب التقوى لله وطاعة الرسول وتوحيد الله في عبادته.", "بيان شؤم الخلاف وما يجرّه من التوغّل في الكفر والفساد.", "وعيد الله لليهود والنصارى الذين لم يدخلوا في الإسلام بالويل، وهو عذاب يوم أليم."], "k": "«إن الله هو ربي وربكم فاعبدوه هذا صراط مستقيم»… دعوة كل الأنبياء واحدة؛ فهل أعيشها بوضوح كما قالوها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (364, 43, 67, 80, 'سورة الزخرف ٦٧ – ٨٠', 'الزخرف: الأخلّاء يومئذ بعضهم لبعض عدو إلا المتقين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 364) = $j$[{"lbl": "الآيات ٦٧ – ٧٣", "q": "ٱلۡأَخِلَّآءُ يَوۡمَئِذِۭ بَعۡضُهُمۡ لِبَعۡضٍ عَدُوٌّ إِلَّا ٱلۡمُتَّقِينَ ﴿٦٧﴾ يَٰعِبَادِ لَا خَوۡفٌ عَلَيۡكُمُ ٱلۡيَوۡمَ وَلَآ أَنتُمۡ تَحۡزَنُونَ ﴿٦٨﴾ ٱلَّذِينَ ءَامَنُواْ بِـَٔايَٰتِنَا وَكَانُواْ مُسۡلِمِينَ ﴿٦٩﴾ ٱدۡخُلُواْ ٱلۡجَنَّةَ أَنتُمۡ وَأَزۡوَٰجُكُمۡ تُحۡبَرُونَ ﴿٧٠﴾ يُطَافُ عَلَيۡهِم بِصِحَافٖ مِّن ذَهَبٖ وَأَكۡوَابٖۖ وَفِيهَا مَا تَشۡتَهِيهِ ٱلۡأَنفُسُ وَتَلَذُّ ٱلۡأَعۡيُنُۖ وَأَنتُمۡ فِيهَا خَٰلِدُونَ ﴿٧١﴾ وَتِلۡكَ ٱلۡجَنَّةُ ٱلَّتِيٓ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٧٢﴾ لَكُمۡ فِيهَا فَٰكِهَةٞ كَثِيرَةٞ مِّنۡهَا تَأۡكُلُونَ ﴿٧٣﴾", "w": [["الأخلّاء يومئذ بعضهم لبعض عدو", "الأحباء يوم تأتيهم الساعة بغتة بعضهم لبعض عدو."], ["إلا المتقين", "فإن محبتهم تدوم لهم لأنها كانت في الله وطاعته."], ["يا عباد لا خوف عليكم ولا أنتم تحزنون", "يُنادَون فيقال لهم ذلك."], ["تُحبَرون", "تُسرّون وتُكرمون."], ["بصحاف من ذهب", "بقصاع من ذهب فيها الطعام."], ["وأكواب", "من ذهب فيها الشراب اللذيذ."], ["وفيها ما تشتهيه الأنفس وتلذّ الأعين", "في الجنة ما تشتهيه الأنفس تلذذاً به وتلذّه الأعين نظراً."], ["وتلك الجنة التي أُورثتموها بما كنتم تعملون", "أورثكموها الله بأعمالكم الصالحة التي هي ثمرة إيمانكم الصادق وإخلاصكم الكامل."]], "m": "ما زال السياق في ذكر أحداث الساعة: الأخلّاء، أي الأحباء في الدنيا، يوم تأتي الساعة بعضهم لبعض عدو، فتنقطع تلك الخلّة وتصبح عداءً لأنها كانت على معصية الله، إلا المتقين الله بفعل أوامره وترك نواهيه، فإن مودتهم لا تنقطع لأنها كانت محبة في الله، وما كان لله دام واتصل، وما كان لغير الله انقطع وانفصل. يناديهم ربهم: يا عبادي لا خوف عليكم اليوم ولا أنتم تحزنون، الذين آمنوا بآياتنا وكانوا منقادين لله ظاهراً وباطناً، ادخلوا الجنة أنتم وزوجاتكم المؤمنات تُسرّون وتُكرمون. يُطاف عليهم بقصاع من ذهب فيها ألذّ الطعام وأشهاه، وأكواب من ذهب فيها ألذّ الشراب، والكوب إناء لا عروة له ولا خرطوم يُشرب منه من أي جهة، وفيها ما تشتهيه الأنفس من سائر المستلذّات وتلذّ الأعين من سائر المرئيات، وأنتم فيها خالدون. وهذه هي الجنة التي أُورثتموها بسبب أعمالكم الصالحة التي زكّت نفوسكم؛ ووجه الوراثة أن الله خلق لكل إنسان منزلين: أحدهما في الجنة والآخر في النار، فكل من دخل الجنة ورث منزل من دخل النار. لكم فيها فاكهة كثيرة منها تأكلون، يقال لهم هذا إكراماً لهم وإسعاداً.", "h": ["كل خلّة يوم القيامة تنقطع إلا خلّة كانت في الله ولله سبحانه، ولذا ينبغي أن تكون المودة في الدنيا لله لا لغيره.", "بيان فضل التقوى وشرف المتقين الذين يتقون الشرك والمعاصي.", "بيان أن الرجل يجمع الله بينه وبين زوجته المسلمة في الجنة.", "بيان نعيم أهل الجنة من طعام وشراب وسائر المستلذّات.", "الإيمان والعمل الصالح سبب في دخول الجنة."], "k": "«الأخلّاء يومئذ بعضهم لبعض عدو إلا المتقين»… أي صحبة لي اليوم ستبقى صداقة يوم القيامة؟"}, {"lbl": "الآيات ٧٤ – ٨٠", "q": "إِنَّ ٱلۡمُجۡرِمِينَ فِي عَذَابِ جَهَنَّمَ خَٰلِدُونَ ﴿٧٤﴾ لَا يُفَتَّرُ عَنۡهُمۡ وَهُمۡ فِيهِ مُبۡلِسُونَ ﴿٧٥﴾ وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن كَانُواْ هُمُ ٱلظَّـٰلِمِينَ ﴿٧٦﴾ وَنَادَوۡاْ يَٰمَٰلِكُ لِيَقۡضِ عَلَيۡنَا رَبُّكَۖ قَالَ إِنَّكُم مَّـٰكِثُونَ ﴿٧٧﴾ لَقَدۡ جِئۡنَٰكُم بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَكُمۡ لِلۡحَقِّ كَٰرِهُونَ ﴿٧٨﴾ أَمۡ أَبۡرَمُوٓاْ أَمۡرٗا فَإِنَّا مُبۡرِمُونَ ﴿٧٩﴾ أَمۡ يَحۡسَبُونَ أَنَّا لَا نَسۡمَعُ سِرَّهُمۡ وَنَجۡوَىٰهُمۚ بَلَىٰ وَرُسُلُنَا لَدَيۡهِمۡ يَكۡتُبُونَ ﴿٨٠﴾", "w": [["إن المجرمين في عذاب جهنم خالدون", "الذين أجرموا على أنفسهم بالشرك والمعاصي في جهنم خالدون لا يخرجون ولا يموتون."], ["لا يُفتّر عنهم وهم فيه مبلسون", "لا يُخفّف عنهم العذاب، وهم فيه ساكتون سكوت يأس."], ["ونادَوا يا مالك ليقضِ علينا ربك", "نادوا مالكاً خازن النار: ليُمتنا ربك."], ["قال إنكم ماكثون", "أجابهم بعد ألف سنة مضت على دعوتهم: إنكم مقيمون في عذاب جهنم دائماً."], ["لقد جئناكم بالحق ولكن أكثركم للحق كارهون", "علة بقائكم أنا جئناكم بالحق على لسان رسولنا، والحق التوحيد وعبادة الله بما شرع، فكرهه أكثركم."], ["أم أبرموا أمراً فإنا مبرمون", "أحكموا الكيد للنبي محمد ﷺ؟ فإنا محكِمون كيدنا في هلاكهم."], ["ورسلنا لديهم يكتبون", "وملائكتنا الحفظة يكتبون ما يُسرّون وما يُعلنون."]], "m": "لما ذكر الجنة ونعيمها ذكر النار وعذابها، وهذا هو الترغيب والترهيب الذي امتاز به أسلوب القرآن: إن الذين أجرموا على أنفسهم فأفسدوها بالشرك والمعاصي في عذاب جهنم خالدون، لا يُخفّف عنهم، وهم فيه ساكتون آيسون قانطون، وما ظلمناهم بتعذيبهم ولكن كانوا هم الظالمين حيث دسّوا أنفسهم بالشرك والمعاصي. ونادى أصحاب ذلك العذاب الدائم مالكاً خازن النار: ليُمتنا ربك فنستريح، فأجابهم بعد ألف سنة: إنكم ماكثون في عذاب جهنم أبداً، لقد جئناكم بالحق، أرسلنا إليكم رسولنا يدعوكم إلى الإيمان والعمل الصالح المزكّي للنفوس، فكره أكثركم ذلك مؤثرين شهوات الدنيا على الآخرة، فمتّم على الشرك، فهذا جزاء الكافرين. بل أأحكم هؤلاء المشركون أمراً يكيدون فيه للرسول ودعوته؟ فإنا محكمون أمراً مضاداً لهم بتعذيبهم وإبطال كيدهم. أم يحسبون أنا لا نسمع سرّهم ونجواهم؟ بلى نسمع، وملائكتنا الحفظة لديهم يكتبون ما يقولون سراً وجهراً. روي أن ثلاثة نفر قالوا تحت أستار الكعبة: أترون أن الله يسمع كلامنا؟ فقال أحدهم: إذا جهرتم سمع وإذا أسررتم لم يسمع، وقال الآخر: إن كان يسمع إذا أعلنتم فإنه يسمع إذا أسررتم، فنزلت الآية.", "h": ["بيان عقوبة الإجرام على النفس بالشرك والمعاصي.", "عذاب الآخرة لا يُطاق ولا يُقدر قدره، يدل عليه طلبهم الموت ليستريحوا منه وما هم بميتين.", "أكبر عامل من عوامل كراهية الحق حب الدنيا والشهوات البهيمية في الأكل والشرب والنكاح، هذه التي تُكرّه إلى صاحبها الدين وشرائعه التي تقيّد من الإسراف في ذلك."], "k": "«ولكن أكثركم للحق كارهون»… هل في قلبي كراهة لحكمٍ ما لأنه يقيّد شهوتي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 364;
insert into public.tdb_cards(topic, i, body) select 364, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٧ – ٧٣", "q": "ٱلۡأَخِلَّآءُ يَوۡمَئِذِۭ بَعۡضُهُمۡ لِبَعۡضٍ عَدُوٌّ إِلَّا ٱلۡمُتَّقِينَ ﴿٦٧﴾ يَٰعِبَادِ لَا خَوۡفٌ عَلَيۡكُمُ ٱلۡيَوۡمَ وَلَآ أَنتُمۡ تَحۡزَنُونَ ﴿٦٨﴾ ٱلَّذِينَ ءَامَنُواْ بِـَٔايَٰتِنَا وَكَانُواْ مُسۡلِمِينَ ﴿٦٩﴾ ٱدۡخُلُواْ ٱلۡجَنَّةَ أَنتُمۡ وَأَزۡوَٰجُكُمۡ تُحۡبَرُونَ ﴿٧٠﴾ يُطَافُ عَلَيۡهِم بِصِحَافٖ مِّن ذَهَبٖ وَأَكۡوَابٖۖ وَفِيهَا مَا تَشۡتَهِيهِ ٱلۡأَنفُسُ وَتَلَذُّ ٱلۡأَعۡيُنُۖ وَأَنتُمۡ فِيهَا خَٰلِدُونَ ﴿٧١﴾ وَتِلۡكَ ٱلۡجَنَّةُ ٱلَّتِيٓ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٧٢﴾ لَكُمۡ فِيهَا فَٰكِهَةٞ كَثِيرَةٞ مِّنۡهَا تَأۡكُلُونَ ﴿٧٣﴾", "w": [["الأخلّاء يومئذ بعضهم لبعض عدو", "الأحباء يوم تأتيهم الساعة بغتة بعضهم لبعض عدو."], ["إلا المتقين", "فإن محبتهم تدوم لهم لأنها كانت في الله وطاعته."], ["يا عباد لا خوف عليكم ولا أنتم تحزنون", "يُنادَون فيقال لهم ذلك."], ["تُحبَرون", "تُسرّون وتُكرمون."], ["بصحاف من ذهب", "بقصاع من ذهب فيها الطعام."], ["وأكواب", "من ذهب فيها الشراب اللذيذ."], ["وفيها ما تشتهيه الأنفس وتلذّ الأعين", "في الجنة ما تشتهيه الأنفس تلذذاً به وتلذّه الأعين نظراً."], ["وتلك الجنة التي أُورثتموها بما كنتم تعملون", "أورثكموها الله بأعمالكم الصالحة التي هي ثمرة إيمانكم الصادق وإخلاصكم الكامل."]], "m": "ما زال السياق في ذكر أحداث الساعة: الأخلّاء، أي الأحباء في الدنيا، يوم تأتي الساعة بعضهم لبعض عدو، فتنقطع تلك الخلّة وتصبح عداءً لأنها كانت على معصية الله، إلا المتقين الله بفعل أوامره وترك نواهيه، فإن مودتهم لا تنقطع لأنها كانت محبة في الله، وما كان لله دام واتصل، وما كان لغير الله انقطع وانفصل. يناديهم ربهم: يا عبادي لا خوف عليكم اليوم ولا أنتم تحزنون، الذين آمنوا بآياتنا وكانوا منقادين لله ظاهراً وباطناً، ادخلوا الجنة أنتم وزوجاتكم المؤمنات تُسرّون وتُكرمون. يُطاف عليهم بقصاع من ذهب فيها ألذّ الطعام وأشهاه، وأكواب من ذهب فيها ألذّ الشراب، والكوب إناء لا عروة له ولا خرطوم يُشرب منه من أي جهة، وفيها ما تشتهيه الأنفس من سائر المستلذّات وتلذّ الأعين من سائر المرئيات، وأنتم فيها خالدون. وهذه هي الجنة التي أُورثتموها بسبب أعمالكم الصالحة التي زكّت نفوسكم؛ ووجه الوراثة أن الله خلق لكل إنسان منزلين: أحدهما في الجنة والآخر في النار، فكل من دخل الجنة ورث منزل من دخل النار. لكم فيها فاكهة كثيرة منها تأكلون، يقال لهم هذا إكراماً لهم وإسعاداً.", "h": ["كل خلّة يوم القيامة تنقطع إلا خلّة كانت في الله ولله سبحانه، ولذا ينبغي أن تكون المودة في الدنيا لله لا لغيره.", "بيان فضل التقوى وشرف المتقين الذين يتقون الشرك والمعاصي.", "بيان أن الرجل يجمع الله بينه وبين زوجته المسلمة في الجنة.", "بيان نعيم أهل الجنة من طعام وشراب وسائر المستلذّات.", "الإيمان والعمل الصالح سبب في دخول الجنة."], "k": "«الأخلّاء يومئذ بعضهم لبعض عدو إلا المتقين»… أي صحبة لي اليوم ستبقى صداقة يوم القيامة؟"}, {"lbl": "الآيات ٧٤ – ٨٠", "q": "إِنَّ ٱلۡمُجۡرِمِينَ فِي عَذَابِ جَهَنَّمَ خَٰلِدُونَ ﴿٧٤﴾ لَا يُفَتَّرُ عَنۡهُمۡ وَهُمۡ فِيهِ مُبۡلِسُونَ ﴿٧٥﴾ وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن كَانُواْ هُمُ ٱلظَّـٰلِمِينَ ﴿٧٦﴾ وَنَادَوۡاْ يَٰمَٰلِكُ لِيَقۡضِ عَلَيۡنَا رَبُّكَۖ قَالَ إِنَّكُم مَّـٰكِثُونَ ﴿٧٧﴾ لَقَدۡ جِئۡنَٰكُم بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَكُمۡ لِلۡحَقِّ كَٰرِهُونَ ﴿٧٨﴾ أَمۡ أَبۡرَمُوٓاْ أَمۡرٗا فَإِنَّا مُبۡرِمُونَ ﴿٧٩﴾ أَمۡ يَحۡسَبُونَ أَنَّا لَا نَسۡمَعُ سِرَّهُمۡ وَنَجۡوَىٰهُمۚ بَلَىٰ وَرُسُلُنَا لَدَيۡهِمۡ يَكۡتُبُونَ ﴿٨٠﴾", "w": [["إن المجرمين في عذاب جهنم خالدون", "الذين أجرموا على أنفسهم بالشرك والمعاصي في جهنم خالدون لا يخرجون ولا يموتون."], ["لا يُفتّر عنهم وهم فيه مبلسون", "لا يُخفّف عنهم العذاب، وهم فيه ساكتون سكوت يأس."], ["ونادَوا يا مالك ليقضِ علينا ربك", "نادوا مالكاً خازن النار: ليُمتنا ربك."], ["قال إنكم ماكثون", "أجابهم بعد ألف سنة مضت على دعوتهم: إنكم مقيمون في عذاب جهنم دائماً."], ["لقد جئناكم بالحق ولكن أكثركم للحق كارهون", "علة بقائكم أنا جئناكم بالحق على لسان رسولنا، والحق التوحيد وعبادة الله بما شرع، فكرهه أكثركم."], ["أم أبرموا أمراً فإنا مبرمون", "أحكموا الكيد للنبي محمد ﷺ؟ فإنا محكِمون كيدنا في هلاكهم."], ["ورسلنا لديهم يكتبون", "وملائكتنا الحفظة يكتبون ما يُسرّون وما يُعلنون."]], "m": "لما ذكر الجنة ونعيمها ذكر النار وعذابها، وهذا هو الترغيب والترهيب الذي امتاز به أسلوب القرآن: إن الذين أجرموا على أنفسهم فأفسدوها بالشرك والمعاصي في عذاب جهنم خالدون، لا يُخفّف عنهم، وهم فيه ساكتون آيسون قانطون، وما ظلمناهم بتعذيبهم ولكن كانوا هم الظالمين حيث دسّوا أنفسهم بالشرك والمعاصي. ونادى أصحاب ذلك العذاب الدائم مالكاً خازن النار: ليُمتنا ربك فنستريح، فأجابهم بعد ألف سنة: إنكم ماكثون في عذاب جهنم أبداً، لقد جئناكم بالحق، أرسلنا إليكم رسولنا يدعوكم إلى الإيمان والعمل الصالح المزكّي للنفوس، فكره أكثركم ذلك مؤثرين شهوات الدنيا على الآخرة، فمتّم على الشرك، فهذا جزاء الكافرين. بل أأحكم هؤلاء المشركون أمراً يكيدون فيه للرسول ودعوته؟ فإنا محكمون أمراً مضاداً لهم بتعذيبهم وإبطال كيدهم. أم يحسبون أنا لا نسمع سرّهم ونجواهم؟ بلى نسمع، وملائكتنا الحفظة لديهم يكتبون ما يقولون سراً وجهراً. روي أن ثلاثة نفر قالوا تحت أستار الكعبة: أترون أن الله يسمع كلامنا؟ فقال أحدهم: إذا جهرتم سمع وإذا أسررتم لم يسمع، وقال الآخر: إن كان يسمع إذا أعلنتم فإنه يسمع إذا أسررتم، فنزلت الآية.", "h": ["بيان عقوبة الإجرام على النفس بالشرك والمعاصي.", "عذاب الآخرة لا يُطاق ولا يُقدر قدره، يدل عليه طلبهم الموت ليستريحوا منه وما هم بميتين.", "أكبر عامل من عوامل كراهية الحق حب الدنيا والشهوات البهيمية في الأكل والشرب والنكاح، هذه التي تُكرّه إلى صاحبها الدين وشرائعه التي تقيّد من الإسراف في ذلك."], "k": "«ولكن أكثركم للحق كارهون»… هل في قلبي كراهة لحكمٍ ما لأنه يقيّد شهوتي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (365, 43, 81, 89, 'سورة الزخرف ٨١ – ٨٩', 'الزخرف: وهو الذي في السماء إله وفي الأرض إله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 365) = $j$[{"lbl": "الآيات ٨١ – ٨٥", "q": "قُلۡ إِن كَانَ لِلرَّحۡمَٰنِ وَلَدٞ فَأَنَا۠ أَوَّلُ ٱلۡعَٰبِدِينَ ﴿٨١﴾ سُبۡحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ ﴿٨٢﴾ فَذَرۡهُمۡ يَخُوضُواْ وَيَلۡعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي يُوعَدُونَ ﴿٨٣﴾ وَهُوَ ٱلَّذِي فِي ٱلسَّمَآءِ إِلَٰهٞ وَفِي ٱلۡأَرۡضِ إِلَٰهٞۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡعَلِيمُ ﴿٨٤﴾ وَتَبَارَكَ ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَعِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٨٥﴾", "w": [["قل إن كان للرحمن ولد", "قل يا رسولنا للزاعمين أن الملائكة بنات الله: إن كان للرحمن ولد فرضاً."], ["فأنا أول العابدين", "فأنا أول من يعبده تعظيماً لله وإجلالاً، ولكن لا ولد له فلا عبادة لغيره."], ["سبحان رب السماوات والأرض", "تنزّه وتقدّس."], ["عما يصفون", "عما يصفون به الله من أن له ولداً وشركاء."], ["فذرهم يخوضوا ويلعبوا", "اتركهم يا رسولنا يخوضوا في باطلهم ويلعبوا في دنياهم."], ["وهو الذي في السماء إله", "معبود في السماء."], ["وفي الأرض إله", "ومعبود في الأرض."], ["وتبارك الذي له ملك السماوات والأرض", "تعاظم وجلّ جلال الذي له ملك السماوات والأرض."], ["وعنده علم الساعة", "عنده علم وقت مجيئها."]], "m": "سبق أن بكّت تعالى المشركين في دعواهم أن الملائكة بنات الله، وهنا قال لرسوله: قل لهم: إن كان للرحمن ولد كما تفترون فرضاً وتقديراً فأنا أول العابدين له، ولكن لم يكن للرحمن ولد، فلم أكن لأعبد غير الله. سبحان رب السماوات والأرض رب العرش، مالك ذلك كله، عما يصفه المشركون به من الولد والشركاء. فإذا أصرّوا على باطلهم والافتراء على الله فذرهم يخوضوا في باطلهم ويلعبوا في دنياهم حتى يلاقوا يومهم الذي يوعدون، وهو يوم القيامة. وهو الذي في السماء معبود وفي الأرض معبود، معظّم غاية التعظيم، محبوب غاية الحب، يُتذلّل له غاية الذل في الأرض والسماء، وهو الحكيم في صنعه وتدبيره، العليم بأحوال خلقه، فهل مثله يفتقر إلى زوجة وولد؟ تعالى الله عن ذلك علواً كبيراً. وتبارك الذي له ملك السماوات والأرض وما بينهما، وعنده علم الساعة، وإليه ترجعون.", "h": ["مشروعية التلطّف في الخطاب والتنزّل مع المخاطب لإقامة الحجة عليه، كقوله تعالى: «وإنا أو إياكم لعلى هدى أو في ضلال مبين»، وكما هنا: «قل إن كان للرحمن ولد» من باب الفرض والتقدير، «فأنا أول العابدين» له، ولكن لا ولد له فلا أعبد غيره سبحانه.", "تهديد المشركين بعذاب يوم القيامة.", "إقامة البراهين على بطلان نسبة الولد إلى الله تعالى."], "k": "«وهو الذي في السماء إله وفي الأرض إله»… هل له في قلبي غاية الحب وغاية الذل؟"}, {"lbl": "الآيات ٨٦ – ٨٩", "q": "وَلَا يَمۡلِكُ ٱلَّذِينَ يَدۡعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِٱلۡحَقِّ وَهُمۡ يَعۡلَمُونَ ﴿٨٦﴾ وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَهُمۡ لَيَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ يُؤۡفَكُونَ ﴿٨٧﴾ وَقِيلِهِۦ يَٰرَبِّ إِنَّ هَـٰٓؤُلَآءِ قَوۡمٞ لَّا يُؤۡمِنُونَ ﴿٨٨﴾ فَٱصۡفَحۡ عَنۡهُمۡ وَقُلۡ سَلَٰمٞۚ فَسَوۡفَ يَعۡلَمُونَ ﴿٨٩﴾", "w": [["ولا يملك الذين يدعون من دونه الشفاعة", "الذين يعبدونهم."], ["إلا من شهد بالحق وهم يعلمون", "لكن الذي شهد بالحق فوحّد الله على علم، هذا الذي تناله شفاعة الملائكة والأنبياء."], ["فأنّى يؤفكون", "كيف يُصرفون عن الحق بعد معرفته؟"], ["وقيله يا رب", "قول النبي: يا رب إن هؤلاء قوم لا يؤمنون."], ["فاصفح عنهم", "أعرض عنهم."], ["وقل سلام فسوف يعلمون", "أمري سلام منكم، فسوف تعلمون عاقبة كفركم."]], "m": "لما أعلم تعالى أن رجوع الناس إليه يوم القيامة، وكان المشركون يزعمون أن آلهتهم من الملائكة وغيرها تشفع لهم، واتخذوا هذا ذريعة لعبادتهم، أعلمهم أن من يعبدونهم من دون الله من الأصنام والملائكة وغيرهم لا يملكون الشفاعة لأحد، فالله وحده يملكها ويعطيها لمن يشاء، إلا من شهد بالحق أنه لا إله إلا الله وهو يعلم ذلك علماً يقيناً بقلبه، فهذا قد يشفع له الملائكة أو الأنبياء، فالموحّدون تنالهم الشفاعة بإذن الله. ولئن سألت هؤلاء المشركين من خلقهم ليقولُنّ الله، فسبحان الله كيف يقرّون بتوحيد الربوبية وينكرون توحيد العبادة؟ فأنّى يُصرفون عن الحق بعد معرفته؟ ويعلم تعالى قول رسوله وشكواه لما شاهد من عنادهم: يا رب إن هؤلاء قوم لا يؤمنون، فأمره أن يتجاوز عما يلقاه منهم وأن يقول لهم: سلام، وهو سلام متاركة لا سلام تحية، فسوف تعلمون عاقبة هذا الإصرار؛ تهديداً لهم بما ينتظرهم من أليم العذاب إن ماتوا على كفرهم.", "h": ["لا يملك الشفاعة يوم القيامة أحد إلا الله تعالى، فمن أذن له شفع ومن لم يأذن له لا يشفع، ولا يُشفع إلا لأهل التوحيد خاصة، أما أهل الشرك والكفر فلا شفاعة لهم.", "مشركو العرب على عهد النبوة موحّدون في الربوبية مشركون في العبادة.", "مشروعية الصفح والتجاوز عند العجز عن إقامة الحدود وإعلاء كلمة الله تعالى."], "k": "«إلا من شهد بالحق وهم يعلمون»… أقولها بلساني؛ فهل يعلمها قلبي يقيناً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 365;
insert into public.tdb_cards(topic, i, body) select 365, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨١ – ٨٥", "q": "قُلۡ إِن كَانَ لِلرَّحۡمَٰنِ وَلَدٞ فَأَنَا۠ أَوَّلُ ٱلۡعَٰبِدِينَ ﴿٨١﴾ سُبۡحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ ﴿٨٢﴾ فَذَرۡهُمۡ يَخُوضُواْ وَيَلۡعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي يُوعَدُونَ ﴿٨٣﴾ وَهُوَ ٱلَّذِي فِي ٱلسَّمَآءِ إِلَٰهٞ وَفِي ٱلۡأَرۡضِ إِلَٰهٞۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡعَلِيمُ ﴿٨٤﴾ وَتَبَارَكَ ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَعِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٨٥﴾", "w": [["قل إن كان للرحمن ولد", "قل يا رسولنا للزاعمين أن الملائكة بنات الله: إن كان للرحمن ولد فرضاً."], ["فأنا أول العابدين", "فأنا أول من يعبده تعظيماً لله وإجلالاً، ولكن لا ولد له فلا عبادة لغيره."], ["سبحان رب السماوات والأرض", "تنزّه وتقدّس."], ["عما يصفون", "عما يصفون به الله من أن له ولداً وشركاء."], ["فذرهم يخوضوا ويلعبوا", "اتركهم يا رسولنا يخوضوا في باطلهم ويلعبوا في دنياهم."], ["وهو الذي في السماء إله", "معبود في السماء."], ["وفي الأرض إله", "ومعبود في الأرض."], ["وتبارك الذي له ملك السماوات والأرض", "تعاظم وجلّ جلال الذي له ملك السماوات والأرض."], ["وعنده علم الساعة", "عنده علم وقت مجيئها."]], "m": "سبق أن بكّت تعالى المشركين في دعواهم أن الملائكة بنات الله، وهنا قال لرسوله: قل لهم: إن كان للرحمن ولد كما تفترون فرضاً وتقديراً فأنا أول العابدين له، ولكن لم يكن للرحمن ولد، فلم أكن لأعبد غير الله. سبحان رب السماوات والأرض رب العرش، مالك ذلك كله، عما يصفه المشركون به من الولد والشركاء. فإذا أصرّوا على باطلهم والافتراء على الله فذرهم يخوضوا في باطلهم ويلعبوا في دنياهم حتى يلاقوا يومهم الذي يوعدون، وهو يوم القيامة. وهو الذي في السماء معبود وفي الأرض معبود، معظّم غاية التعظيم، محبوب غاية الحب، يُتذلّل له غاية الذل في الأرض والسماء، وهو الحكيم في صنعه وتدبيره، العليم بأحوال خلقه، فهل مثله يفتقر إلى زوجة وولد؟ تعالى الله عن ذلك علواً كبيراً. وتبارك الذي له ملك السماوات والأرض وما بينهما، وعنده علم الساعة، وإليه ترجعون.", "h": ["مشروعية التلطّف في الخطاب والتنزّل مع المخاطب لإقامة الحجة عليه، كقوله تعالى: «وإنا أو إياكم لعلى هدى أو في ضلال مبين»، وكما هنا: «قل إن كان للرحمن ولد» من باب الفرض والتقدير، «فأنا أول العابدين» له، ولكن لا ولد له فلا أعبد غيره سبحانه.", "تهديد المشركين بعذاب يوم القيامة.", "إقامة البراهين على بطلان نسبة الولد إلى الله تعالى."], "k": "«وهو الذي في السماء إله وفي الأرض إله»… هل له في قلبي غاية الحب وغاية الذل؟"}, {"lbl": "الآيات ٨٦ – ٨٩", "q": "وَلَا يَمۡلِكُ ٱلَّذِينَ يَدۡعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِٱلۡحَقِّ وَهُمۡ يَعۡلَمُونَ ﴿٨٦﴾ وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَهُمۡ لَيَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ يُؤۡفَكُونَ ﴿٨٧﴾ وَقِيلِهِۦ يَٰرَبِّ إِنَّ هَـٰٓؤُلَآءِ قَوۡمٞ لَّا يُؤۡمِنُونَ ﴿٨٨﴾ فَٱصۡفَحۡ عَنۡهُمۡ وَقُلۡ سَلَٰمٞۚ فَسَوۡفَ يَعۡلَمُونَ ﴿٨٩﴾", "w": [["ولا يملك الذين يدعون من دونه الشفاعة", "الذين يعبدونهم."], ["إلا من شهد بالحق وهم يعلمون", "لكن الذي شهد بالحق فوحّد الله على علم، هذا الذي تناله شفاعة الملائكة والأنبياء."], ["فأنّى يؤفكون", "كيف يُصرفون عن الحق بعد معرفته؟"], ["وقيله يا رب", "قول النبي: يا رب إن هؤلاء قوم لا يؤمنون."], ["فاصفح عنهم", "أعرض عنهم."], ["وقل سلام فسوف يعلمون", "أمري سلام منكم، فسوف تعلمون عاقبة كفركم."]], "m": "لما أعلم تعالى أن رجوع الناس إليه يوم القيامة، وكان المشركون يزعمون أن آلهتهم من الملائكة وغيرها تشفع لهم، واتخذوا هذا ذريعة لعبادتهم، أعلمهم أن من يعبدونهم من دون الله من الأصنام والملائكة وغيرهم لا يملكون الشفاعة لأحد، فالله وحده يملكها ويعطيها لمن يشاء، إلا من شهد بالحق أنه لا إله إلا الله وهو يعلم ذلك علماً يقيناً بقلبه، فهذا قد يشفع له الملائكة أو الأنبياء، فالموحّدون تنالهم الشفاعة بإذن الله. ولئن سألت هؤلاء المشركين من خلقهم ليقولُنّ الله، فسبحان الله كيف يقرّون بتوحيد الربوبية وينكرون توحيد العبادة؟ فأنّى يُصرفون عن الحق بعد معرفته؟ ويعلم تعالى قول رسوله وشكواه لما شاهد من عنادهم: يا رب إن هؤلاء قوم لا يؤمنون، فأمره أن يتجاوز عما يلقاه منهم وأن يقول لهم: سلام، وهو سلام متاركة لا سلام تحية، فسوف تعلمون عاقبة هذا الإصرار؛ تهديداً لهم بما ينتظرهم من أليم العذاب إن ماتوا على كفرهم.", "h": ["لا يملك الشفاعة يوم القيامة أحد إلا الله تعالى، فمن أذن له شفع ومن لم يأذن له لا يشفع، ولا يُشفع إلا لأهل التوحيد خاصة، أما أهل الشرك والكفر فلا شفاعة لهم.", "مشركو العرب على عهد النبوة موحّدون في الربوبية مشركون في العبادة.", "مشروعية الصفح والتجاوز عند العجز عن إقامة الحدود وإعلاء كلمة الله تعالى."], "k": "«إلا من شهد بالحق وهم يعلمون»… أقولها بلساني؛ فهل يعلمها قلبي يقيناً؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;